// ── SPLASH SCREEN ─────────────────────────────────────────────────────────
// Runs immediately as this script parses (script.js is the very last tag
// before </body>, so the DOM up to and including #loadingOverlay already
// exists by now, and the <link rel="stylesheet"> in <head> has already
// blocked first paint until its rules are ready) — so this replaces the
// plain "⚡ TraineeXP" + spinner ring markup with a branded splash (logo
// badge, wordmark, tagline, dot-loader) before the user ever sees the
// plain version, Duolingo/ChatGPT-style rather than a bare progress ring.
// #loadMsg keeps its id so showLoading()/hideLoading() elsewhere need no
// changes at all — it's kept in the DOM (so nothing throws) but visually
// hidden via CSS, since a Duolingo/ChatGPT-style splash shows no status
// text at all, just the brand mark + dot loader.
(function () {
  const el = document.getElementById('loadingOverlay');
  if (!el) return;
  const existingMsg = document.getElementById('loadMsg');
  const msgText = existingMsg ? existingMsg.textContent : 'Connecting to server...';
  el.innerHTML = `
    <div class="splash-badge">
      <svg class="splash-bolt" viewBox="0 0 100 100" fill="none">
        <path d="M44,16 L57,16 L41,54 L28,54 Z" fill="#ffffff"/>
        <path d="M58,16 L73,16 L53,54 L76,54 L38,90 L50,54 L31,54 Z" fill="#e85d26"/>
      </svg>
    </div>
    <div class="splash-wordmark">Triangle</div>
    <div class="splash-tagline">Level Up Your Training</div>
    <div class="splash-dots"><span></span><span></span><span></span></div>
    <div class="load-msg" id="loadMsg">${msgText}</div>`;
})();

// ╔══════════════════════════════════════════════════╗
// ║           FIREBASE REALTIME DATABASE             ║
// ║  All data stored at: traineexp-default-rtdb      ║
// ║  Every save/load goes through the internet       ║
// ╚══════════════════════════════════════════════════╝
// Reads from window.TXP_CONFIG (set by config.js, loaded before this file
// in index.html — see per-flavor config.js files for prod vs sandbox).
// The literal here is only a fallback for the rare case config.js failed
// to load, so this never silently breaks.
const FIREBASE_URL = (window.TXP_CONFIG && window.TXP_CONFIG.FIREBASE_URL) || 'https://triangle-apk-default-rtdb.firebaseio.com';

// ── Multi-org data model (Phase 2) ───────────────────────────────────────
// The app's live data used to live at a single flat /txp path with no
// organization concept at all. It now lives at organizations/{orgId}/data
// instead — the SAME layout the Direct Messaging feature already used
// from day one (see DM_ORG_ID/_dmBasePath() below), just applied to the
// main app data too. TXP_ORG_ID matches DM_ORG_ID ('org1') on purpose:
// they're the same real organization (AIO Training Program / @aiotrainees),
// so this migration doesn't touch DM data or its path at all.
//
// IMPORTANT — this only relocates where the EXISTING single organization's
// data lives; it does not yet make the classic username/password login
// (doLogin()) itself organization-aware. Every current admin/trainee
// login still resolves to this one org's data, exactly as before the
// migration. New organizations created via the Google-auth onboarding
// preview (see "AUTH & ORGANIZATION ONBOARDING") get their own real
// organizations/{orgId} records and their own real join-request data
// (see _authCreateOrganization()/_authSendPublicRequest()/etc.) — but
// routing a NEWLY approved trainee/admin into their OWN org's dashboard
// data (rather than always org1's) is the next slice of work, not part
// of this pass.
//
// IMPORTANT — before this build is installed, the live /txp data must be
// copied to organizations/org1/data using org1_migration_tool.html (run
// once in a browser, same one-time-tool pattern as reset_tool.html
// earlier) — otherwise loadDB() below will find nothing at the new path
// and treat it as a brand-new empty organization.
const TXP_ORG_ID = (window.TXP_CONFIG && window.TXP_CONFIG.ORG_ID) || 'org1';
// window.currentOrgId is the actual session-level org — set at login time
// (doLogin()/_authEnterRealApp()/session-restore, all default it to
// TXP_ORG_ID today since org1 is still the only organization with a real
// dashboard). Every fb* call already goes through _txpBasePath(), so once
// a second org gets real backing data, logging its admin/trainees in with
// a different currentOrgId is the only change needed here — nothing in
// fbRead/fbWrite/fbPatch/fbPut/the realtime listener has to change again.
function _txpBasePath() { return `organizations/${window.currentOrgId || TXP_ORG_ID}/data`; }

// ── Google Drive image proxy ─────────────────────────────────────────────
// Every image the app stores (feed/quick post photos, reward catalog
// images, rich-text description images, task/habit proof photos) used to
// be embedded as a base64 data URL straight into Firebase — which is what
// blew past the free-tier storage/bandwidth limits in the first place
// (every full-tree read re-downloads every embedded image, every time).
// Now they're uploaded to Drive via this Apps Script Web App (deployed
// under the admin's Google account, running "as them" so no device needs
// its own OAuth) and only the small returned URL string is stored in
// Firebase instead.
const DRIVE_IMAGE_PROXY_URL = 'https://script.google.com/macros/s/AKfycbxjrAHa-YcY-rUjvRl9b-aWtJsbBDeDg5UGHUqW0eqHwz0zcUg1fTJns5Y9AoGj34VR0g/exec';

// Uploads a base64 image (data URL, e.g. "data:image/jpeg;base64,...") to
// the Drive proxy and returns its public view URL. Throws on any failure —
// every call site below catches this and falls back to keeping the base64
// data URL itself, so a network hiccup during upload never means a
// silently lost photo, just one that (for that one save) didn't make it
// off Firebase yet.
// Pending uploads awaiting a callback from native — keyed by request id, so
// several concurrent uploads (e.g. a reward's square + banner crop) each
// resolve independently instead of racing.
window._driveUploadPending = window._driveUploadPending || {};
let _driveUploadReqSeq = 0;

// Native callback (see MainActivity.uploadImageToDrive() in MainActivity.kt)
window.onImageUploadResult = function (reqId, success, urlOrError) {
  const pending = window._driveUploadPending[reqId];
  if (!pending) return;
  delete window._driveUploadPending[reqId];
  if (success) pending.resolve(urlOrError);
  else pending.reject(new Error(urlOrError));
};

async function uploadImageToDrive(dataUrl, filename, folder) {
  const safeFilename = filename || ('img_' + Date.now() + '.jpg');
  const safeFolder = folder || 'misc';

  // Preferred path: hand the upload to native (MainActivity/ImageUploadHelper)
  // via plain HttpURLConnection. This exists because calling the Apps
  // Script Web App directly from here with fetch() hit a browser-CORS wall
  // — a plain address-bar visit to the same URL works fine (page
  // navigation isn't subject to CORS), which is what made this look like
  // it should work from JS too, but a fetch() call from a page loaded at
  // file:///android_asset/index.html sends an effectively null Origin that
  // Google's response didn't get correctly echoed back for, so the browser
  // silently blocked reading it and every upload failed with a generic
  // "TypeError: Failed to fetch" — confirmed via chrome://inspect. Native
  // HttpURLConnection has no concept of CORS, so it isn't affected.
  if (window.Android && typeof window.Android.uploadImageToDrive === 'function') {
    return new Promise((resolve, reject) => {
      const reqId = 'imgup' + (++_driveUploadReqSeq) + '_' + Date.now();
      window._driveUploadPending[reqId] = { resolve, reject };
      try {
        window.Android.uploadImageToDrive(reqId, dataUrl, safeFilename, safeFolder);
      } catch (e) {
        delete window._driveUploadPending[reqId];
        reject(e);
      }
    });
  }

  // Fallback (no native bridge present — e.g. opened in a plain desktop
  // browser during development): try the direct fetch() path. This will
  // hit the same CORS wall inside the real Android app, which is exactly
  // why the native path above is the real fix, but it costs nothing to
  // leave this here for a non-WebView context where CORS may not apply.
  let res;
  try {
    res = await fetch(DRIVE_IMAGE_PROXY_URL, {
      method: 'POST',
      body: JSON.stringify({ image: dataUrl, filename: safeFilename, mimeType: 'image/jpeg', folder: safeFolder })
    });
  } catch (networkErr) {
    console.error('[uploadImageToDrive] fetch() fallback threw before any response:', networkErr, 'url:', DRIVE_IMAGE_PROXY_URL);
    throw networkErr;
  }
  if (!res.ok) {
    let bodyText = '';
    try { bodyText = await res.text(); } catch (e) {}
    console.error('[uploadImageToDrive] fetch() fallback non-OK HTTP response:', res.status, 'body:', bodyText.slice(0, 500));
    throw new Error('Drive upload failed: ' + res.status);
  }
  const json = await res.json();
  if (!json.success) throw new Error(json.error || 'Drive upload failed');
  return json.url;
}

// ─── SHA-256 — WebCrypto with pure-JS fallback for Android WebView / file:// ──
// crypto.subtle requires a secure context (HTTPS). When loaded from file:// in
// a WebView it is unavailable, so we fall back to a self-contained JS implementation.
async function sha256(message) {
  if (window.crypto && window.crypto.subtle) {
    try {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(message));
      return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2,'0')).join('');
    } catch(e) { /* fall through to JS impl */ }
  }
  return _sha256js(message);
}

// Compact pure-JS SHA-256 (no dependencies, no external libs)
function _sha256js(str) {
  function rr(v,a){return(v>>>a)|(v<<(32-a));}
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
           0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
           0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
           0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
           0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
           0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
           0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
           0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bytes=new TextEncoder().encode(str);
  const L=bytes.length;
  const bitLen=L*8;
  const padLen=((L+8)>>6)*64+64;
  const msg=new Uint8Array(padLen);
  msg.set(bytes);
  msg[L]=0x80;
  const view=new DataView(msg.buffer);
  view.setUint32(padLen-4,bitLen&0xffffffff,false);
  view.setUint32(padLen-8,Math.floor(bitLen/2**32),false);
  for(let i=0;i<padLen;i+=64){
    const w=new Array(64);
    for(let j=0;j<16;j++) w[j]=view.getUint32(i+j*4,false);
    for(let j=16;j<64;j++){
      const s0=rr(w[j-15],7)^rr(w[j-15],18)^(w[j-15]>>>3);
      const s1=rr(w[j-2],17)^rr(w[j-2],19)^(w[j-2]>>>10);
      w[j]=(w[j-16]+s0+w[j-7]+s1)|0;
    }
    let [a,b,c,d,e,f,g,hh]=h;
    for(let j=0;j<64;j++){
      const S1=rr(e,6)^rr(e,11)^rr(e,25);
      const ch=(e&f)^(~e&g);
      const t1=(hh+S1+ch+K[j]+w[j])|0;
      const S0=rr(a,2)^rr(a,13)^rr(a,22);
      const maj=(a&b)^(a&c)^(b&c);
      const t2=(S0+maj)|0;
      hh=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0;
    }
    h=[h[0]+a,h[1]+b,h[2]+c,h[3]+d,h[4]+e,h[5]+f,h[6]+g,h[7]+hh].map(v=>v|0);
  }
  return h.map(v=>(v>>>0).toString(16).padStart(8,'0')).join('');
}

// ─── XSS sanitiser — use on ALL user-supplied content before innerHTML ────────
function sanitize(str) {
  const d = document.createElement('div');
  d.textContent = String(str ?? '');
  return d.innerHTML;
}

// ── Rich description sanitizer ──────────────────────────────────────────
// Task/habit descriptions written in the rich text editor (openDescEditor)
// are stored as HTML. This allowlist-based cleaner strips any tag/attribute
// not explicitly permitted before the HTML is ever rendered with innerHTML,
// so stored content can't carry scripts, handlers, or other unsafe markup.
const _RICH_TAG_OK = new Set(['B','STRONG','I','EM','U','BR','DIV','SPAN','P','UL','OL','LI','H1','H2','H3','IMG','SUB','SUP']);
const _RICH_FULL_STRIP = new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','LINK','META','FORM','SVG']);
const _RICH_ATTR_OK = { SPAN:['style'], DIV:['style','class'], LI:['class'], IMG:['src','style','alt'] };
function sanitizeRichHtml(html) {
  const root = document.createElement('div');
  root.innerHTML = String(html ?? '');
  (function walk(el) {
    Array.from(el.children).forEach(child => {
      const tag = child.tagName;
      if (_RICH_FULL_STRIP.has(tag)) { child.remove(); return; }
      walk(child);
      if (tag === 'INPUT') {
        if (child.getAttribute('type') !== 'checkbox') { child.remove(); return; }
        Array.from(child.attributes).forEach(a => { if (a.name!=='type' && a.name!=='checked') child.removeAttribute(a.name); });
        return;
      }
      if (!_RICH_TAG_OK.has(tag)) {
        while (child.firstChild) child.parentNode.insertBefore(child.firstChild, child);
        child.remove();
        return;
      }
      const allowed = _RICH_ATTR_OK[tag] || [];
      Array.from(child.attributes).forEach(a => {
        if (/^on/i.test(a.name)) { child.removeAttribute(a.name); return; }
        if (!allowed.includes(a.name)) { child.removeAttribute(a.name); return; }
        if (a.name === 'style' && /expression|javascript:/i.test(a.value)) child.removeAttribute('style');
        if (a.name === 'src' && !/^data:image\//i.test(a.value)) child.removeAttribute('src');
      });
    });
  })(root);
  return root.innerHTML;
}
// Plain-text snippet of a rich description, for previews/list rows.
function richTextPreview(html, maxLen) {
  maxLen = maxLen || 60;
  const d = document.createElement('div');
  d.innerHTML = String(html ?? '');
  const txt = (d.textContent || '').replace(/\s+/g,' ').trim();
  return txt.length > maxLen ? txt.slice(0, maxLen) + '…' : txt;
}
// Full (non-truncated) plain-text extraction — used by the legacy quick-edit
// textareas so they never show raw HTML tags from a rich description.
function richTextPlain(html) {
  const d = document.createElement('div');
  d.innerHTML = String(html ?? '');
  return (d.textContent || '').trim();
}
// Flattens a rich description into a single line while *keeping* inline
// formatting (bold/italic/underline/font colour/highlight) — used for the
// one-line description preview row in the create-task/habit panels, so you
// can actually see that formatting was applied instead of just plain text.
// Block structure (headings, list items, paragraphs) collapses into simple
// spacing; images and checklist checkboxes are dropped since they can't be
// meaningfully shown in a single clipped line.
const _RTE_INLINE_TAGS = { B:'b', STRONG:'b', I:'i', EM:'i', U:'u', SPAN:'span', SUB:'sub', SUP:'sup' };
function richInlinePreview(html) {
  const root = document.createElement('div');
  root.innerHTML = sanitizeRichHtml(html);
  const out = document.createElement('span');
  (function walk(node, target) {
    Array.from(node.childNodes).forEach(child => {
      if (child.nodeType === 3) { target.appendChild(document.createTextNode(child.textContent)); return; }
      if (child.nodeType !== 1) return;
      const tag = child.tagName;
      if (tag === 'IMG' || tag === 'INPUT') return; // can't show these in one flat line
      const inline = _RTE_INLINE_TAGS[tag];
      if (inline) {
        const clone = document.createElement(inline);
        if (child.hasAttribute('style')) clone.setAttribute('style', child.getAttribute('style'));
        target.appendChild(clone);
        walk(child, clone);
        return;
      }
      // Block-level element (div/p/h1-h3/li/ul/ol/etc.) — flatten its
      // children onto the same line, then add a separating space so
      // different lines/list items don't visually run together.
      walk(child, target);
      if (target.lastChild) target.appendChild(document.createTextNode(' '));
    });
  })(root, out);
  return out.innerHTML.trim();
}

// Returns black or white depending on bg luminance for readable text
function _contrastColor(hex) {
  try {
    const h = hex.replace('#','');
    const r = parseInt(h.substring(0,2),16);
    const g = parseInt(h.substring(2,4),16);
    const b = parseInt(h.substring(4,6),16);
    const lum = (0.299*r + 0.587*g + 0.114*b) / 255;
    return lum > 0.45 ? '#1a1d23' : '#ffffff';
  } catch(e) { return '#ffffff'; }
}
function _nameShadow(hex) {
  try {
    const h = hex.replace('#','');
    const r = parseInt(h.substring(0,2),16);
    const g = parseInt(h.substring(2,4),16);
    const b = parseInt(h.substring(4,6),16);
    const lum = (0.299*r + 0.587*g + 0.114*b) / 255;
    return lum > 0.45 ? '0 1px 4px rgba(255,255,255,.4)' : '0 1px 6px rgba(0,0,0,.55)';
  } catch(e) { return 'none'; }
}

