// Logs a Google-authenticated user into the REAL app (main dashboard, real
// live db) — the same session setup doLogin() does after a successful
// username/password check, minus the credential check itself. Currently
// only ever called for org1's admin (the one organization with real
// backing data), since a brand-new org created through the wizard doesn't
// have its own dashboard/data yet — see the TXP_ORG_ID comment near
// FIREBASE_URL for what's still deferred there.
async function _authEnterRealApp(user, orgId) {
  orgId = orgId || TXP_ORG_ID;
  showLoading('Connecting to server...');
  try {
    window.currentOrgId = orgId;
    await _refreshInternsRoster(orgId); // before loadDB() — see comment on _refreshInternsRoster
    await loadDB();
    hideLoading();
    currentUser = user;
    currentRole = user.role || 'intern';
    restoreColorTheme(); // apply THIS trainee's own saved color theme, not whoever was last on this device
    try { localStorage.setItem('txp_session', JSON.stringify({ id: user.id, name: user.name, username: user.username, role: user.role || null, orgId })); } catch(e) {}
    document.getElementById('authScreen').classList.remove('active');
    document.getElementById('mainScreen').classList.add('active');
    const firstName = user.name.split(' ')[0];
    document.getElementById('topFirstName') && (document.getElementById('topFirstName').textContent = sanitize(firstName));
    document.getElementById('topName') && (document.getElementById('topName').textContent = sanitize(user.name));
    document.getElementById('topRole').textContent = currentRole === 'admin' ? 'Administrator' : 'Intern';
    (function() {
      const av = document.getElementById('topAvatar');
      if (!av) return;
      const avCfg = db?.submissions?.[user.id]?.avatar || {};
      const avUrl = buildAvatarUrl(avCfg);
      av.innerHTML = '';
      av.style.background = 'none';
      av.style.overflow = 'hidden';
      av.style.padding = '0';
      const img = document.createElement('img');
      img.src = avUrl;
      img.style.cssText = 'width:100%;height:100%;object-fit:cover;object-position:top center;border-radius:50%;';
      img.onerror = () => { av.textContent = user.name[0]; av.style.background = 'var(--accent)'; };
      av.insertBefore(img, av.firstChild);
    })();
    window.taskFilter = 'Today'; window.adminTaskFilter = 'Sent';
    window.adminSelectedIntern = null; window.atFilterAssignee = ''; window.atFilterCat = '';
    renderSidebar();
    startRepeatTimer();
    _dmSubscribeUnreadBadge();
    _thStartRealtime();
    if (currentRole === 'admin') _refreshPendingJoinReqCount();
    if (window.lucide) lucide.createIcons(); initCarousels();
    clearAndroidHistory();
    await navigateTo(currentRole === 'admin' ? 'adminDashboard' : 'internDashboard', { replace: true });
    registerDeviceToken();
    notifyAndroidAppReady();
    maybeAutoBackup();
  } catch (e) {
    hideLoading();
    showToast('Could not load your organization: ' + (e?.message || e), 'error');
  }
}

function _authPickRole(role) {
  if (role === 'admin') {
    _authPickAdminRole();
  } else if (role === 'individual') {
    _authCreateIndividualAccount();
  } else {
    showAuthScreen('traineeFindOrg', { role });
  }
}

// ── Individual flow ─────────────────────────────────────────────────────
// "Individual" is implemented as a normal organization with exactly one
// member (this person) — reuses 100% of the existing
// organizations/{orgId}/data storage, task/habit/reward code, and backup/
// restore, with no new Firebase schema at all (same reasoning as
// _authCreateOrganization() just below). The only differences from a
// normal admin-created org: no name/username/visibility questions, no
// join-request step at all — create it and go straight into the
// dashboard. role is stored as 'individual' (not 'admin') so the UI layer
// can hide multi-person-only screens (Leaderboard, Feed, Chat, Complaints,
// Join Requests, the hamburger side-drawer) and the task/habit/reward
// creation forms can skip their Assign To sections — see the
// currentRole === 'individual' checks throughout this file.
async function _authCreateIndividualAccount() {
  const f = window._authFlow;
  if (!f.uid) { showToast('Please sign in again', 'error'); showAuthScreen('welcome'); return; }
  showLoading('Setting up your space...');
  try {
    const { color: orgColor, icon: orgIcon } = await _nextOrgIconAndColor();
    const displayName = f.googleName || 'My';
    const newOrgId = await fbPost('organizations', {
      name: `${displayName}'s Space`,
      username: null,
      visibility: 'private',
      type: 'individual',
      adminId: f.uid,
      createdAt: Date.now(),
      status: 'Active',
      icon: orgIcon,
      color: orgColor
    });
    await fbRootPut('users/' + f.uid, {
      name: f.googleName || '', email: f.googleEmail || '',
      role: 'individual', orgId: newOrgId, createdAt: Date.now()
    });
    hideLoading();
    const user = { id: f.uid, name: f.googleName || '', username: f.googleEmail || f.uid, role: 'individual' };
    await _authEnterRealApp(user, newOrgId);
  } catch (e) {
    hideLoading();
    console.error('[_authCreateIndividualAccount] failed:', e);
    showToast('Could not set up your space: ' + e.message, 'error');
  }
}

// If org1 (the one real, already-migrated organization) hasn't been
// claimed by any real Google account yet — its adminId is still the
// legacy numeric placeholder (99) written by the migration tool, not a
// Firebase uid — the FIRST admin to pick "I'm an Admin" claims it and is
// logged straight into the real dashboard, instead of going through the
// "create a brand new organization" wizard (which would be wrong here:
// org1 already exists, it just didn't have a real Google identity linked
// to it yet). Once claimed, every subsequent Google sign-in recognizes
// this uid via users/{uid} and routes straight into the real dashboard
// too (see onGoogleAuthResult()'s existing-admin branch).
async function _authPickAdminRole() {
  const f = window._authFlow;
  try {
    const currentAdminId = await fbRootGet(`organizations/${TXP_ORG_ID}/adminId`);
    if (typeof currentAdminId !== 'string' && f.uid) {
      await fbRootPut(`organizations/${TXP_ORG_ID}/adminId`, f.uid);
      await fbRootPut('users/' + f.uid, {
        name: f.googleName || '', email: f.googleEmail || '',
        role: 'admin', orgId: TXP_ORG_ID, createdAt: Date.now()
      });
      showToast('Linked your Google account to AIO Training Program');
      // Log in as the REAL signed-in person, not the legacy id:99 fixture
      // this org used before any real account claimed its admin slot —
      // _refreshInternsRoster() (called inside _authEnterRealApp) now
      // recognizes this uid as the real admin too, once users/{uid} above
      // has landed.
      const adminUser = { id: f.uid, name: f.googleName || 'Admin', username: f.googleEmail || f.uid, role: 'admin' };
      await _authEnterRealApp(adminUser);
      return;
    }
  } catch (e) {
    console.error('[_authPickAdminRole] org1 claim check failed:', e);
    // fall through to the normal "create a new organization" wizard —
    // better to let them create a new org than get stuck on a network hiccup
  }
  showAuthScreen('adminOrgName', { role: 'admin' });
}

function _authRenderAdminOrgName() {
  return `
    <div class="auth-card">
      <div class="onb-icon-circle onb-icon-circle--building">${_AUTH_BUILDING_ICON_SVG}</div>
      <div class="auth-sub" style="margin-bottom:14px;">What is your organization name?</div>
      <input type="text" class="auth-input" id="authOrgNameInput" placeholder="AIO Training Program" value="${(window._authFlow.orgName||'').replace(/"/g,'&quot;')}" oninput="_authValidateOrgName()">
      <div class="auth-hint" id="authOrgNameHint">&nbsp;</div>
      <button class="auth-btn auth-btn--primary" id="authOrgNameBtn" ${window._authFlow.orgName ? '' : 'disabled'} onclick="_authContinueOrgName()">Continue</button>
    </div>`;
}
function _authValidateOrgName() {
  const v = document.getElementById('authOrgNameInput').value.trim();
  const hint = document.getElementById('authOrgNameHint');
  const btn = document.getElementById('authOrgNameBtn');
  if (v.length > 0 && v.length < 3) { hint.textContent = 'Organization name is too short'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true; return; }
  if (v.length > 60) { hint.textContent = 'Organization name is too long (max 60 characters)'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true; return; }
  hint.textContent = ' '; hint.className = 'auth-hint';
  btn.disabled = !v;
}
function _authContinueOrgName() {
  const v = document.getElementById('authOrgNameInput').value.trim();
  if (!v) return;
  showAuthScreen('adminUsername', { orgName: v });
}

function _slugifyOrgUsername(v) {
  return '@' + v.toLowerCase().replace(/^@/, '').replace(/[^a-z0-9_]/g, '');
}
function _authRenderAdminUsername() {
  const suggested = window._authFlow.orgUsername || _slugifyOrgUsername(window._authFlow.orgName || '');
  return `
    <div class="auth-card">
      <div class="onb-icon-circle" style="margin-top:14px;"><i data-lucide="at-sign"></i></div>
      <div class="auth-sub" style="margin-bottom:14px;">Create a unique username for your organization.</div>
      <input type="text" class="auth-input" id="authOrgUserInput" placeholder="@aiotrainees" value="${suggested}" oninput="_authValidateOrgUsername()">
      <div class="auth-hint" id="authOrgUserHint">This will be your organization's unique identity on Triangle</div>
      <button class="auth-btn auth-btn--primary" id="authOrgUserBtn" onclick="_authContinueOrgUsername()">Continue</button>
    </div>`;
}
// Real uniqueness check against orgUsernames/{username} — reserved names
// (matching the existing live org, plus generic reserved words) are
// rejected without a network round trip; everything else is a genuine
// Firebase lookup.
const _RESERVED_USERNAMES = ['@admin', '@triangle', '@support', '@help'];
let _authUsernameCheckSeq = 0;
async function _authValidateOrgUsername() {
  const raw = document.getElementById('authOrgUserInput').value;
  const v = _slugifyOrgUsername(raw);
  document.getElementById('authOrgUserInput').value = v;
  const hint = document.getElementById('authOrgUserHint');
  const btn = document.getElementById('authOrgUserBtn');
  const bare = v.slice(1);
  if (!bare) { hint.textContent = "This will be your organization's unique identity on Triangle"; hint.className = 'auth-hint'; btn.disabled = true; return; }
  if (bare.length < 3) { hint.textContent = 'Username must be at least 3 characters'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true; return; }
  if (_RESERVED_USERNAMES.includes(v)) { hint.textContent = 'Username already taken'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true; return; }
  const mySeq = ++_authUsernameCheckSeq;
  hint.textContent = 'Checking availability…'; hint.className = 'auth-hint'; btn.disabled = true;
  try {
    const existingOrgId = await fbRootGet('orgUsernames/' + _orgUsernameKey(v));
    if (mySeq !== _authUsernameCheckSeq) return; // a newer keystroke's check already superseded this one
    if (existingOrgId) {
      hint.textContent = 'Username already taken'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true;
    } else {
      hint.textContent = 'Available'; hint.className = 'auth-hint auth-hint--available'; btn.disabled = false;
    }
  } catch (e) {
    if (mySeq !== _authUsernameCheckSeq) return;
    hint.textContent = 'Could not check availability — try again'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true;
  }
}
function _authContinueOrgUsername() {
  const v = document.getElementById('authOrgUserInput').value;
  if (!v || v === '@') return;
  showAuthScreen('adminVisibility', { orgUsername: v });
}

function _authRenderAdminVisibility() {
  const vis = window._authFlow.visibility;
  return `
    <div class="auth-card">
      <div class="onb-icon-circle" style="margin-top:14px;"><i data-lucide="shield-check"></i></div>
      <div class="auth-sub" style="margin-bottom:16px;">Who can see your organization?</div>
      <div class="vis-option ${vis==='public'?'is-selected':''}" onclick="_authSetVisibility('public')">
        <div class="vis-option-icon"><i data-lucide="globe"></i></div>
        <div><div class="vis-option-title">Public</div><div class="vis-option-sub">Anyone can find and request to join your organization.</div></div>
      </div>
      <div class="vis-option ${vis==='private'?'is-selected':''}" onclick="_authSetVisibility('private')">
        <div class="vis-option-icon"><i data-lucide="lock"></i></div>
        <div><div class="vis-option-title">Private</div><div class="vis-option-sub">Only trainees who know your organization username can request to join.</div></div>
      </div>
      <button class="auth-btn auth-btn--primary" onclick="_authCreateOrganization()">Create Organization</button>
    </div>`;
}
function _authSetVisibility(v) {
  window._authFlow.visibility = v;
  renderAuthScreen();
}
async function _authCreateOrganization() {
  const f = window._authFlow;
  const btn = document.querySelector('#authContent .auth-btn--primary');
  if (btn) { btn.disabled = true; btn.textContent = 'Creating…'; }
  try {
    // Re-check the username hasn't been taken by someone else in the gap
    // since Step 2 — genuinely possible now that this is a real shared
    // database instead of local mock state.
    const existingOrgId = await fbRootGet('orgUsernames/' + _orgUsernameKey(f.orgUsername));
    if (existingOrgId) {
      showToast('That username was just taken — pick another', 'error');
      showAuthScreen('adminUsername');
      return;
    }
    const { color: orgColor, icon: orgIcon } = await _nextOrgIconAndColor();
    const newOrgId = await fbPost('organizations', {
      name: f.orgName,
      username: f.orgUsername,
      visibility: f.visibility,
      adminId: f.uid || null,
      createdAt: Date.now(),
      status: 'Active',
      icon: orgIcon,
      color: orgColor
    });
    await fbRootPut('orgUsernames/' + _orgUsernameKey(f.orgUsername), newOrgId);
    if (f.uid) {
      await fbRootPut('users/' + f.uid, {
        name: f.googleName || '', email: f.googleEmail || '',
        role: 'admin', orgId: newOrgId, createdAt: Date.now()
      });
    }
    showAuthScreen('adminSuccess', { orgId: newOrgId });
  } catch (e) {
    console.error('[_authCreateOrganization] failed:', e);
    showToast('Could not create organization: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Create Organization'; }
  }
}

function _authRenderAdminSuccess() {
  const f = window._authFlow;
  return `
    <div class="auth-card">
      <div class="auth-success-icon"><i data-lucide="check"></i></div>
      <div class="auth-title">You're All Set!</div>
      <div class="auth-sub">Your organization has been created successfully.</div>
      <div class="auth-summary-card">
        <div class="auth-summary-row"><span class="auth-summary-label">Organization Name</span><span class="auth-summary-value">${f.orgName}</span></div>
        <div class="auth-summary-row"><span class="auth-summary-label">Username</span><span class="auth-summary-value">${f.orgUsername}</span></div>
        <div class="auth-summary-row"><span class="auth-summary-label">Visibility</span><span class="auth-summary-value">${f.visibility === 'public' ? '🌐 Public' : '🔒 Private'}</span></div>
      </div>
      <button class="auth-btn auth-btn--primary" onclick="_authGoToRealDashboard()">Go to Dashboard</button>
      <div class="auth-link-row"><a onclick="showAuthScreen('adminRequests')">View Join Requests →</a></div>
    </div>`;
}

// Every fb* call already goes through _txpBasePath(), which reads from
// window.currentOrgId (see that function's comment near the top of this
// file) — so a brand-new organization already has real per-org backing
// data the moment it's created; nothing else needed building. This used
// to be a placeholder toast ("lands with the next phase") because that
// wiring hadn't been connected here yet — it now just calls
// _authEnterRealApp() (the same entry point every other real sign-in
// path already uses) with this admin's real identity and the org they
// just created.
async function _authGoToRealDashboard() {
  const f = window._authFlow;
  if (!f.uid || !f.orgId) {
    showToast('Could not open your dashboard — missing account info. Please sign in again.', 'error');
    return;
  }
  const adminUser = { id: f.uid, name: f.googleName || 'Admin', username: f.googleEmail || f.uid, role: 'admin' };
  await _authEnterRealApp(adminUser, f.orgId);
}

// ── Trainee flow ─────────────────────────────────────────────────────────
// Real Firebase reads now — GET organizations.json once per visit to this
// screen, filtered client-side to public+Active orgs (fine at this scale;
// a proper indexed query is unnecessary until there are hundreds of orgs).
function _authRenderTraineeFindOrg() {
  // Search icon uses a CLASS selector in CSS (.org-search-icon), not a bare
  // "i" tag selector — lucide.createIcons() replaces this <i> with an
  // <svg>, so anything styled only via the "i" tag stops matching (and
  // stops being positioned) the moment the icon renders. That was also
  // why the field looked "broken": the unstyled, unsized icon sat as a
  // block element above the input instead of inline inside it.
  // "Can't find your organization?" used to be its own separate button
  // that led to the exact same screen as "Request Private Organization"
  // right below it — two controls for one destination. Trimmed to a
  // single plain-text nudge above the one real CTA.
  return `
    <div class="auth-card auth-card--left">
      <div class="org-search-wrap">
        <i data-lucide="search" class="org-search-icon"></i>
        <input type="text" class="org-search-input" id="authOrgSearchInput" placeholder="Search organizations..." oninput="_authRenderOrgListOnly()">
      </div>
      <div class="auth-section-label">Public Organizations</div>
      <div id="authOrgListWrap" style="width:100%;">${_authOrgListHtml('')}</div>
      <div class="org-private-hint">Don't see your organization? It may be private.</div>
      <button class="auth-btn auth-btn--green" onclick="showAuthScreen('traineeRequestPrivate')">Request Private Organization</button>
    </div>`;
}
async function _authLoadPublicOrgs() {
  const wrap = document.getElementById('authOrgListWrap');
  if (wrap) wrap.innerHTML = '<div class="req-empty">Loading organizations…</div>';
  try {
    const all = await fbRootGet('organizations') || {};
    window._authFlow.publicOrgsCache = Object.keys(all)
      .map(orgId => ({ orgId, ...all[orgId] }))
      .filter(o => o.visibility === 'public' && o.status === 'Active');
  } catch (e) {
    console.error('[_authLoadPublicOrgs] failed:', e);
    window._authFlow.publicOrgsCache = [];
    if (wrap) wrap.innerHTML = '<div class="req-empty">Could not load organizations — check your connection</div>';
    return;
  }
  const searchInput = document.getElementById('authOrgSearchInput');
  _authRenderOrgListOnly(searchInput ? searchInput.value : '');
}
function _authOrgListHtml(filter) {
  const f = (filter || '').toLowerCase();
  const orgs = (window._authFlow.publicOrgsCache || []).filter(o => !f || (o.name||'').toLowerCase().includes(f) || (o.username||'').toLowerCase().includes(f));
  if (!orgs.length) return `<div class="req-empty">No organizations match "${filter}"</div>`;
  return orgs.map(o => `
    <div class="org-list-item">
      ${_orgAvatarHtml(o)}
      <div><div class="org-list-name">${o.name}</div><div class="org-list-username">${o.username}</div></div>
      <button class="org-req-btn" id="orgReq_${o.orgId}" onclick="_authSendPublicRequest('${o.orgId}', this)">Send Request</button>
    </div>`).join('');
}
function _authRenderOrgListOnly(presetValue) {
  const input = document.getElementById('authOrgSearchInput');
  const v = presetValue !== undefined ? presetValue : (input ? input.value : '');
  document.getElementById('authOrgListWrap').innerHTML = _authOrgListHtml(v);
  if (window.lucide) lucide.createIcons();
}
async function _authSendPublicRequest(orgId, btnEl) {
  const org = (window._authFlow.publicOrgsCache || []).find(o => o.orgId === orgId);
  if (!org) return;
  if (btnEl) { btnEl.disabled = true; btnEl.textContent = 'Sending…'; }
  await _authSubmitJoinRequest(org, btnEl);
}

function _authRenderTraineeRequestPrivate() {
  const found = window._authFlow.foundPrivateOrg;
  return `
    <div class="auth-card">
      <div class="onb-icon-circle onb-icon-circle--green" style="margin-top:14px;"><i data-lucide="lock"></i></div>
      <div class="auth-sub" style="margin-bottom:14px;">Enter the organization username to send a join request</div>
      <input type="text" class="auth-input" id="authPrivateUserInput" placeholder="@privateorg" value="${window._authFlow.privateUsernameInput||''}" oninput="_authValidatePrivateOrg()">
      <div class="auth-hint" id="authPrivateHint">Ask your organization admin for the username</div>
      ${found ? `
        <div class="org-list-item" style="margin-top:6px;">
          ${_orgAvatarHtml(found)}
          <div><div class="org-list-name">${found.name}</div><div class="org-list-username">${found.username}</div></div>
        </div>` : ''}
      <button class="auth-btn auth-btn--green" id="authPrivateSendBtn" disabled onclick="_authSendPrivateRequest()">Send Request</button>
      <div class="auth-link-row"><a class="is-green" onclick="showAuthScreen('traineeFindOrg')">← Back to organization list</a></div>
    </div>`;
}
let _authPrivateCheckSeq = 0;
async function _authValidatePrivateOrg() {
  const raw = document.getElementById('authPrivateUserInput').value;
  const v = _slugifyOrgUsername(raw);
  document.getElementById('authPrivateUserInput').value = v;
  window._authFlow.privateUsernameInput = v;
  const hint = document.getElementById('authPrivateHint');
  const btn = document.getElementById('authPrivateSendBtn');
  window._authFlow.foundPrivateOrg = null;
  if (v.length <= 1) { hint.textContent = 'Ask your organization admin for the username'; hint.className = 'auth-hint'; btn.disabled = true; return; }
  const mySeq = ++_authPrivateCheckSeq;
  hint.textContent = 'Looking up organization…'; hint.className = 'auth-hint'; btn.disabled = true;
  try {
    const orgId = await fbRootGet('orgUsernames/' + _orgUsernameKey(v));
    if (mySeq !== _authPrivateCheckSeq) return; // superseded by a newer keystroke
    if (!orgId) {
      hint.textContent = 'Organization not found. Check the username and try again.'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true;
      renderAuthScreen(); _authRefocusPrivateInput(v); return;
    }
    const org = await fbRootGet('organizations/' + orgId);
    if (mySeq !== _authPrivateCheckSeq) return;
    if (!org) {
      hint.textContent = 'Organization not found. Check the username and try again.'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true;
    } else if (org.visibility === 'public') {
      hint.textContent = 'This organization is public. You can find it in the organization list.'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true;
    } else {
      hint.textContent = 'Organization found'; hint.className = 'auth-hint auth-hint--available'; btn.disabled = false;
      window._authFlow.foundPrivateOrg = { orgId, name: org.name, username: org.username };
    }
  } catch (e) {
    if (mySeq !== _authPrivateCheckSeq) return;
    hint.textContent = 'Could not check that username — try again'; hint.className = 'auth-hint auth-hint--taken'; btn.disabled = true;
  }
  renderAuthScreen();
  _authRefocusPrivateInput(v);
}
function _authRefocusPrivateInput(v) {
  const input = document.getElementById('authPrivateUserInput');
  if (input) { input.focus(); input.setSelectionRange(v.length, v.length); }
}
async function _authSendPrivateRequest() {
  const org = window._authFlow.foundPrivateOrg;
  if (!org) return;
  const btn = document.getElementById('authPrivateSendBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
  await _authSubmitJoinRequest(org, btn);
}

// Shared by both the public "Send Request" button and the private-org
// flow — real write to organizations/{orgId}/joinRequests, with a real
// duplicate-pending check (BR-10: no duplicate pending requests) instead
// of a mock array lookup.
async function _authSubmitJoinRequest(org, btnEl) {
  const f = window._authFlow;
  if (!f.uid) {
    showToast('Please sign in with Google again before sending a request', 'error');
    if (btnEl) { btnEl.disabled = false; btnEl.textContent = 'Send Request'; }
    return;
  }
  try {
    const existing = await fbRootGet(`organizations/${org.orgId}/joinRequests`) || {};
    const alreadyPending = Object.values(existing).some(r => r && r.traineeUid === f.uid && r.status === 'pending');
    if (alreadyPending) {
      showToast('Your request is already pending', 'error');
      if (btnEl) { btnEl.disabled = false; btnEl.textContent = 'Send Request'; }
      return;
    }
    const alreadyMember = Object.values(existing).some(r => r && r.traineeUid === f.uid && r.status === 'approved');
    if (alreadyMember) {
      showToast('You are already a member of this organization', 'error');
      if (btnEl) { btnEl.disabled = false; btnEl.textContent = 'Send Request'; }
      return;
    }
    const reqId = await fbPost(`organizations/${org.orgId}/joinRequests`, {
      traineeUid: f.uid,
      traineeName: f.googleName || f.googleEmail || 'Unknown',
      traineeEmail: f.googleEmail || '',
      status: 'pending',
      createdAt: Date.now()
    });
    showAuthScreen('traineeRequestSent', { pendingOrg: Object.assign({}, org, { reqId }) });
  } catch (e) {
    console.error('[_authSubmitJoinRequest] failed:', e);
    showToast('Could not send request: ' + e.message, 'error');
    if (btnEl) { btnEl.disabled = false; btnEl.textContent = 'Send Request'; }
  }
}

function _authRenderTraineeRequestSent() {
  const org = window._authFlow.pendingOrg || {};
  return `
    <div class="auth-card">
      <div class="onb-icon-circle onb-icon-circle--green"><i data-lucide="send"></i></div>
      <div class="auth-title">Request Sent!</div>
      <div class="auth-sub">Your request has been sent to the organization admin.</div>
      <div class="auth-summary-card">
        <div class="auth-summary-row"><span class="auth-summary-label">Organization</span><span class="auth-summary-value">${org.name || ''}</span></div>
        <div class="auth-summary-row"><span class="auth-summary-label">Username</span><span class="auth-summary-value">${org.username || ''}</span></div>
      </div>
      <button class="auth-btn auth-btn--green" onclick="_authCheckRequestStatus()">Check Status</button>
      <button class="auth-btn" onclick="_closeAuthPreview()">Back to Home</button>
    </div>`;
}
async function _authCheckRequestStatus() {
  const org = window._authFlow.pendingOrg;
  if (!org || !org.orgId || !org.reqId) { showToast('Nothing to check yet'); return; }
  try {
    const req = await fbRootGet(`organizations/${org.orgId}/joinRequests/${org.reqId}`);
    if (!req) { showToast('Request not found'); return; }
    if (req.status === 'approved') {
      showAuthScreen('traineeWelcome');
    } else if (req.status === 'denied') {
      showToast('Your request to join ' + org.name + ' was not approved', 'error');
    } else {
      showToast('Still pending — the admin hasn\'t reviewed it yet');
    }
  } catch (e) {
    showToast('Could not check status: ' + e.message, 'error');
  }
}

function _authRenderTraineeWelcome() {
  const org = window._authFlow.pendingOrg || { name: 'your organization', username: '' };
  return `
    <div class="auth-card">
      <div class="welcome-emoji">👋</div>
      <div class="auth-title">Welcome to ${org.name}!</div>
      <div class="auth-sub">You're now part of<br><strong style="color:var(--text);">${org.username}</strong></div>
      <div class="auth-sub">Let's learn, grow, and achieve together.</div>
      <button class="auth-btn auth-btn--green" onclick="_authGoToHomeFromWelcome()">Go to Home</button>
    </div>`;
}
// Every org has real backing data now (see _authGoToRealDashboard()'s
// comment above, which generalized the admin creation path the same way)
// — this used to only work for TXP_ORG_ID and fell back to a placeholder
// toast for any other organization. Just hand this trainee's real
// identity and their actual org id to _authEnterRealApp(); nothing else
// to build, _txpBasePath() already scopes every read/write to whatever
// window.currentOrgId is set to.
function _authGoToHomeFromWelcome() {
  const f = window._authFlow;
  const org = f.pendingOrg;
  if (org && org.orgId && f.uid) {
    _authEnterRealApp({ id: f.uid, name: f.googleName || '', username: f.googleEmail || f.uid }, org.orgId);
  } else {
    showToast('Could not open your dashboard — missing account info. Please sign in again.', 'error');
  }
}

// ── Admin: Join Requests ──────────────────────────────────────────────────
// Real reads/writes against organizations/{orgId}/joinRequests. Requires
// window._authFlow.orgId (set right after this admin created their
// organization in this same session — see _authCreateOrganization()).
function _authRenderAdminRequests() {
  const tab = window._authFlow.reqTab;
  return `
    <div class="auth-card auth-card--left">
      <div class="auth-title">Join Requests</div>
      <div class="req-tabs" style="margin-top:16px;">
        <div class="req-tab ${tab==='pending'?'is-active':''}" onclick="_authSetReqTab('pending')">Pending${window._authFlow.joinRequests.pending.length ? ' ('+window._authFlow.joinRequests.pending.length+')' : ''}</div>
        <div class="req-tab ${tab==='history'?'is-active':''}" onclick="_authSetReqTab('history')">History</div>
      </div>
      <div id="authReqListWrap" style="width:100%;"><div class="req-empty">Loading…</div></div>
      <button class="auth-btn" style="margin-top:6px;" onclick="showAuthScreen('adminSuccess')">← Back</button>
    </div>`;
}
async function _authLoadJoinRequests() {
  const f = window._authFlow;
  const wrap = document.getElementById('authReqListWrap');
  if (!f.orgId) {
    if (wrap) wrap.innerHTML = '<div class="req-empty">No organization yet in this session</div>';
    return;
  }
  try {
    const all = await fbRootGet(`organizations/${f.orgId}/joinRequests`) || {};
    const entries = Object.keys(all).map(reqId => ({ reqId, ...all[reqId] }));
    f.joinRequests = {
      pending: entries.filter(r => r.status === 'pending').sort((a,b) => (a.createdAt||0)-(b.createdAt||0)),
      history: entries.filter(r => r.status === 'approved' || r.status === 'denied').sort((a,b) => (b.reviewedAt||0)-(a.reviewedAt||0))
    };
  } catch (e) {
    console.error('[_authLoadJoinRequests] failed:', e);
    if (wrap) wrap.innerHTML = '<div class="req-empty">Could not load requests — check your connection</div>';
    return;
  }
  if (wrap) wrap.innerHTML = _authReqListHtml();
  // Refresh just the Pending count badge in the tab row — NOT a full
  // renderAuthScreen() call, since renderAuthScreen() is what calls this
  // function in the first place (see its "loading placeholder" hook
  // above); calling it again here would recurse forever.
  const pendingTab = document.querySelector('#authContent .req-tab');
  if (pendingTab) {
    const n = window._authFlow.joinRequests.pending.length;
    pendingTab.textContent = 'Pending' + (n ? ' (' + n + ')' : '');
  }
}
function _authReqListHtml() {
  const tab = window._authFlow.reqTab;
  const list = window._authFlow.joinRequests[tab] || [];
  if (!list.length) return `<div class="req-empty">No ${tab === 'pending' ? 'pending requests' : 'history yet'}</div>`;
  return list.map(r => `
    <div class="req-card">
      <div class="req-card-top">
        <div class="req-avatar">${_authInitials(r.traineeName)}</div>
        <div><div class="req-name">${r.traineeName}</div><div class="req-username">${r.traineeEmail || ''}</div></div>
      </div>
      ${tab === 'pending' ? `
        <div class="req-actions">
          <button class="req-deny-btn" onclick="_authDecideRequest('${r.reqId}', 'denied')">Deny</button>
          <button class="req-admit-btn" onclick="_authDecideRequest('${r.reqId}', 'approved')">Admit</button>
        </div>` : `<div class="auth-hint" style="margin:0;">${r.status === 'approved' ? '✅ Admitted' : '❌ Denied'}</div>`}
    </div>`).join('');
}
function _authSetReqTab(tab) {
  window._authFlow.reqTab = tab;
  renderAuthScreen(); // also re-triggers _authLoadJoinRequests() itself, see renderAuthScreen()
}
async function _authDecideRequest(reqId, decision) {
  const f = window._authFlow;
  if (!f.orgId) return;
  try {
    await fbRootPatch(`organizations/${f.orgId}/joinRequests/${reqId}`, { status: decision, reviewedAt: Date.now() });
    const req = (f.joinRequests.pending || []).find(r => r.reqId === reqId);
    if (decision === 'approved' && req && req.traineeUid) {
      await fbRootPut('users/' + req.traineeUid, {
        name: req.traineeName || '', email: req.traineeEmail || '',
        role: 'trainee', orgId: f.orgId, status: 'active', joinedAt: Date.now()
      });
    }
    showToast(decision === 'approved' ? `${req ? req.traineeName : 'Trainee'} admitted` : `Request denied`);
    await _authLoadJoinRequests();
  } catch (e) {
    showToast('Could not update request: ' + e.message, 'error');
  }
}

// ── Continue with Google — real Firebase Auth identity ───────────────────
// Native GoogleSignInClient (see MainActivity.signInWithGoogleForAuth())
// returns a real Google ID token, which gets exchanged for a Firebase
// Auth identity via the REST accounts:signInWithIdp endpoint. That's a
// genuine signed-in Firebase user (uid) — everything AFTER that (which
// role, which org) is still the mock/local state described above until
// Phase 2's data model exists to actually persist it per-uid.
const FIREBASE_WEB_API_KEY = (window.TXP_CONFIG && window.TXP_CONFIG.FIREBASE_WEB_API_KEY) || 'AIzaSyDPkDucFc5ZpmJE-U1ABb72mUmruCUx6Lg'; // Firebase Console > Project Settings > General > Web API Key

// ── Real email verification codes (EmailJS) ───────────────────────────────
// EmailJS sends the actual email straight from the client, no backend
// needed — the same "no server, just REST calls" shape as everything else
// real in this flow (Firebase Auth above, Firebase Realtime DB elsewhere).
// The 6-digit code itself is generated here, stored in Firebase Realtime
// DB (emailOtps/{email}, see _otpKey()) with a 10-minute expiry, and
// verified by comparing against that stored value (_authOtpNext()) —
// EmailJS's only job is delivering the email.
//
// To finish wiring this up: create a free account at emailjs.com, add an
// Email Service, and create a template with two variables the template
// body/subject can reference — {{to_email}} (recipient) and {{code}} (the
// 6-digit code) — then fill in the three values below from the EmailJS
// dashboard (Email Services / Email Templates / Account > General).
// Until they're filled in, _authSendEmailCode() below still generates and
// stores a real code, it just skips the actual send and surfaces the code
// via a toast + console.warn instead — same "FILL_ME_IN preview fallback"
// pattern FIREBASE_WEB_API_KEY used before it was set, so the flow stays
// testable end-to-end while EmailJS is being set up.
const EMAILJS_SERVICE_ID  = 'service_dm5qnqj'; // EmailJS dashboard > Email Services > your service's ID
const EMAILJS_TEMPLATE_ID = 'template_e1azwbs'; // EmailJS dashboard > Email Templates > your template's ID
const EMAILJS_PUBLIC_KEY  = 'bRNGLcTaJW2tTsFC1'; // EmailJS dashboard > Account > General > Public Key
// EmailJS normally checks the request's Origin/Referer against a domain
// allowlist (Account > Security) to stop the Public Key being abused from
// random sites — but this app's WebView loads from a file:///android_asset/
// origin, which isn't a real domain and can't be added to that allowlist,
// so calls with only the Public Key get rejected here. The documented way
// around that for non-browser apps is to also send the account's PRIVATE
// Key (dashboard > Account > General, right below the Public Key) as
// `accessToken` — that bypasses the origin check entirely. Leave this as
// 'FILL_ME_IN' and the "could not send the code" error is almost
// certainly this.
const EMAILJS_PRIVATE_KEY = '20c9Z-zyjYmWJRMPaoTQw'; // EmailJS dashboard > Account > General > Private Key
const _EMAILJS_CONFIGURED = EMAILJS_SERVICE_ID !== 'FILL_ME_IN' && EMAILJS_TEMPLATE_ID !== 'FILL_ME_IN' && EMAILJS_PUBLIC_KEY !== 'FILL_ME_IN';

// ── Real "you've been invited" emails (Add Participants → Invite) ────────
// Same EmailJS account/service/keys as the OTP email above — but a REAL
// invite email needs its own template, not a reuse of the OTP one: the OTP
// template's only content variable is {{code}}, and sending a task invite
// through it would just show the recipient a stray verification code with
// no mention of who invited them or what task it's for. So this is a
// second template, same account.
// To finish wiring this up: in the same EmailJS dashboard used for the OTP
// template, create ANOTHER template (Email Templates > Create New) whose
// subject/body reference {{to_email}} (recipient), {{from_name}} (who's
// inviting them), {{task_title}} (the task's title), and {{app_name}} —
// then paste its id below. Until it's filled in, _sendTaskInviteEmail()
// below skips the real send and surfaces this in a toast, same
// "FILL_ME_IN preview fallback" pattern as the OTP template above.
const EMAILJS_INVITE_TEMPLATE_ID = 'template_gy2be9h'; // EmailJS dashboard > Email Templates > your NEW invite template's ID
const _EMAILJS_INVITE_CONFIGURED = EMAILJS_SERVICE_ID !== 'FILL_ME_IN' && EMAILJS_INVITE_TEMPLATE_ID !== 'FILL_ME_IN' && EMAILJS_PUBLIC_KEY !== 'FILL_ME_IN';

// Sends the actual "you've been invited to a task" email. Note this can
// only ever be a "download the app and sign up" nudge — there's no uid to
// deliver an actual task copy to until that email creates an account, and
// nothing here auto-attaches the task once they do (that'd need a
// pendingInvites-by-email table checked at signup time, which doesn't
// exist yet — a reasonable follow-up if it turns out people want it).
async function _sendTaskInviteEmail(toEmail, taskTitle) {
  if (!_EMAILJS_INVITE_CONFIGURED) {
    console.warn('[_sendTaskInviteEmail] Invite template not configured yet — see EMAILJS_INVITE_TEMPLATE_ID comment.');
    showToast('Invite emails aren\'t set up yet — see EMAILJS_INVITE_TEMPLATE_ID in script.js', 'error');
    return false;
  }
  const reqBody = {
    service_id: EMAILJS_SERVICE_ID,
    template_id: EMAILJS_INVITE_TEMPLATE_ID,
    user_id: EMAILJS_PUBLIC_KEY,
    template_params: { to_email: toEmail, from_name: currentUser?.name || 'A Triangle user', task_title: taskTitle, app_name: 'Triangle' }
  };
  if (EMAILJS_PRIVATE_KEY !== 'FILL_ME_IN') reqBody.accessToken = EMAILJS_PRIVATE_KEY;
  try {
    const res = await fetch('https://api.emailjs.com/api/v1.0/email/send', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(reqBody)
    });
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      throw new Error('EMAILJS_REJECTED: HTTP ' + res.status + (text ? ' — ' + text : ''));
    }
    return true;
  } catch (e) {
    console.error('[_sendTaskInviteEmail] send failed:', e);
    return false;
  }
}

// Firebase Realtime DB keys can't contain ".", "#", "$", "[", "]" —
// encodeURIComponent already escapes "@" but leaves "." alone, so that
// still needs manual escaping to turn an email into one valid path segment.
// Firebase Realtime DB keys can't contain ".", "#", "$", "[", "]" — the
// PREVIOUS version of this percent-encoded the email (encodeURIComponent
// + manually escaping "." as "%2E"), which looks right but isn't: Firebase
// decodes the URL path segment BEFORE validating it as a key, so "%2E"
// just turns back into a literal "." server-side and gets rejected anyway
// — this is exactly what was causing the "Firebase database write failed
// ... 400" error. Replacing the disallowed characters with a plain safe
// substitute (",") instead of percent-encoding them sidesteps that
// decode-then-validate order entirely, which is also why this is the
// standard approach used for email-keyed Firebase data in general.
function _otpKey(email) {
  return (email || '').trim().toLowerCase().replace(/[.#$\[\]]/g, ',');
}

function _authGenerateOtp() {
  return String(Math.floor(100000 + Math.random() * 900000));
}

// Generates a fresh code, stores it (10-minute expiry, 0 attempts so far)
// in Firebase Realtime DB, and — if EmailJS is configured — actually
// emails it. Verification (_authOtpNext()) re-reads the code back from
// the DB rather than trusting this function's return value, so a stale
// local copy held by the caller can never cause a false accept. Throws if
// a REAL send attempt fails (network error, EmailJS rejecting the
// request) so the caller can keep the user on the email step instead of
// silently advancing to a code that was never delivered.
//
// _authFriendlySendErrorMsg() turns one of those tagged failures into a
// toast that says WHICH stage broke and why, instead of one generic
// "could not send the code" for every possible cause — DB write, network,
// and EmailJS rejecting the request are three genuinely different bugs
// with three different fixes, and guessing between them from a vague
// message wastes a round trip every time.
function _authFriendlySendErrorMsg(e) {
  const msg = e?.message || String(e);
  if (msg.startsWith('DB_WRITE_FAILED')) return 'Could not save the code (Firebase database write failed) — ' + msg.replace('DB_WRITE_FAILED: ', '');
  if (msg.startsWith('NETWORK_FAILURE')) return 'Could not reach EmailJS (network/CORS block, no response received) — ' + msg.replace('NETWORK_FAILURE: ', '');
  if (msg.startsWith('EMAILJS_REJECTED')) return 'EmailJS rejected the request — ' + msg.replace('EMAILJS_REJECTED: ', '');
  return 'Could not send the code — ' + msg;
}
async function _authSendEmailCode(email) {
  const code = _authGenerateOtp();
  const expiresAt = Date.now() + 10 * 60 * 1000;
  // Two genuinely separate network calls happen in this function — the
  // Firebase Realtime DB write (storing the code) and the EmailJS send
  // (delivering it) — and a generic "could not send the code" toast can't
  // tell you which one actually broke. Every failure path below is
  // labeled with which stage it came from so that's never ambiguous again.
  try {
    await fbRootPut('emailOtps/' + _otpKey(email), { code, expiresAt, attempts: 0 });
  } catch (e) {
    console.error('[_authSendEmailCode] Firebase DB write failed:', e);
    throw new Error('DB_WRITE_FAILED: ' + (e?.message || String(e)));
  }
  if (!_EMAILJS_CONFIGURED) {
    console.warn('[_authSendEmailCode] EmailJS not configured yet — skipping real send. Code for testing: ' + code);
    showToast('Email delivery isn’t set up yet — using code ' + code + ' for now', 'error');
    return code;
  }
  const reqBody = {
    service_id: EMAILJS_SERVICE_ID,
    template_id: EMAILJS_TEMPLATE_ID,
    user_id: EMAILJS_PUBLIC_KEY,
    template_params: { to_email: email, code, app_name: 'Triangle' }
  };
  if (EMAILJS_PRIVATE_KEY !== 'FILL_ME_IN') reqBody.accessToken = EMAILJS_PRIVATE_KEY;
  let res;
  try {
    res = await fetch('https://api.emailjs.com/api/v1.0/email/send', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(reqBody)
    });
  } catch (e) {
    // fetch() itself threw — no HTTP response was ever received (DNS
    // failure, TLS error, or the request being blocked outright before a
    // response came back, e.g. a CORS preflight rejection). This is a
    // DIFFERENT failure mode than EmailJS responding with an error code,
    // and needs a different fix, so it's labeled distinctly.
    console.error('[_authSendEmailCode] fetch() to EmailJS threw (no response received):', e);
    throw new Error('NETWORK_FAILURE: ' + (e?.message || String(e)));
  }
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error('EMAILJS_REJECTED: HTTP ' + res.status + (text ? ' — ' + text : ''));
  }
  return code;
}
function onGoogleAuthClick() {
  const b = _driveBridge();
  if (!b || typeof b.signInWithGoogleForAuth !== 'function') {
    showToast('Google sign-in is only available in the app (needs a native build with this feature)');
    return;
  }
  showToast('Opening Google sign-in…');
  try { b.signInWithGoogleForAuth(); } catch (e) { showToast('Could not open Google sign-in', 'error'); }
}

// Thin wrapper around every identitytoolkit.googleapis.com/v1/accounts:*
// REST call this flow makes (Google exchange, real email signUp, real
// email/password login) — one place for the fetch + Firebase's
// error-shape handling, so each of those three call sites doesn't repeat
// it. Throws an Error whose .code is Firebase's short error string (e.g.
// "EMAIL_EXISTS", "INVALID_PASSWORD") so callers can branch on it for a
// friendly message instead of showing the raw Firebase text.
async function _authFirebaseAuthRequest(endpoint, body) {
  const res = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:${endpoint}?key=${FIREBASE_WEB_API_KEY}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  const data = await res.json();
  if (!res.ok) {
    const code = (data && data.error && data.error.message) || '';
    const err = new Error(code || ('HTTP ' + res.status));
    err.code = code;
    throw err;
  }
  return data;
}

// Shared "where does this now-authenticated Firebase uid belong" routing —
// used after EVERY real identity check in this flow (Google exchange,
// real email signup, real email/password login), so a returning user
// lands in the same place no matter which of those three got them
// authenticated. PRD 5.1 steps 4-6: does this uid already have a
// users/{uid} record? Existing user with a role+org → skip role
// selection and go straight to wherever they already belong; brand new
// uid → role selection.
async function _authRouteAfterIdentity(uid, displayName, displayEmail) {
  let existing = null;
  try { existing = await fbRootGet('users/' + uid); } catch (e) { /* best-effort — fall through to role select on lookup failure */ }
  if (existing && existing.role === 'admin' && existing.orgId) {
    // Recognized returning admin of ANY real organization — every org has
    // real backing data now (see _authGoToRealDashboard()'s comment),
    // straight into the real dashboard, not a detour screen. Used to only
    // do this for TXP_ORG_ID and send every other org's admin through the
    // "You're All Set!" screen again on every single login.
    window._authFlow.uid = uid; window._authFlow.googleName = displayName; window._authFlow.googleEmail = displayEmail;
    // Same fix as the initial claim in _authPickAdminRole(): log this
    // returning admin in as themselves, not the legacy id:99 fixture.
    // `existing` is their own stored users/{uid} record, so prefer its
    // name/email (set at claim time) over whatever this sign-in call
    // reports, falling back to the latter if the record is thin.
    const adminUser = { id: uid, name: existing.name || displayName || 'Admin', username: existing.email || displayEmail || uid, role: 'admin' };
    await _authEnterRealApp(adminUser, existing.orgId);
  } else if (existing && existing.role === 'trainee' && existing.orgId) {
    // Admitted member of ANY real organization (was TXP_ORG_ID-only
    // before). First login ever → show the one-time PRD-required welcome
    // screen, then straight into the real dashboard; every login after
    // that skips straight to the real dashboard.
    if (!existing.welcomedAt) {
      let org = null;
      try { org = await fbRootGet('organizations/' + existing.orgId); } catch (e) {}
      fbRootPatch('users/' + uid, { welcomedAt: Date.now() }).catch(() => {});
      showAuthScreen('traineeWelcome', {
        uid, googleName: existing.name || displayName, googleEmail: existing.email || displayEmail,
        pendingOrg: { orgId: existing.orgId, name: org ? org.name : 'your organization', username: org ? org.username : '' }
      });
    } else {
      const traineeUser = { id: uid, name: existing.name || displayName, username: existing.email || displayEmail };
      await _authEnterRealApp(traineeUser, existing.orgId);
    }
  } else if (existing && existing.role === 'individual' && existing.orgId) {
    // Recognized returning individual user — straight into their own
    // dashboard, same as a returning admin.
    const individualUser = { id: uid, name: existing.name || displayName || '', username: existing.email || displayEmail || uid, role: 'individual' };
    await _authEnterRealApp(individualUser, existing.orgId);
  } else {
    showAuthScreen('roleSelect', { uid, googleName: displayName, googleEmail: displayEmail });
  }
}

window.onGoogleAuthResult = async function (success, idToken, name, email, message) {
  if (!success) {
    showToast(message || 'Google sign-in was cancelled', 'error');
    return;
  }
  if (FIREBASE_WEB_API_KEY === 'FILL_ME_IN') {
    // Exchange endpoint not wired up yet — still show real name/email from
    // Google so the UI flow can be reviewed end-to-end.
    console.warn('[onGoogleAuthResult] FIREBASE_WEB_API_KEY not set — skipping Firebase Auth exchange, using Google identity directly for preview purposes.');
    showToast('Signed in as ' + (name || email));
    showAuthScreen('roleSelect', { googleName: name, googleEmail: email });
    return;
  }
  try {
    const data = await _authFirebaseAuthRequest('signInWithIdp', {
      postBody: `id_token=${idToken}&providerId=google.com`,
      requestUri: 'https://triangle.app/oauth-callback',
      returnIdpCredential: true,
      returnSecureToken: true
    });
    const uid = data.localId;
    const displayName = data.displayName || name;
    const displayEmail = data.email || email;
    showToast('Signed in as ' + (displayName || displayEmail));
    await _authRouteAfterIdentity(uid, displayName, displayEmail);
  } catch (e) {
    console.error('[onGoogleAuthResult] Firebase Auth exchange failed:', e);
    showToast('Google sign-in failed: ' + e.message, 'error');
  }
};

