function openProfileInfoPopup() {
  if (!currentUser) return;
  
  // Close if already open
  const existing = document.getElementById('pipContainer');
  if (existing) {
    closeProfileInfoPopup();
    return;
  }
  
  const roleLabel = currentRole === 'admin' ? 'Administrator' : 'Intern';
  const initial = currentUser.name.split(' ').map(n => n[0]).join('');
  
  // Get user's email
  const email = currentUser.email || `${currentUser.name.toLowerCase().replace(/\s+/g, '.')}@example.com`;
  
  // Get contributor code
  const contributorCode = String(currentUser.id).padStart(4, '0');
  
  // Get avatar - check if user has custom avatar from submissions
  const s = db.submissions?.[currentUser.id];
  let avatarHTML;
  if (s?.avatar) {
    const avatarUrl = buildAvatarUrl(s.avatar);
    avatarHTML = `<img src="${avatarUrl}" alt="Avatar">`;
  } else {
    avatarHTML = initial;
  }
  
  // Create popup container
  const container = document.createElement('div');
  container.id = 'pipContainer';
  container.className = 'pip-container';
  container.innerHTML = `
    <div class="profile-info-popup">
      <div class="pip-header">
        <div class="pip-avatar">
          ${avatarHTML}
        </div>
        <div class="pip-name-block">
          <div class="pip-name">${sanitize(currentUser.name)}</div>
          <div class="pip-role">${roleLabel}</div>
        </div>
      </div>
      
      <div class="pip-fields">
        <div class="pip-field">
          <label class="pip-field-label">Email</label>
          <div class="pip-field-value">
            <span id="pipEmail">${sanitize(email)}</span>
            <span class="pip-edit-btn" onclick="editEmailInPopup()">Edit</span>
          </div>
        </div>
        
        <div class="pip-field">
          <label class="pip-field-label">Contributor Code</label>
          <div class="pip-field-value">
            <span class="pip-code-value" id="pipCode">••••</span>
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="pip-toggle-icon" onclick="toggleContributorCode('${contributorCode}')">
              <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </div>
        </div>
      </div>
      
      <button class="pip-view-btn" onclick="closeProfileInfoPopup();navigateTo(currentRole==='admin'?'adminDashboard':'internProfile');">
        View full profile
      </button>
      ${currentRole === 'admin' ? `<button class="pip-view-btn" onclick="closeProfileInfoPopup();navigateTo('adminAccountSettings');" style="margin-top:8px;">⚙️ Settings</button>` : ''}
    </div>
  `;
  
  document.body.appendChild(container);
  
  // Show with animation
  setTimeout(() => container.classList.add('show'), 10);
  
  // Close on outside click
  setTimeout(() => {
    document.addEventListener('click', handlePipOutsideClick);
  }, 100);
}

function handlePipOutsideClick(e) {
  const pip = document.getElementById('pipContainer');
  const userChip = document.querySelector('.user-chip');
  
  if (pip && !pip.contains(e.target) && !userChip.contains(e.target)) {
    closeProfileInfoPopup();
  }
}

function closeProfileInfoPopup() {
  const container = document.getElementById('pipContainer');
  if (container) {
    container.classList.remove('show');
    setTimeout(() => {
      container.remove();
      document.removeEventListener('click', handlePipOutsideClick);
    }, 200);
  }
}

function toggleContributorCode(code) {
  const codeEl = document.getElementById('pipCode');
  if (!codeEl) return;
  
  if (codeEl.textContent === '••••') {
    codeEl.textContent = code;
  } else {
    codeEl.textContent = '••••';
  }
}

function editEmailInPopup() {
  const emailEl = document.getElementById('pipEmail');
  if (!emailEl) return;
  
  const currentEmail = emailEl.textContent;
  const newEmail = prompt('Enter new email address:', currentEmail);
  
  if (newEmail && newEmail.trim() && newEmail !== currentEmail) {
    emailEl.textContent = sanitize(newEmail.trim());
    // Here you could save to database if needed
    showToast('Email updated successfully', 'success');
  }
}

function openProfilePopup() {
  if (!currentUser) return;
  const roleLabel = currentRole === 'admin' ? 'Administrator' : 'Intern';
  const initial = currentUser.name[0];
  const s = db.submissions?.[currentUser.id] || {};
  const pts = s.points || 0;
  const unreadCount = currentRole === 'intern'
    ? ((db.notifications?.[currentUser.id]) || []).filter(n => !n.read).length
    : (db.adminNotifications || []).filter(n => !n.read).length;
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

  // Point history (intern only, last 20 entries)
  const history = (s.pointHistory || []).slice(0, 20);
  const catTotals = {};
  history.forEach(h => {
    const k = h.label || h.type;
    catTotals[k] = (catTotals[k] || 0) + (h.pts || 0);
  });
  const catIcons = {'Office Attendance':'🏢','Projects':'🚀','Bugs':'🐛','Suggestions':'💡'};

  // Build category breakdown (like image 6)
  const breakdownRows = Object.entries(catTotals).map(([k, total]) => {
    const count = history.filter(h => (h.label||h.type) === k).length;
    const icon = catIcons[k] || '⭐';
    const subText = k.includes('Office') ? `${count} entries · verified`
      : k.includes('Project') ? `${count} submitted`
      : k.includes('Bug') ? `${count} accepted`
      : k.includes('Suggest') ? `${count} accepted`
      : `${count} entries`;
    return `<div class="ph-row">
      <div class="ph-row-icon">${icon}</div>
      <div class="ph-row-info"><div class="ph-row-label">${k}</div><div class="ph-row-sub">${subText}</div></div>
      <div class="ph-row-pts">+${total}</div>
    </div>`;
  }).join('');

  const taskPts = history.filter(h => h.type === 'task' || h.type === 'task_approval').reduce((a,h) => a+(h.pts||0), 0);
  const entryPts = history.filter(h => h.type === 'entry').reduce((a,h) => a+(h.pts||0), 0);

  const pointHistorySection = currentRole === 'intern' ? `
    <div class="ph-section">
      <div class="ph-title">📊 Point History</div>
      ${breakdownRows || '<div style="font-size:12px;color:var(--text2);padding:12px 0;text-align:center;">No history yet</div>'}
      ${breakdownRows ? `<div class="ph-monthly-total">Monthly Total <strong>${pts.toLocaleString()} pts</strong></div>` : ''}
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap;">
        <div class="ph-mini-badge">Tasks: +${taskPts} pts</div>
        <div class="ph-mini-badge">Entries: +${entryPts} pts</div>
      </div>
    </div>` : '';

  openModal(`
    <div class="profile-header">
      <div class="profile-avatar-lg" style="position:relative;">
        ${initial}
        ${unreadCount > 0 ? `<div class="profile-notif-dot">${unreadCount}</div>` : ''}
      </div>
      <div class="profile-name-block">
        <div class="profile-fn">${sanitize(currentUser.name.split(' ')[0])}</div>
        <div style="font-size:12px;color:var(--text2);margin-top:1px;">${sanitize(currentUser.name)}</div>
        <div class="profile-role-badge">${roleLabel}</div>
      </div>
      ${currentRole === 'intern' ? `<div class="profile-pts-chip"><div class="ppc-val">${pts.toLocaleString()}</div><div class="ppc-label">pts</div></div>` : ''}
    </div>

    <div class="profile-actions-row">
      <button class="profile-action-btn" onclick="closeModal();handleNotifClick();">
        <span class="pab-icon">🔔</span>
        <span>Alerts</span>
        ${unreadCount > 0 ? `<span class="pab-badge">${unreadCount}</span>` : ''}
      </button>
      <button class="profile-action-btn" onclick="toggleDarkMode();">
        <span class="pab-icon">${isDark ? '☀️' : '🌙'}</span>
        <span>${isDark ? 'Light' : 'Dark'}</span>
      </button>
      <button class="profile-action-btn danger" onclick="closeModal();doLogout();">
        <span class="pab-icon">↩</span>
        <span>Logout</span>
      </button>
    </div>

    ${pointHistorySection}

    <div class="modal-actions" style="margin-top:16px;">
      <button class="btn btn-secondary btn-full" onclick="closeModal()">Close</button>
    </div>`);
}

