// Dedicated full-screen "Backup & Restore" page — reached from Settings >
// Admin > Backup & Restore (right under Toolkit), and also from Individual's
// Settings > Data (see renderInternSettings' currentRole==='individual'
// block — Individual owns its own solo org's data same as an admin owns
// theirs, so it gets the same Drive feature; interns don't). Uses the same
// classic .rws-page-header (back button + centered title) as the
// Notifications page rather than the Settings-style header, and hides the
// app topbar + bottom nav/FAB — see the page-name lists inside
// navigateTo()/updateBadges() where 'adminDriveBackup' is added alongside
// the other full-screen sub-pages (dmThread, internNotifs, etc.) — kept as
// one shared page/function/key for both roles rather than a duplicate
// "individualDriveBackup", same as renderDriveBackupSection() below it is
// already shared. Card content comes from renderDriveBackupSection() (see
// that function + MainActivity.kt/WebAppInterface.kt for how the native
// bridge side works).
function renderAdminDriveBackup(ca) {
  const backTarget = currentRole === 'admin' ? 'adminAccountSettings' : 'internSettings';
  // Wrapped in .rws-page — the same fixed, full-viewport, single-scroll-owner
  // pattern Reward Store/Notifications already use (see .rws-page in
  // style.css) — instead of relying on the ambient #contentArea/.content-area
  // scroll like this page used to. That older approach needed a special
  // [data-page="adminDriveBackup"] .content-area override (see style.css) to
  // even reach full height, and still left a dead gap below a short card
  // (or clipped a tall one) because .content-area isn't a flex container —
  // its children's flex:1 (.drive-backup-card, #driveBackupSection) had
  // nothing to size against. .rws-page sizes and scrolls itself, so none of
  // that flex-chain plumbing is needed here any more.
  ca.innerHTML = `
    <div class="rws-page">
      <div class="rws-page-header">
        <button class="rws-back-btn" onclick="navigateTo('${backTarget}')">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>
        <span class="rws-page-title">Backup &amp; Restore</span>
        <div style="width:36px;"></div>
      </div>
      <div class="rw-body" style="padding:14px 14px 32px;">
        <div class="card drive-backup-card" style="margin:0;padding:0;overflow:hidden;">
          <div id="driveBackupSection">${renderDriveBackupSection()}</div>
        </div>
      </div>
    </div>`;
  if (typeof lucide !== 'undefined') lucide.createIcons();
  maybeAutoBackup();
}

// Real "Join Requests" admin page — reached from Settings > Admin > Join
// Requests. This is the REAL counterpart of the auth-preview flow's
// _authRenderAdminRequests() (same idea: pending/history tabs, real
// organizations/{orgId}/joinRequests reads, real Admit/Deny writes) but
// scoped to window.currentOrgId (the logged-in admin's actual org, set at
// login — see _refreshInternsRoster()/_authEnterRealApp()) instead of the
// auth flow's window._authFlow.orgId, since a real admin session has no
// _authFlow object at all. Admitting someone here triggers a live roster
// refresh (_refreshInternsRoster) so the new trainee shows up immediately
// in the Trainees list, task/habit assignment pickers, leaderboard, etc.
// without needing to log out and back in.
window._adminJoinReqState = { tab: 'pending', pending: [], history: [] };
function renderAdminJoinRequests(ca) {
  const st = window._adminJoinReqState;
  ca.innerHTML = `
    <div class="rws-page-header">
      <button class="rws-back-btn" onclick="navigateTo('adminAccountSettings')">
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
      </button>
      <span class="rws-page-title">Join Requests</span>
      <div style="width:36px;"></div>
    </div>
    <div class="rw-body" style="padding:14px 14px 32px;">
      <div class="req-tabs">
        <div class="req-tab ${st.tab==='pending'?'is-active':''}" onclick="_adminSetJoinReqTab('pending')">Pending${st.pending.length ? ' ('+st.pending.length+')' : ''}</div>
        <div class="req-tab ${st.tab==='history'?'is-active':''}" onclick="_adminSetJoinReqTab('history')">History</div>
      </div>
      <div id="adminJoinReqListWrap" style="margin-top:14px;">${_adminJoinReqListHtml()}</div>
    </div>`;
  if (typeof lucide !== 'undefined') lucide.createIcons();
  _adminLoadJoinRequests();
}
async function _adminLoadJoinRequests() {
  const wrap = document.getElementById('adminJoinReqListWrap');
  const orgId = window.currentOrgId || TXP_ORG_ID;
  try {
    const all = await fbRootGet(`organizations/${orgId}/joinRequests`) || {};
    const entries = Object.keys(all).map(reqId => ({ reqId, ...all[reqId] }));
    window._adminJoinReqState.pending = entries.filter(r => r.status === 'pending').sort((a,b) => (a.createdAt||0)-(b.createdAt||0));
    window._adminJoinReqState.history = entries.filter(r => r.status === 'approved' || r.status === 'denied').sort((a,b) => (b.reviewedAt||0)-(a.reviewedAt||0));
    window._pendingJoinReqCount = window._adminJoinReqState.pending.length;
    updateBadges();
  } catch (e) {
    console.error('[_adminLoadJoinRequests] failed:', e);
    if (wrap) wrap.innerHTML = '<div class="req-empty">Could not load requests — check your connection</div>';
    return;
  }
  if (wrap) wrap.innerHTML = _adminJoinReqListHtml();
  if (typeof lucide !== 'undefined') lucide.createIcons();
  const pendingTabEl = document.querySelector('#contentArea .req-tab');
  if (pendingTabEl) pendingTabEl.textContent = 'Pending' + (window._adminJoinReqState.pending.length ? ' (' + window._adminJoinReqState.pending.length + ')' : '');
}
function _adminJoinReqListHtml() {
  const st = window._adminJoinReqState;
  const list = st[st.tab] || [];
  if (!list.length) return `<div class="req-empty">No ${st.tab === 'pending' ? 'pending requests' : 'history yet'}</div>`;
  return list.map(r => `
    <div class="req-card">
      <div class="req-card-top">
        <div class="req-avatar">${_authInitials(r.traineeName)}</div>
        <div><div class="req-name">${sanitize(r.traineeName||'')}</div><div class="req-username">${sanitize(r.traineeEmail||'')}</div></div>
      </div>
      ${st.tab === 'pending' ? `
        <div class="req-actions">
          <button class="req-deny-btn" onclick="_adminDecideJoinRequest('${r.reqId}', 'denied')">Deny</button>
          <button class="req-admit-btn" onclick="_adminDecideJoinRequest('${r.reqId}', 'approved')">Admit</button>
        </div>` : `<div class="auth-hint" style="margin:0;">${r.status === 'approved' ? '✅ Admitted' : '❌ Denied'}</div>`}
    </div>`).join('');
}
function _adminSetJoinReqTab(tab) {
  window._adminJoinReqState.tab = tab;
  document.getElementById('adminJoinReqListWrap').innerHTML = _adminJoinReqListHtml();
  document.querySelectorAll('#contentArea .req-tab').forEach((el,i) => el.classList.toggle('is-active', (i===0) === (tab==='pending')));
  if (typeof lucide !== 'undefined') lucide.createIcons();
}
async function _adminDecideJoinRequest(reqId, decision) {
  const orgId = window.currentOrgId || TXP_ORG_ID;
  try {
    await fbRootPatch(`organizations/${orgId}/joinRequests/${reqId}`, { status: decision, reviewedAt: Date.now() });
    const req = (window._adminJoinReqState.pending || []).find(r => r.reqId === reqId);
    if (decision === 'approved' && req && req.traineeUid) {
      await fbRootPut('users/' + req.traineeUid, {
        name: req.traineeName || '', email: req.traineeEmail || '',
        role: 'trainee', orgId, status: 'active', joinedAt: Date.now()
      });
      // Live roster refresh so the new trainee shows up everywhere
      // immediately (Trainees list, assignment pickers, leaderboard) —
      // and creates their default submissions/notifications entry the
      // next time db is patched, without needing to log out/in.
      await _refreshInternsRoster(orgId);
      try { await fbPut('submissions/' + req.traineeUid, (db.submissions||{})[req.traineeUid] || {office:0,project:0,bugs:0,suggestions:0,dailyCounts:{},points:0,pointHistory:[],attendanceLogs:[],entries:[],avatar:null}); } catch(e) {}
      if (db) { if (!db.submissions) db.submissions = {}; if (!db.submissions[req.traineeUid]) db.submissions[req.traineeUid] = {office:0,project:0,bugs:0,suggestions:0,dailyCounts:{},points:0,pointHistory:[],attendanceLogs:[],entries:[],avatar:null}; if (!db.notifications) db.notifications = {}; if (!db.notifications[req.traineeUid]) db.notifications[req.traineeUid] = []; }
    }
    showToast(decision === 'approved' ? `${req ? req.traineeName : 'Trainee'} admitted` : 'Request denied');
    await _adminLoadJoinRequests();
    updateBadges();
  } catch (e) {
    showToast('Could not update request: ' + e.message, 'error');
  }
}

