function openChangePasswordModal() {
  openModal(`
    <div style="padding:4px 0;">
      <div style="font-size:16px;font-weight:700;color:var(--text);margin-bottom:16px;">Change Password</div>
      <div class="form-group"><label>Current Password</label><input type="password" id="cpCurrent" placeholder="Current password"></div>
      <div class="form-group"><label>New Password</label><input type="password" id="cpNew" placeholder="New password (min 6 chars)"></div>
      <div class="form-group" style="margin-bottom:4px;"><label>Confirm New</label><input type="password" id="cpConfirm" placeholder="Confirm new password"></div>
      <div class="error-msg" id="cpError" style="display:none;margin-bottom:8px;"></div>
      <div class="modal-actions">
        <button class="btn btn-secondary" onclick="closeModal()">Cancel</button>
        <button class="btn btn-primary" onclick="doChangePassword()">Update</button>
      </div>
    </div>`);
}

async function doChangePassword() {
  const cur = document.getElementById('cpCurrent')?.value || '';
  const nw  = document.getElementById('cpNew')?.value || '';
  const cf  = document.getElementById('cpConfirm')?.value || '';
  const errEl = document.getElementById('cpError');
  const showErr = msg => { if(errEl){errEl.textContent=msg;errEl.style.display='block';} };
  if (!cur || !nw || !cf) { showErr('Please fill all fields.'); return; }
  if (nw.length < 6) { showErr('New password must be at least 6 characters.'); return; }
  if (nw !== cf) { showErr('Passwords do not match.'); return; }
  // Verify current password
  const curHash = await sha256(cur);
  const uid = currentUser.id;
  const storedHash = db.submissions?.[uid]?.passwordHash || INTERN_HASHES[uid];
  if (curHash !== storedHash) { showErr('Current password is incorrect.'); return; }
  // Save new hash
  const newHash = await sha256(nw);
  if (!db.submissions[uid]) db.submissions[uid] = {};
  db.submissions[uid].passwordHash = newHash;
  try {
    await fbPut(`submissions/${uid}/passwordHash`, newHash);
    closeModal();
    showToast('✓', 'Password updated!');
  } catch(e) { showErr('Save failed. Try again.'); }
}

// Open "More" bottom sheet on profile page
function openProfileMoreSheet() {
  const items = [
    { icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg>`,
      label: 'Profile', action: `navigateTo('internProfile')` },
    { icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M8 6l4-4 4 4"/><path d="M12 2v10.3"/><path d="M4.9 19H3a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h2"/><path d="M19.1 19H21a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-2"/><rect x="7" y="10" width="10" height="12" rx="2"/></svg>`,
      label: 'Leaderboard', action: `closeMoreSheet();navigateTo('internDashboard')` },
    { icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="6"/><path d="M15.477 12.89L17 22l-5-3-5 3 1.523-9.11"/></svg>`,
      label: 'Rewards', action: `showToast('🏅','Rewards coming soon!')` },
    { icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>`,
      label: 'Complaints', action: `closeProfMoreSheet();navigateTo('internComplaints')` },
  ];

  // Remove existing sheet
  document.getElementById('profMoreSheetOverlay')?.remove();

  const overlay = document.createElement('div');
  overlay.id = 'profMoreSheetOverlay';
  overlay.className = 'pms-overlay';
  overlay.onclick = e => { if (e.target === overlay) closeProfMoreSheet(); };
  overlay.innerHTML = `
    <div class="pms-sheet">
      <div class="pms-handle"></div>
      ${items.map(item => `
        <div class="pms-item" onclick="${item.action};closeProfMoreSheet()">
          <div class="pms-icon">${item.icon}</div>
          <span class="pms-label">${item.label}</span>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-left:auto;color:var(--text3);"><polyline points="9 18 15 12 9 6"/></svg>
        </div>`).join('')}
    </div>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(() => overlay.querySelector('.pms-sheet').classList.add('open'));
}

function closeProfMoreSheet() {
  const o = document.getElementById('profMoreSheetOverlay');
  if (!o) return;
  o.querySelector('.pms-sheet')?.classList.remove('open');
  setTimeout(() => o.remove(), 280);
}

