function openWorkLogDetail(cat) {
  document.getElementById('wldWrapper')?.remove();

  const id      = currentUser.id;
  const entries = (db.submissions[id]?.entries||[])
    .filter(e => e.cat === cat)
    .slice().sort((a,b) => b.addedAt - a.addedAt);

  const colors = { Bugs:'#ef4444', Projects:'#059669', Suggestions:'#f59e0b' };
  const bgs    = { Bugs:'rgba(239,68,68,.15)', Projects:'rgba(5,150,105,.15)', Suggestions:'rgba(245,158,11,.15)' };
  const icons  = {
    Bugs:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" width="16" height="16"><rect width="8" height="14" x="8" y="6" rx="4"/><path d="m19 7-3 2M5 7l3 2M20 13h-4M4 13h4"/></svg>`,
    Projects:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" width="16" height="16"><path d="M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2z"/><path d="m12 15-3-3a22 22 0 012-3.95A12.88 12.88 0 0122 2c0 2.72-.78 7.5-6 11z"/></svg>`,
    Suggestions:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" width="16" height="16"><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 006 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/><path d="M9 18h6M10 22h4"/></svg>`,
  };
  const color = colors[cat]; const bg = bgs[cat];

  const itemsHtml = entries.length === 0
    ? `<div style="text-align:center;padding:48px 24px;color:var(--text3);font-size:14px;">No ${cat.toLowerCase()} logged yet.</div>`
    : entries.map(e => `
      <div class="wl-entry-card">
        <div class="wl-entry-top">
          <div class="wl-entry-icon" style="background:${bg};color:${color};">${icons[cat]}</div>
          <div class="wl-entry-main">
            <div class="wl-entry-title">${sanitize(e.title)}</div>
            <div class="wl-entry-id" style="background:${bg};color:${color};">${e.id}</div>
          </div>
          <div class="wl-entry-date">${sanitize(e.date)}</div>
        </div>
        ${e.desc ? `<div class="wl-entry-desc">${sanitize(e.desc)}</div>` : ''}
        ${e.link ? `<a class="wl-entry-link" href="${sanitize(e.link)}" target="_blank">
          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71"/></svg>
          ${sanitize(e.link.replace(/^https?:\/\//,'').slice(0,45))}
        </a>` : ''}
      </div>`).join('');

  const w = document.createElement('div');
  w.id = 'wldWrapper';
  w.innerHTML = `
    <div class="wld-screen">
      <div class="wld-header" style="border-bottom:1.5px solid var(--border);">
        <button class="wld-back" onclick="closeWorkLogDetail()">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>
        <span class="wld-title" style="color:${color};">${cat}</span>
        <span class="wld-count">${entries.length} total</span>
      </div>
      <div class="wld-body">
        ${itemsHtml}
      </div>
    </div>`;
  document.body.appendChild(w);
  requestAnimationFrame(() => w.querySelector('.wld-screen')?.classList.add('open'));
}

