function refreshContribInfo() {
  const cat = document.getElementById('addCat')?.value; if (!cat) return;
  const catPts = db.catPoints || DEF_POINTS;
  document.getElementById('catPtsVal').textContent = catPts[cat] || 5;
  // Only show contributors that handle entries (not taskApprovalOnly)
  const contrib = db.contributors.find(c => !c.taskApprovalOnly && (c.category === cat || c.category === 'All'));
  document.getElementById('catContribName').textContent = contrib ? contrib.name : 'No contributor assigned for this category';
}

async function refreshContribFromCode() {
  const raw = document.getElementById('addCode').value.trim();
  if (!raw) { refreshContribInfo(); return; }
  const h = await sha256(raw);
  const contrib = db.contributors.find(c => c.codeHash === h);
  const el = document.getElementById('catContribName');
  if (el) el.textContent = contrib ? contrib.name + ' ✓' : '—';
}

async function submitAdd() {
  const cat = document.getElementById('addCat').value;
  const code = document.getElementById('addCode').value.trim();
  const catKey = CAT_KEYS[cat];
  const s = db.submissions[currentUser.id];
  const td = today(); const dk = td + '-' + catKey;
  s.dailyCounts = s.dailyCounts || {};
  if ((s.dailyCounts[dk] || 0) >= 3) { showToast('Daily limit (3) reached for this category', 'error'); return; }
  // FIX-1: hash-based code verification — never compare plaintext
  const codeHash = await sha256(code);
  const contrib = db.contributors.find(c => c.codeHash === codeHash);
  if (!contrib) { showToast('Invalid contributor code', 'error'); return; }
  if (contrib.taskApprovalOnly) { showToast('This contributor is for task approval only, not entries. Use Send Request instead.', 'error'); return; }
  if (contrib.category && contrib.category !== cat && contrib.category !== 'All') {
    showToast('This contributor is not assigned to ' + cat, 'error'); return;
  }
  s[catKey] = (s[catKey] || 0) + 1;
  s.dailyCounts[dk] = (s.dailyCounts[dk] || 0) + 1;
  // FIX-5: validate & clamp all numeric inputs
  const catPts = db.catPoints || DEF_POINTS;
  let earned = Math.max(0, parseInt(catPts[cat]) || 5);
  if (document.getElementById('addBonus').checked) {
    const bonus = parseInt(document.getElementById('bonusPts').value) || 0;
    earned += Math.max(0, Math.min(bonus, 500));
  }
  if (!isFinite(earned) || isNaN(earned)) earned = catPts[cat] || 5;
  s.points = Math.max(0, (s.points || 0) + earned);
  s.pointHistory = s.pointHistory || [];
  s.pointHistory.unshift({ type:'entry', label: cat, pts: earned, date: today() });
  db.submissions[currentUser.id] = s;
  awardCoins(currentUser.id, earned, 'entry', cat);
  closeModal();
  await saveAndRefresh(cat + ' added! +' + earned + ' pts', 'internDashboard');
}

// ╔══════════════════════════════════════════════════╗
// ║           SEND REQUEST (Feature 3)               ║
// ║  Intern sends request when no contributor avail  ║
// ║  Admin approves → entry or task auto-applied     ║
// ╚══════════════════════════════════════════════════╝
// BUG-19 FIX: accepts optional preTaskId to pre-select the task in the dropdown
function openSendRequest(preTaskId) {
  const cats = Object.keys(CAT_KEYS);
  const alreadyRequested = new Set(
    (db.pendingRequests || []).filter(r => r.status === 'pending' && r.type === 'task').map(r => r.taskId)
  );
  const approvalTasks = db.tasks.filter(t =>
    _taskAppliesTo(t, currentUser.id) && !t.isPersonal && !t.isTemplate &&
    t.approvalRequired === true && !isTaskDone(t.id, currentUser.id) && !alreadyRequested.has(t.id)
  );
  // If preTaskId is specified switch default type to 'task'
  const defaultType = preTaskId ? 'task' : 'entry';
  openModal(`<div class="modal-title">📨 Send Request to Admin</div>
    <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:10px 13px;font-size:12px;color:#92400e;margin-bottom:14px;">
      Use this when no contributor is available. Admin will review and approve your request. Nothing is added or completed until admin approves.
    </div>
    <div class="form-group">
      <label>Request Type</label>
      <select id="reqType" onchange="toggleReqType()">
        <option value="entry" ${defaultType==='entry'?'selected':''}>Add Entry (attendance/project/etc.)</option>
        <option value="task"  ${defaultType==='task' ?'selected':''}>Task Completion</option>
      </select>
    </div>
    <div id="reqEntrySection" style="display:${defaultType==='entry'?'block':'none'};">
      <div class="form-group">
        <label>Category</label>
        <select id="reqCat">
          ${cats.map(c => `<option value="${c}">${CAT_ICONS[c]} ${c}</option>`).join('')}
        </select>
      </div>
    </div>
    <div id="reqTaskSection" style="display:${defaultType==='task'?'block':'none'};">
      <div class="form-group">
        <label>Select Task</label>
        ${approvalTasks.length === 0
          ? `<div style="background:#fff0f0;border:1px solid #fecaca;border-radius:8px;padding:10px 13px;font-size:13px;color:#e53e3e;">
               No approval-required tasks pending. Only tasks with "Approval Required" can be requested.
             </div>`
          : `<select id="reqTask">
               ${approvalTasks.map(t => `<option value="${t.id}" ${t.id===preTaskId?'selected':''}>${sanitize(t.title)}</option>`).join('')}
             </select>`}
      </div>
    </div>
    <div class="form-group">
      <label>Reason / Note <span style="color:var(--text3);">(optional)</span></label>
      <textarea id="reqNote" rows="2" placeholder="e.g. Contributor was unavailable today" maxlength="500"></textarea>
    </div>
    <div class="modal-actions">
      <button class="btn btn-secondary" onclick="closeModal()">Cancel</button>
      <button class="btn btn-primary" onclick="submitRequest()">Send Request</button>
    </div>`);
}

function toggleReqType() {
  const type = document.getElementById('reqType').value;
  document.getElementById('reqEntrySection').style.display = type === 'entry' ? 'block' : 'none';
  document.getElementById('reqTaskSection').style.display  = type === 'task'  ? 'block' : 'none';
}

async function submitRequest() {
  const type = document.getElementById('reqType').value;
  const note = document.getElementById('reqNote')?.value.trim() || '';
  let reqData = { id: 'req-'+Date.now(), type, internId: currentUser.id, note, date: today(), status: 'pending', read: false };
  if (type === 'entry') {
    reqData.category = document.getElementById('reqCat').value;
    reqData.msg = `📨 Entry Request: "${reqData.category}" from ${currentUser.name}`;
  } else {
    const taskEl = document.getElementById('reqTask');
    const taskId = taskEl?.value;
    if (!taskId) { showToast('No approval-required tasks available', 'error'); return; }
    // Guard: no duplicate pending request for same task
    const alreadyPending = (db.pendingRequests || []).some(r => r.taskId === taskId && r.status === 'pending');
    if (alreadyPending) { showToast('A request for this task is already pending', 'error'); return; }
    const task = db.tasks.find(t => t.id === taskId);
    if (!task) { showToast('Task not found', 'error'); return; }
    reqData.taskId = taskId;
    reqData.taskTitle = task.title;
    reqData.msg = `📨 Task Completion Request: "${task.title}" from ${currentUser.name}`;
  }
  if (!db.pendingRequests) db.pendingRequests = [];
  db.pendingRequests.unshift(reqData);
  closeModal();
  await saveAndRefresh('Request sent! Waiting for admin approval.', 'internDashboard');
}

// NOTE: approveRequest()/denyRequest() (the admin Approve/Deny actions for pending
// entry & task requests) were removed along with the Notifications pages, since their
// only UI lived there. db.pendingRequests entries are still created by submitRequest()
// and still show as "in review" on task cards, but nothing currently resolves them —
// that'll need a new home once notifications are rebuilt.

// ╔══════════════════════════════════════════════════╗
// ║              INTERN TASKS (KANBAN)               ║
// ╚══════════════════════════════════════════════════╝
function isTaskDone(tid, iid) { return db.taskCompletions?.[tid + '-' + iid]?.done || false; }

// Sort tasks newest-first
function sortNewest(tasks) {
  return [...tasks].sort((a, b) => {
    const ta = a.createdAt || (a.createdDate ? new Date(a.createdDate).getTime() : 0);
    const tb = b.createdAt || (b.createdDate ? new Date(b.createdDate).getTime() : 0);
    if (tb !== ta) return tb - ta;
    // Same timestamp (e.g. same-day date strings): use id as tiebreaker — higher id = newer
    return (Number(b.id)||0) - (Number(a.id)||0);
  });
}

// ════════════════════════════════════════════════════════════
// HABIT-STYLE TASK DASHBOARD — STATE
// ════════════════════════════════════════════════════════════
