function openHabitInfoPopup(tid, anchorEl) {
  closeHabitInfoPopup();
  const task = db.tasks.find(t=>t.id==tid); if(!task) return;
  const tags=[];
  if(task.sharedWith&&task.sharedWith.length>0) tags.push({icon:'👥',val:`Shared ${task.sharedWith.length}+`});
  const rd=task.instanceDate||task.createdDate||task.dueDate;
  if(rd) tags.push({icon:'📅',val:new Date(rd+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})});
  const rl=task.repeat?(typeof repeatLabel==='function'?repeatLabel(task.repeat):'Repeating'):task.templateId?'Daily':null;
  if(rl) tags.push({icon:'🔁',val:rl});
  if(task.points) tags.push({icon:'⚡',val:`+${task.points} XP`,cls:'points'});
  if(task.category) tags.push({icon:'🏷',val:task.category});
  if(!tags.length) tags.push({icon:'ℹ',val:'No extra info'});
  const tagsHtml=tags.map(t=>`<div class="info-popup-tag ${t.cls||''}"><div class="info-popup-tag-icon">${t.icon}</div><div class="info-popup-tag-val">${sanitize(t.val)}</div></div>`).join('');
  const ttl=task.title.length>28?task.title.slice(0,26)+'…':task.title;
  const ov=document.createElement('div'); ov.className='info-popup-overlay'; ov.id='habitInfoOverlay'; ov.onclick=closeHabitInfoPopup;
  const pop=document.createElement('div'); pop.className='info-popup'; pop.id='habitInfoPopup';
  pop.innerHTML=`<div class="info-popup-title">${sanitize(ttl)}</div><div class="info-popup-tags">${tagsHtml}</div>`;
  pop.onclick=e=>e.stopPropagation();
  document.body.appendChild(ov); document.body.appendChild(pop);
  requestAnimationFrame(()=>{
    const r=anchorEl.getBoundingClientRect(),pw=pop.offsetWidth||240,ph=pop.offsetHeight||140;
    let top=r.bottom+8,left=r.left+r.width/2-pw/2;
    if(left<12)left=12; if(left+pw>window.innerWidth-12)left=window.innerWidth-pw-12;
    if(top+ph>window.innerHeight-20)top=r.top-ph-8;
    pop.style.top=top+'px'; pop.style.left=left+'px';
  });
}
function closeHabitInfoPopup() { document.getElementById('habitInfoOverlay')?.remove(); document.getElementById('habitInfoPopup')?.remove(); }

