function renderKanbanCol(cat, tasks, id) {
  const cls = cat.toLowerCase();
  const colTasks = tasks.filter(t => (t.category || 'Personal').toLowerCase() === cls);
  return `<div class="kanban-col">
    <div class="kanban-header ${cls}"><span>${cat}</span><span style="font-size:11px;opacity:.8;">${colTasks.length}</span></div>
    <div class="kanban-tasks">
      ${colTasks.length === 0
        ? `<div style="padding:14px;text-align:center;color:var(--text3);font-size:12px;">No tasks</div>`
        : colTasks.map(t => renderKanbanCard(t, id)).join('')}
    </div>
  </div>`;
}

function renderKanbanCard(task, id) {
  const done = isTaskDone(task.id, id);
  // BUG-05 FIX: sanitize all user-generated content before innerHTML
  const safeTitle = sanitize(task.title);
  const pts  = task.points ? `<span class="kc-pts"><i data-lucide="star" style="width:10px;height:10px;display:inline;vertical-align:middle;"></i>${task.points}</span>` : '';
  const rep  = task.templateId ? `<span style="font-size:10px;color:var(--text3);"><i data-lucide="repeat" style="width:10px;height:10px;display:inline;vertical-align:middle;"></i></span>` : '';

  // PHASE-2 FIX-5: Overdue detection and visual treatment
  let overdueClass = '';
  let overdueBadge = '';
  if (!done && task.dueDate) {
    const todayStr = today();
    if (task.dueDate < todayStr) {
      // Calculate days overdue
      const msOverdue = new Date(todayStr+'T00:00:00') - new Date(task.dueDate+'T00:00:00');
      const daysOver = Math.round(msOverdue / 86400000);
      overdueClass = daysOver >= 2 ? 'overdue-urgent' : 'overdue';
      overdueBadge = `<span class="badge-overdue"><i data-lucide="alert-circle" style="width:9px;height:9px;display:inline;vertical-align:middle;"></i>${daysOver}d overdue</span>`;
    }
  }

  // Due date badge — red if overdue, orange otherwise
  let due = '';
  if (task.dueDate && !done) {
    const isOver = task.dueDate < today();
    due = `<span class="badge ${isOver ? 'badge-red' : 'badge-orange'}" style="font-size:10px;">${sanitize(task.dueDate)}</span>`;
  } else if (task.dueDate && done) {
    due = `<span class="badge badge-orange" style="font-size:10px;">${sanitize(task.dueDate)}</span>`;
  }

  let circle;
  if (done)
    circle = `<div class="kc-circle done"><i data-lucide="check" style="width:11px;height:11px;"></i></div>`;
  else if (task.approvalRequired && !task.isPersonal)
    circle = `<div class="kc-circle approval" onclick="event.stopPropagation();openApprovalDlg('${task.id}','${id}')" title="Needs approval"><i data-lucide="lock" style="width:11px;height:11px;"></i></div>`;
  else
    circle = `<div class="kc-circle" onclick="event.stopPropagation();completeTask('${task.id}','${id}',this,'tasks')" onmouseenter="showCheckHover(this)" onmouseleave="clearCheckHover(this)" title="Complete"></div>`;

  const actions = task.isPersonal && task.createdBy == id
    ? `<button class="kc-action kc-del" onclick="event.stopPropagation();deletePersonalTask('${task.id}')" title="Delete"><i data-lucide="trash-2" style="width:13px;height:13px;"></i></button>`
    : '';

  return `<div class="kanban-card ${done ? 'completed' : ''} ${overdueClass}" onclick="openTaskDetail('${task.id}')">
    ${circle}
    <div class="kc-info">
      <div class="kc-title">${done ? '<s>' + safeTitle + '</s>' : safeTitle}</div>
      <div class="kc-meta">${pts}${due}${rep}${overdueBadge}</div>
    </div>
    ${actions}
  </div>`;
}

function showCheckHover(el) {
  el.innerHTML = '<i data-lucide="check" style="width:11px;height:11px;"></i>';
  el.style.borderColor = 'var(--accent)';
  if (window.lucide) lucide.createIcons(); initCarousels();
}
function clearCheckHover(el) {
  el.innerHTML = '';
  el.style.borderColor = '';
}

function setTF(f) { window.taskFilter = f; navigateTo('internTasks'); }

// ╔══════════════════════════════════════════════════╗
// ║   LONG PRESS / CONTEXT MENU (req 11)             ║
// ╚══════════════════════════════════════════════════╝
let _lpTimer = null, _lpEl = null;
let _adminSelMode = false, _adminSelIds = new Set();

function initLongPressAll() {
  document.querySelectorAll('[data-longpress-id]').forEach(el => {
    el.addEventListener('pointerdown', e => {
      _lpEl = el;
      _lpTimer = setTimeout(() => {
        const tid = el.dataset.longpressId;
        const role = el.dataset.longpressRole;
        showTaskCtxMenu(e, tid, role);
      }, 600);
    });
    el.addEventListener('pointerup',    () => clearTimeout(_lpTimer));
    el.addEventListener('pointerleave', () => clearTimeout(_lpTimer));
    el.addEventListener('pointermove',  () => clearTimeout(_lpTimer));
  });
}

function showTaskCtxMenu(e, tid, role) { showTaskSheet(tid, role); }

function showTaskSheet(tid, role) {
  const task = db.tasks.find(t => t.id == tid); if (!task) return;
  const isOwn    = role === 'intern' && task.isPersonal && task.createdBy == currentUser?.id;
  const isAdmin  = role === 'admin';
  const needsApproval = !task.isPersonal && task.approvalRequired;

  let items = '';
  if (isAdmin) {
    items = `
      <div class="tsheet-item" onclick="closeTaskSheet();openEditTask('${tid}')">
        <div class="tsheet-icon" style="background:rgba(59,130,246,.12);color:#3b82f6;">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
        </div>
        <div class="tsheet-item-body"><div class="tsheet-item-title">Edit Task</div><div class="tsheet-item-sub">Modify title, date, points</div></div>
        <svg class="tsheet-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
      </div>
      <div class="tsheet-item danger" onclick="closeTaskSheet();ctxDeleteTask('${tid}')">
        <div class="tsheet-icon" style="background:rgba(220,38,38,.12);color:#dc2626;">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>
        </div>
        <div class="tsheet-item-body"><div class="tsheet-item-title" style="color:#dc2626;">Delete Task</div><div class="tsheet-item-sub">Remove permanently</div></div>
        <svg class="tsheet-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
      </div>`;
  } else if (isOwn) {
    items = `
      <div class="tsheet-item" onclick="closeTaskSheet();openEditCustomTask('${tid}')">
        <div class="tsheet-icon" style="background:rgba(59,130,246,.12);color:#3b82f6;">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
        </div>
        <div class="tsheet-item-body"><div class="tsheet-item-title">Edit Task</div><div class="tsheet-item-sub">Change title, date, category</div></div>
        <svg class="tsheet-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
      </div>
      <div class="tsheet-item danger" onclick="closeTaskSheet();deletePersonalTask('${tid}')">
        <div class="tsheet-icon" style="background:rgba(220,38,38,.12);color:#dc2626;">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>
        </div>
        <div class="tsheet-item-body"><div class="tsheet-item-title" style="color:#dc2626;">Delete Task</div><div class="tsheet-item-sub">Remove this custom task</div></div>
        <svg class="tsheet-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
      </div>`;
  } else {
    // Admin-assigned task for intern
    items = `
      <div class="tsheet-item" onclick="closeTaskSheet();openTaskDetail('${tid}')">
        <div class="tsheet-icon" style="background:rgba(232,93,38,.12);color:var(--accent);">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="12 19 12 5"/><polyline points="5 12 12 5 19 12"/></svg>
        </div>
        <div class="tsheet-item-body">
          <div class="tsheet-item-title">Send Request / Enter Code</div>
          <div class="tsheet-item-sub">${needsApproval ? 'Submit approval code to complete' : 'Mark task as complete'}</div>
        </div>
        <svg class="tsheet-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
      </div>`;
  }

  document.getElementById('taskSheetWrapper')?.remove();
  const title = task.title.length > 32 ? task.title.slice(0,30)+'…' : task.title;
  const w = document.createElement('div'); w.id = 'taskSheetWrapper';
  w.innerHTML = `
    <div class="tsheet-overlay" onclick="closeTaskSheet()"></div>
    <div class="tsheet" id="taskSheet">
      <div class="tsheet-handle"></div>
      <div class="tsheet-task-name">${sanitize(title)}</div>
      <div class="tsheet-items">${items}</div>
    </div>`;
  document.body.appendChild(w);
  if (window.lucide) lucide.createIcons();
  requestAnimationFrame(() => {
    document.getElementById('taskSheet')?.classList.add('open');
    w.querySelector('.tsheet-overlay')?.classList.add('visible');
  });
}

function closeTaskSheet() {
  const s  = document.getElementById('taskSheet');
  const ov = document.querySelector('.tsheet-overlay');
  if (s)  s.classList.remove('open');
  if (ov) ov.classList.remove('visible');
  setTimeout(() => document.getElementById('taskSheetWrapper')?.remove(), 300);
}


function closeCtxMenu() {
  document.getElementById('ctxMenu')?.classList.remove('visible');
  document.getElementById('ctxOverlay')?.remove();
}

async function ctxDeleteTask(tid) {
  closeCtxMenu();
  const task = db.tasks.find(t => t.id == tid); if (!task) return;
  if (currentRole === 'admin') {
    confirmDeleteAdminTask(tid);
  } else {
    await deletePersonalTask(tid);
  }
}

function ctxStartMultiSelect(tid) {
  closeCtxMenu();
  _adminSelMode = true;
  _adminSelIds = new Set([tid]);
  renderAdminTasks(document.getElementById('contentArea'));
}

function toggleAdminSel(tid) {
  if (_adminSelIds.has(tid)) _adminSelIds.delete(tid);
  else _adminSelIds.add(tid);
  // Update checkboxes visually
  document.querySelectorAll('.tlr-checkbox').forEach(cb => {
    const row = cb.closest('[data-task-id]');
    if (row) cb.classList.toggle('checked', _adminSelIds.has(row.dataset.taskId));
  });
  const bar = document.getElementById('adminSelBar');
  if (bar) bar.querySelector('span').textContent = `${_adminSelIds.size} selected`;
}

async function deleteSelectedAdminTasks() {
  if (_adminSelIds.size === 0) return;
  const count = _adminSelIds.size;
  for (const tid of _adminSelIds) {
    const task = db.tasks.find(t => t.id === tid);
    if (task) {
      const ck = tid + '-' + task.assignedTo;
      if (db.taskCompletions[ck]?.done && task.points) {
        const s = db.submissions[task.assignedTo];
        if (s) s.points = Math.max(0, (s.points || 0) - task.points);
      }
      db.tasks = db.tasks.filter(t => t.id !== tid && t.templateId !== tid);
      Object.keys(db.taskCompletions).forEach(k => { if (k.startsWith(tid + '-')) delete db.taskCompletions[k]; });
    }
  }
  _adminSelMode = false; _adminSelIds = new Set();
  await saveAndRefresh(`${count} task(s) deleted`, 'adminTasks');
}

function cancelAdminSel() {
  _adminSelMode = false; _adminSelIds = new Set();
  renderAdminTasks(document.getElementById('contentArea'));
}


async function deletePersonalTask(tid) {
  const task = db.tasks.find(t => t.id === tid);
  if (!task || !task.isPersonal || task.createdBy != currentUser.id) {
    showToast('You can only delete your own tasks', 'error'); return;
  }
  db.tasks = db.tasks.filter(t => t.id !== tid);
  // Also remove from template children
  db.tasks = db.tasks.filter(t => t.templateId !== tid);
  await saveAndRefresh('Task deleted', 'internTasks');
}

function openTaskDetail(tid) {
  const task = db.tasks.find(t => t.id == tid);
  if (!task) { showToast('Task not found', 'error'); return; }
  const isAdmin = currentRole === 'admin';
  const iid = isAdmin ? task.assignedTo : currentUser?.id;
  if (!isAdmin) {
    const owned = task.assignedTo === iid || (task.sharedWith && task.sharedWith.includes(iid)) || (task.isPersonal && task.createdBy == iid);
    if (!owned) { showToast('Access denied', 'error'); return; }
  }
  _openNewTaskDetail(tid);
}

// ── New unified Task Detail page ─────────────────────────────────────
function _openNewTaskDetail(tid) {
  const task = db.tasks.find(t => t.id == tid);
  if (!task) return;
  const isAdmin  = currentRole === 'admin';
  const iid      = isAdmin ? (task.assignedTo || currentUser?.id) : currentUser?.id;
  const done     = isTaskDone(task.id, iid);
  const inProg   = task.inProgress && task.inProgress.includes(iid);

  // Fix 1: use _habitGetIconColor/_habitGetIconSvg for BOTH intern and admin
  const heroColor = (typeof _habitGetIconColor === 'function')
    ? _habitGetIconColor(task)
    : (task.iconColor || task.color || '#e85d26');
  const rawIcon = (typeof _habitGetIconSvg === 'function')
    ? _habitGetIconSvg(task)
    : (task.iconSvg || '');
  const heroIcon = rawIcon.replace(/width="[^"]*"/g,'').replace(/height="[^"]*"/g,'')
    .replace('<svg ','<svg width="52" height="52" ').replace(/stroke="[^"]*"/g,'stroke="#fff"').replace(/fill="[^"]*"(?!.*none)/g,'');

  // Fix 4: Three statuses — To Do, Pending (overdue), Completed. No "In Progress".
  const isOverdue = !done && task.dueDate && new Date(task.dueDate + 'T23:59:59') < new Date();
  const currentStatus = done ? 'Completed' : isOverdue ? 'Pending' : 'To Do';
  const statusColor   = done ? '#22c55e' : isOverdue ? '#ef4444' : '#94a3b8';

  const assignedIntern = INTERNS.find(i => i.id == (task.assignedTo || iid));
  const internName = assignedIntern?.name || 'Intern';
  const internInitial = internName.charAt(0).toUpperCase();
  const internAvatarSrc = assignedIntern?.avatar || '';
  const internAvatarHtml = internAvatarSrc
    ? `<img src="${internAvatarSrc}" class="ntd-detail-avatar-img" alt="${sanitize(internName)}">`
    : `<div class="ntd-detail-avatar-initials" style="background:${assignedIntern?.color||heroColor};">${internInitial}</div>`;

  const fmtDate = raw => {
    if (!raw) return '—';
    const d = new Date(raw + 'T00:00:00');
    return isNaN(d) ? raw : d.toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'});
  };
  const cat      = task.category || 'Office';
  const pts      = task.points ? `${task.points} XP` : '—';
  const dueDate  = fmtDate(task.dueDate);
  const created  = fmtDate(task.createdDate || (task.createdAt ? new Date(task.createdAt).toISOString().slice(0,10) : null));
  const approval = task.approvalRequired ? 'Required' : 'Not required';

  // Fix 4: Checklist visible to BOTH intern and admin (no filter)
  const checkItems = task.checklist || [];
  const checkHtml = checkItems.length
    ? checkItems.map(item => {
        const isDone = item.done ? 'checked' : '';
        return `<div class="ntd-check-item" id="ntdci-${item.id}">
          <label class="ntd-check-label">
            <input type="checkbox" class="ntd-check-cb" ${isDone} onchange="ntdToggleCheckItem('${task.id}','${item.id}',this.checked,'${iid}')">
            <span class="ntd-check-text ${item.done?'ntd-check-done':''}">${sanitize(item.text)}</span>
          </label>
        </div>`;
      }).join('')
    : `<div class="ntd-empty-row"><svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="var(--text3)" stroke-width="1.5"><polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg><span>No checklist items</span></div>`;

  const doneCount = checkItems.filter(i=>i.done).length;
  const checkBadge = checkItems.length ? ` <span class="ntd-acc-count">${doneCount}/${checkItems.length}</span>` : '';

  // Fix 7: ALL notes visible to both admin and intern — no role filtering
  const notes = task.notes || [];

  const editBtn = isAdmin ? `<button class="ntd-topbar-btn" onclick="ntdClose();openEditTask&&openEditTask('${task.id}')" title="Edit">
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
  </button>` : '';

  // Share Task (Individual role only, and only the task's own owner can
  // share it — see openShareTaskSheet()'s comment for why cross-account
  // sharing is Individual-only and owner-only).
  const canShareTask = currentRole === 'individual' && task.isPersonal && task.createdBy == currentUser?.id;
  const shareBtn = canShareTask ? `<button class="ntd-topbar-btn" onclick="openShareTaskSheet('${task.id}')" title="Share Task">
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>
  </button>` : '';

  const assignedRowHtml = (() => {
    const allAssigned = [];
    if (task.assignedTo) {
      const ai = INTERNS.find(i => i.id == task.assignedTo);
      if (ai) allAssigned.push(ai);
    }
    if (task.sharedWith && task.sharedWith.length) {
      task.sharedWith.forEach(sid => {
        const si = INTERNS.find(i => i.id == sid);
        if (si && !allAssigned.find(a => a.id == si.id)) allAssigned.push(si);
      });
    }
    if (!allAssigned.length) return `<div class="ntd-row"><span class="ntd-rlabel">Assigned To</span><span class="ntd-rval">${sanitize(internName)}</span></div>`;
    // Fix 1: one row per intern — avatar on left of value, name inline
    return allAssigned.map((a, idx) => {
      const av = a.avatar
        ? `<img src="${a.avatar}" class="ntd-detail-avatar-img" alt="${sanitize(a.name)}">`
        : `<div class="ntd-detail-avatar-initials" style="background:${a.color||heroColor};">${a.name.charAt(0).toUpperCase()}</div>`;
      const label = idx === 0 ? 'Assigned To' : '';
      return `<div class="ntd-row${idx===allAssigned.length-1?' ntd-row-last-assigned':''}">
        <span class="ntd-rlabel">${label}</span>
        <span class="ntd-rval ntd-rval-avatar">${av}<span>${sanitize(a.name)}</span></span>
      </div>`;
    }).join('');
  })();

  // Shared-task info (Individual role's cross-account sharing — see
  // openShareTaskSheet()). A shared task lives as its own independent copy
  // in each participant's own account (see shareTaskWithUser()'s comment
  // for why), so these are just read-only breadcrumbs: who this copy came
  // from, and — on the original owner's copy — who they've shared it with.
  const sharedByRow = task.sharedFromName
    ? `<div class="ntd-row"><span class="ntd-rlabel">Shared By</span><span class="ntd-rval">${sanitize(task.sharedFromName)}</span></div>`
    : '';
  const sharedWithRow = (task.sharedToUsers && task.sharedToUsers.length)
    ? `<div class="ntd-row"><span class="ntd-rlabel">Shared With</span><span class="ntd-rval">${task.sharedToUsers.map(u=>sanitize(u.name)).join(', ')}</span></div>`
    : '';

  // Fix 1: XP label (replaces freq pill)
  const xpLabel = task.points ? `${task.points} XP` : pts;

  const dis = done ? 'ntd-btn-disabled' : '';
  const notesHtml = _buildNotesTimeline(notes, heroColor, isAdmin);

  const generalOpen   = task.description ? 'ntd-acc-open' : '';
  const detailsOpen   = 'ntd-acc-open';
  const checklistOpen = checkItems.length ? 'ntd-acc-open' : '';
  const gChev  = task.description ? 'rotate(180deg)' : '';
  const dChev  = 'rotate(180deg)';
  const clChev = checkItems.length ? 'rotate(180deg)' : '';

  const html = `
  <div class="ntd-overlay" id="ntdOverlay" onclick="ntdClose()"></div>
  <div class="ntd-page" id="ntdPage">
    <div class="ntd-scroll-outer" id="ntdScrollOuter">

      <div class="ntd-hero" id="ntdHero" style="--hero:${heroColor};">
        <div class="ntd-topbar">
          <button class="ntd-topbar-btn" onclick="ntdClose()">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <div style="flex:1;"></div>
          ${shareBtn}
          ${editBtn}
          <!-- Fix 2: static status badge, no dropdown -->
          <div class="ntd-status-badge">
            <span class="ntd-spill-dot" style="background:${statusColor};"></span>
            <span>${currentStatus}</span>
          </div>
        </div>
        <div class="ntd-hero-body">
          <div class="ntd-hero-icon-ring">${heroIcon}</div>
          <h2 class="ntd-hero-title">${sanitize(task.title)}</h2>
          ${task.description ? `<p class="ntd-hero-desc" style="color:${heroColor};background:${heroColor}33;border-radius:8px;padding:6px 12px;">${richTextPreview(task.description,120)}</p>` : ''}
        </div>
        <!-- XP left, action buttons right -->
        <div class="ntd-hero-actions">
          <div class="ntd-hero-freq"><svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="rgba(255,255,255,.8)" stroke="none"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg> ${xpLabel}</div>
          <div class="ntd-hero-btns">
            <button class="ntd-hero-act-btn ${dis}" onclick="${done?'':' ntdOpenNoteSheet(\''+task.id+'\')'}" ${done?'disabled':''} title="Add Note">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="12" y1="18" x2="12" y2="12"/><line x1="9" y1="15" x2="15" y2="15"/></svg>
            </button>
            <!-- Fix 8: photo button opens action sheet -->
            <button class="ntd-hero-act-btn ${dis}" onclick="${done?'':'ntdShowPhotoSheet(\''+task.id+'\')'}" ${done?'disabled':''} title="Add Photo">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
            </button>
            <!-- Fix 2: checkmark same bg, green stroke when done -->
            <button class="ntd-hero-act-btn ${done?'ntd-act-completed':''} ${dis}" onclick="${done?'':'ntdChangeStatus(\''+task.id+'\',\''+iid+'\',\'Completed\')'}" ${done?'disabled':''} title="${done?'Completed':'Mark Complete'}">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="${done?'#4ade80':'#fff'}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            </button>
          </div>
        </div>
      </div>

      <div class="ntd-card-body" id="ntdCardBody">
        <!-- Fix 4: Sticky header with more top-bottom padding -->
        <div class="ntd-sticky-hd" id="ntdStickyHd">
          <button class="ntd-sticky-back" onclick="ntdClose()">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <div class="ntd-sticky-title">${sanitize(task.title)}</div>
        </div>

        <div class="ntd-acc-list">
          <div class="ntd-acc" id="ntdAcc_General">
            <button class="ntd-acc-hd" onclick="ntdToggleAcc('General')">
              <div class="ntd-acc-hd-left"><span>General</span></div>
              <svg class="ntd-chevron" id="ntdCh_General" style="transform:${gChev}" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            <div class="ntd-acc-body ${generalOpen}" id="ntdBd_General">
              <div class="ntd-gen-block">
                <div class="ntd-gen-label">Description</div>
                <div class="ntd-gen-desc rich-desc">${task.description ? sanitizeRichHtml(task.description) : '<em style="color:var(--text3);">No description added.</em>'}</div>
              </div>
            </div>
          </div>

          <div class="ntd-acc" id="ntdAcc_Details">
            <button class="ntd-acc-hd" onclick="ntdToggleAcc('Details')">
              <div class="ntd-acc-hd-left"><span>Details</span></div>
              <svg class="ntd-chevron" id="ntdCh_Details" style="transform:${dChev}" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            <div class="ntd-acc-body ${detailsOpen}" id="ntdBd_Details">
              ${assignedRowHtml}
              <div class="ntd-row"><span class="ntd-rlabel">Created By</span><span class="ntd-rval">Admin</span></div>
              ${sharedByRow}
              ${sharedWithRow}
              <div class="ntd-row"><span class="ntd-rlabel">Points</span><span class="ntd-rval"><span class="ntd-chip-sm" style="background:${heroColor}18;color:${heroColor};">${pts}</span></span></div>
              <div class="ntd-row"><span class="ntd-rlabel">Category</span><span class="ntd-rval"><span class="ntd-chip-sm" style="background:${heroColor}18;color:${heroColor};">${sanitize(cat)}</span></span></div>
              <div class="ntd-row"><span class="ntd-rlabel">Task Created</span><span class="ntd-rval">${created}</span></div>
              <div class="ntd-row"><span class="ntd-rlabel">Due Date</span><span class="ntd-rval${dueDate!=='—'?' ntd-rval-due':''}">${dueDate}</span></div>
              <div class="ntd-row ntd-row-last"><span class="ntd-rlabel">Approval</span><span class="ntd-rval">${approval}</span></div>
            </div>
          </div>

          <div class="ntd-acc" id="ntdAcc_Checklist">
            <button class="ntd-acc-hd" onclick="ntdToggleAcc('Checklist')">
              <div class="ntd-acc-hd-left"><span>Checklist${checkBadge}</span></div>
              <svg class="ntd-chevron" id="ntdCh_Checklist" style="transform:${clChev}" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            <div class="ntd-acc-body ${checklistOpen}" id="ntdBd_Checklist">
              <div class="ntd-checklist-wrap" id="ntdChecklistWrap">${checkHtml}</div>
            </div>
          </div>
        </div>

        <div class="ntd-timeline" id="ntdNotesSection" data-color="${heroColor}">
          ${notesHtml}
        </div>
        <div style="height:80px;"></div>
      </div>

    </div>
  </div>`;

  document.getElementById('ntdWrapper')?.remove();
  window._ntdOpenTaskId = task.id; window._ntdOpenHabitId = null; window._ntdOpenHabitIid = null;
  const w = document.createElement('div'); w.id = 'ntdWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  if (window.lucide) lucide.createIcons();
  requestAnimationFrame(() => {
    document.getElementById('ntdPage')?.classList.add('open');
    document.getElementById('ntdOverlay')?.classList.add('vis');

    // Fix 5: Set page bg to --bg so hero color doesn't bleed through on scroll
    const page = document.getElementById('ntdPage');
    if (page) page.style.background = 'var(--bg)';

    // Smooth parallax — white card slides up over hero
    const outer    = document.getElementById('ntdScrollOuter');
    const hero     = document.getElementById('ntdHero');
    const cardBody = document.getElementById('ntdCardBody');
    const stickyHd = document.getElementById('ntdStickyHd');

    if (outer && hero && cardBody) {
      const peek = 60;
      requestAnimationFrame(() => {
        const heroH = hero.offsetHeight || 260;

        outer.addEventListener('scroll', () => {
          const s = outer.scrollTop;
          const maxScroll = heroH - peek;
          const t = Math.min(1, s / maxScroll);

          // Hero: smoothly fades out; no translateY to avoid color peek
          hero.style.opacity = String(Math.max(0, 1 - t * 1.3).toFixed(3));

          // Sticky header: fades in only after hero fully gone
          if (stickyHd) stickyHd.classList.toggle('ntd-sticky-visible', s > maxScroll);
        }, { passive: true });
      });
    }
  });
  document.addEventListener('click', _ntdOutsideClick);
}


function _buildNotesTimeline(notes, heroColor, isAdmin) {
  if (!notes || !notes.length) return '';
  return notes.map((note, idx) => {
    const noteIsAdmin = note.role === 'admin' || note.userId === 99;
    const uname = note.userName || (noteIsAdmin ? 'Admin' : 'Intern');
    const initial = uname.charAt(0).toUpperCase();
    // Fix 6: live timestamp — store timestamp as data-ts, update via interval
    const ts = note.timestamp || 0;
    const timeAgo = typeof getTimeAgo === 'function' ? getTimeAgo(ts) : '';
    const isLast = idx === notes.length - 1;
    const avatarBg = heroColor;

    const body = note.type === 'photo'
      ? `<img src="${note.content}" class="ntd-note-img" onclick="ntdOpenLightbox('${note.content}')" alt="Note photo">`
      : `<div class="ntd-note-text">${sanitize(note.content||'')}</div>`;

    // Fix 5: line always renders, hidden on last via CSS class
    return `<div class="ntd-tl-entry${isLast?' ntd-tl-last':''}">
      <div class="ntd-tl-left">
        <div class="ntd-tl-avatar" style="background:${avatarBg};">${initial}</div>
        <div class="ntd-tl-line" style="background:${heroColor}55;"></div>
      </div>
      <div class="ntd-tl-card">
        <div class="ntd-tl-meta">
          <span class="ntd-tl-username" style="color:${heroColor};">@${sanitize(uname.toLowerCase().replace(/\s+/g,''))}</span>
          <span class="ntd-tl-time" data-ts="${ts}">${timeAgo}</span>
        </div>
        <div class="ntd-tl-body">${body}</div>
      </div>
    </div>`;
  }).join('');
}

// Fix 6: live timestamp refresh every 30 seconds
setInterval(() => {
  document.querySelectorAll('.ntd-tl-time[data-ts]').forEach(el => {
    const ts = parseInt(el.dataset.ts, 10);
    if (ts && typeof getTimeAgo === 'function') el.textContent = getTimeAgo(ts);
  });
}, 30000);

// Fix 8: Photo action sheet — Take Photo / From Gallery (like TickOff / competitor apps)
function ntdShowPhotoSheet(taskId) {
  // Remove any existing sheet
  document.getElementById('ntdPhotoSheet')?.remove();
  const sheet = document.createElement('div');
  sheet.id = 'ntdPhotoSheet';
  sheet.innerHTML = `
    <div class="ntd-photo-backdrop" onclick="document.getElementById('ntdPhotoSheet')?.remove()"></div>
    <div class="ntd-photo-sheet">
      <div class="ntd-photo-sheet-handle"></div>
      <div class="ntd-photo-sheet-title">Add Photo</div>
      <button class="ntd-photo-opt" onclick="ntdPhotoCapture('${taskId}','camera')">
        <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
        <span>Take Photo</span>
      </button>
      <button class="ntd-photo-opt" onclick="ntdPhotoCapture('${taskId}','gallery')">
        <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
        <span>From Gallery</span>
      </button>
      <button class="ntd-photo-cancel" onclick="document.getElementById('ntdPhotoSheet')?.remove()">Cancel</button>
    </div>
  `;
  document.body.appendChild(sheet);
  // Animate in
  requestAnimationFrame(() => sheet.querySelector('.ntd-photo-sheet').classList.add('ntd-photo-sheet-open'));
}

function ntdPhotoCapture(taskId, source) {
  document.getElementById('ntdPhotoSheet')?.remove();
  let fi = document.getElementById('ntdFileInput');
  if (!fi) {
    fi = document.createElement('input');
    fi.type = 'file';
    fi.id = 'ntdFileInput';
    fi.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(fi);
  }
  fi.value = '';
  fi.accept = 'image/*';
  // capture=environment for camera, no capture for gallery
  if (source === 'camera') {
    fi.setAttribute('capture', 'environment');
  } else {
    fi.removeAttribute('capture');
  }
  fi.dataset.taskid = taskId;
  fi.onchange = () => ntdHandlePhoto(taskId, fi);
  fi.click();
}

function ntdClose() {
  document.removeEventListener('click', _ntdOutsideClick);
  const page = document.getElementById('ntdPage');
  const ov   = document.getElementById('ntdOverlay');
  if (page) { page.classList.remove('open'); setTimeout(() => document.getElementById('ntdWrapper')?.remove(), 320); }
  if (ov) ov.classList.remove('vis');
  window._ntdOpenTaskId = null; window._ntdOpenHabitId = null; window._ntdOpenHabitIid = null;
}

function _ntdOutsideClick(e) {
  const menu = document.getElementById('ntdSmenu');
  const wrap = document.getElementById('ntdStatusWrap');
  if (menu && wrap && !wrap.contains(e.target)) menu.style.display = 'none';
}

function ntdToggleAcc(name) {
  const body    = document.getElementById('ntdBd_' + name);
  const chevron = document.getElementById('ntdCh_' + name);
  if (!body) return;
  const isOpen = body.classList.contains('ntd-acc-open');
  if (isOpen) {
    body.classList.remove('ntd-acc-open');
    if (chevron) chevron.style.transform = '';
  } else {
    body.classList.add('ntd-acc-open');
    if (chevron) chevron.style.transform = 'rotate(180deg)';
  }
}

function ntdToggleStatus() {
  const menu = document.getElementById('ntdSmenu');
  if (!menu) return;
  menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
}

async function ntdChangeStatus(taskId, iid, newStatus) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  // Was parseInt(iid) — mangled every real (string-UID) trainee's own id
  // into NaN, so tapping "Mark Complete" on the Task Detail page silently
  // wrote points/completion to db.submissions[NaN]/taskCompletions[...-NaN]
  // instead of the trainee's own record. This is exactly the path a
  // non-primary trainee on a shared task uses (the primary assignee usually
  // completes it from the Home dashboard checkbox instead, which was never
  // affected), which is why only the first-assigned trainee's points/task
  // count ever appeared to go up.
  const uid = _parseInternId(iid);
  const key = taskId + '-' + uid;
  let coinsEarned = 0;

  if (newStatus === 'Completed') {
    // Fix 2: write to db.taskCompletions — the same store isTaskDone() reads
    if (!db.taskCompletions[key]?.done) {
      db.taskCompletions[key] = { done: true };
      const pts = task.points || 0;
      if (pts) {
        if (!db.submissions[uid]) db.submissions[uid] = { points: 0 };
        db.submissions[uid].points = (db.submissions[uid].points || 0) + pts;
        db.submissions[uid].pointHistory = db.submissions[uid].pointHistory || [];
        db.submissions[uid].pointHistory.unshift({ type: 'task', label: task.title, pts, date: today() });
        // This flow was never converting XP into coins — fixed to match
        // how task completion elsewhere in the app already does it.
        coinsEarned = awardCoins(uid, pts, 'task', task.title, taskId);
      }
      if (currentRole === 'intern') {
        const internName = INTERNS.find(i => i.id === uid)?.name || currentUser?.name || 'Intern';
        pushAdminNotif({ type:'task_completed', title:'Task Completed', body:`${internName} completed "${task.title}"`, internId: uid });
      }
      if (task.isPersonal && task.sharedFromUserId) _notifyShareSenderOnComplete(task);
    }
    if (task.inProgress) task.inProgress = task.inProgress.filter(id => id !== uid);
  } else {
    delete db.taskCompletions[key];
    if (task.inProgress) task.inProgress = task.inProgress.filter(id => id !== uid);
  }

  markDirty();
  try {
    // PUT, not PATCH — see the note on fbPut() above re: PATCH being
    // unreliable in this app's real runtime. taskCompletions is a shared
    // map, so unlike the other conversions this one COULD in principle
    // drop a different trainee's near-simultaneous completion; accepted
    // for now since PATCH here was failing outright anyway.
    await fbPut('taskCompletions', db.taskCompletions);
    // THE FIX: this never actually synced the points update above to the
    // server at all — db.submissions[uid].points was only ever changed in
    // local memory, with nothing here writing it back to Firebase. So
    // completing a task from the Task Detail page's "Mark Complete" button
    // always looked right immediately, then reverted the exact same way
    // habit XP was reverting: the next real data sync from anywhere just
    // had no idea the points had changed, because they never left this
    // one session's memory.
    if (task.points) await fbPut(`submissions/${uid}/points`, db.submissions[uid].points);
    if (coinsEarned > 0) await saveWallet(uid);
  } catch(e) {}
  showToast(newStatus === 'Completed' ? (coinsEarned > 0 ? `✓ Task completed! +${coinsEarned} coin${coinsEarned!==1?'s':''}` : '✓ Task completed!') : 'Status updated', 'success');
  updateBadges && updateBadges();

  // Refresh status badge
  const isOverdue = !isTaskDone(taskId, uid) && task.dueDate && new Date(task.dueDate + 'T23:59:59') < new Date();
  const nowStatus = isTaskDone(taskId, uid) ? 'Completed' : isOverdue ? 'Pending' : 'To Do';
  const nowColor  = nowStatus === 'Completed' ? '#22c55e' : nowStatus === 'Pending' ? '#ef4444' : '#94a3b8';
  const badge = document.querySelector('.ntd-status-badge');
  if (badge) {
    const dot = badge.querySelector('.ntd-spill-dot');
    const lbl = badge.querySelectorAll('span')[1];
    if (dot) dot.style.background = nowColor;
    if (lbl) lbl.textContent = nowStatus;
  }

  if (newStatus === 'Completed') {
    // Fix 2: disable ALL hero action buttons
    document.querySelectorAll('#ntdPage .ntd-hero-btns .ntd-hero-act-btn').forEach(b => {
      b.disabled = true;
      b.classList.add('ntd-btn-disabled');
      b.onclick = null;
    });
    // Turn checkmark green
    const btns = document.querySelectorAll('#ntdPage .ntd-hero-btns .ntd-hero-act-btn');
    const checkBtnEl = btns[btns.length - 1];
    if (checkBtnEl) {
      checkBtnEl.classList.add('ntd-act-completed');
      const svgEl = checkBtnEl.querySelector('svg');
      if (svgEl) svgEl.setAttribute('stroke', '#4ade80');
    }
    playSuccessSound && playSuccessSound();
  }

  // Refresh background list
  const ca = document.getElementById('contentArea');
  if (ca) {
    if (typeof renderInternTasks === 'function') renderInternTasks(ca);
  }
}

function ntdOpenNoteSheet(taskId) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const heroColor = task.iconColor || task.color || '#e85d26';
  // Build inline note sheet directly in the page (not modal) so keyboard opens immediately
  const existing = document.getElementById('ntdInlineNoteSheet');
  if (existing) { existing.remove(); return; } // toggle off if already open
  const sheet = document.createElement('div');
  sheet.id = 'ntdInlineNoteSheet';
  sheet.className = 'ntd-inline-sheet';
  sheet.innerHTML = `
    <div class="ntd-inline-sheet-hd">
      <span style="font-size:14px;font-weight:700;color:var(--text);">📝 Add Note</span>
      <button class="ntd-inline-sheet-close" onclick="document.getElementById('ntdInlineNoteSheet')?.remove()">✕</button>
    </div>
    <textarea id="ntdInlineNoteTA" class="ntd-inline-sheet-ta" placeholder="Write your note…" rows="4" autofocus></textarea>
    <div style="display:flex;gap:8px;padding:0 0 4px;">
      <button class="btn btn-secondary" style="flex:1;" onclick="document.getElementById('ntdInlineNoteSheet')?.remove()">Cancel</button>
      <button class="btn btn-primary" style="flex:1;background:${heroColor};border-color:${heroColor};" onclick="ntdSaveNote('${taskId}')">Save Note</button>
    </div>
  `;
  // Append inside ntdScrollBody so it scrolls with content and keyboard pushes it up
  const scrollBody = document.getElementById('ntdScrollBody');
  if (scrollBody) {
    scrollBody.appendChild(sheet);
    scrollBody.scrollTop = scrollBody.scrollHeight;
  } else {
    document.getElementById('ntdPage')?.appendChild(sheet);
  }
  // Focus textarea immediately — this opens the keyboard on mobile
  const ta = document.getElementById('ntdInlineNoteTA');
  if (ta) {
    ta.focus();
    // Scroll into view after keyboard opens
    setTimeout(() => ta.scrollIntoView({ behavior: 'smooth', block: 'center' }), 200);
  }
}

async function ntdSaveNote(taskId) {
  const ta = document.getElementById('ntdInlineNoteTA');
  const text = ta?.value.trim();
  if (!text) { showToast('Note cannot be empty', 'error'); return; }
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const user = currentUser;
  const note = {
    id: 'note-' + Date.now(),
    userId: user?.id || 0,
    userName: user?.name || 'Unknown',
    role: currentRole,
    type: 'text',
    content: text,
    timestamp: Date.now()
  };
  if (!task.notes) task.notes = [];
  task.notes.push(note);  // append — allows multiple notes
  markDirty();
  // fbPut, not fbPatch — db.tasks is a real array, and PATCHing a raw array
  // corrupts it server-side into a numeric-keyed object (same established
  // Firebase quirk documented on fbPut above, and the exact bug that broke
  // habit completion syncing — see the note on saveHabit()).
  try { await fbPut('tasks', db.tasks); } catch(e){}
  document.getElementById('ntdInlineNoteSheet')?.remove();
  showToast('Note saved ✓', 'success');
  _ntdRefreshNotes(taskId);
}

function ntdOpenCamera(taskId) {
  // Create a fresh file input each time to avoid stale state on Android WebView
  let fi = document.getElementById('ntdFileInput');
  if (!fi) {
    fi = document.createElement('input');
    fi.type = 'file';
    fi.id = 'ntdFileInput';
    fi.accept = 'image/*';
    fi.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(fi);
  }
  fi.value = '';  // clear previous selection
  fi.dataset.taskid = taskId;
  fi.onchange = () => ntdHandlePhoto(taskId, fi);
  fi.click();
}

function ntdHandlePhoto(taskId, input) {
  const file = input?.files?.[0]; if (!file) return;
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const user = currentUser;
  const reader = new FileReader();
  reader.onload = async e => {
    const dataUrl = e.target.result;
    let content = dataUrl;
    try { content = await uploadImageToDrive(dataUrl, 'task_' + taskId + '_' + Date.now() + '.jpg', 'misc'); }
    catch (err) { console.error('Drive upload failed, keeping photo inline instead:', err); }
    const note = {
      id: 'note-' + Date.now(),
      userId: user?.id || 0,
      userName: user?.name || 'Unknown',
      role: currentRole,
      type: 'photo',
      content: content,
      timestamp: Date.now()
    };
    if (!task.notes) task.notes = [];
    task.notes.push(note);
    markDirty();
    try { await fbPut('tasks', db.tasks); } catch(e){}
    showToast('Photo added ✓', 'success');
    _ntdRefreshNotes(taskId);
    input.value = '';
  };
  reader.onerror = () => showToast('Failed to read image', 'error');
  reader.readAsDataURL(file);
}

function _ntdRefreshNotes(taskId) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const heroColor = (typeof _habitGetIconColor === 'function') ? _habitGetIconColor(task) : (task.iconColor || task.color || '#e85d26');
  const isAdminView = currentRole === 'admin';
  // Fix 7: ALL notes visible to both admin and intern
  const visibleNotes = task.notes || [];
  const section = document.getElementById('ntdNotesSection'); if (!section) return;
  section.dataset.color = heroColor;
  section.innerHTML = _buildNotesTimeline(visibleNotes, heroColor, isAdminView);
}

// ╔══════════════════════════════════════════════════╗
// ║              SHARE TASK (Individual role)         ║
// ╚══════════════════════════════════════════════════╝
// Individual accounts each live in their own solo organization (see
// _authPickRole()'s 'individual' branch — a fresh newOrgId is minted per
// signup), so — unlike admin/trainee "sharedWith" further up, which just
// adds a second id to an array everyone in the SAME org's realtime stream
// already sees — sharing a personal task across two individual accounts
// means crossing organizations/{orgId}/data boundaries the realtime
// subscription (_thStartRealtime) never reaches. Rather than attempt a
// live cross-org subscription (a much larger change touching loadDB/
// patchDB/every stat function that assumes `db` is one org's blob), we
// give the recipient their own independent COPY of the task, written
// straight into their org via the root-level fbRootGet/fbRootPut helpers
// (same ones the org directory / user roster already use for exactly this
// "reach outside my own org" need). It's assignedTo/createdBy them, so it
// appears in their list, they can complete it, and it counts in their own
// stats the same as any task they created themselves — just tagged with
// sharedFromName/sharedFromTaskId so both sides can see the link. The two
// copies do NOT stay in sync after that (each side's completion is their
// own) — intentional: this is "send them a copy of my task", not a live
// shared checklist, and needing true two-way sync is exactly the
// cross-org realtime problem described above.

// ── Add Participants (task-creation picker) ──────────────────────────────
// Same delivery mechanism as the Share button above (_deliverTaskCopyToUser),
// just chosen BEFORE the task exists yet — selections are held in
// window._ctParticipants and only actually delivered once saveCustomTask()
// has built the real task object. Suggestions come from db.shareContacts
// (see _recordShareContact()), sorted most-recent-first.
function openAddParticipantsPage() {
  if (!window._ctParticipants) window._ctParticipants = [];
  const html = `
  <div class="ct-overlay visible" id="apOverlay" onclick=""></div>
  <div class="ct-page open" id="apPage">
    <div class="ct-header">
      <button class="ct-back-btn" onclick="_apClose()">
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
      <span class="ct-header-title">Add Participants</span>
      <button class="ct-back-btn" onclick="_apClose()">
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
      </button>
    </div>
    <div class="ct-body">
      <div class="ct-field-wrap" style="padding-top:16px;">
        <span class="ct-field-label">To</span>
        <input type="text" id="apSearchInput" class="ct-search-input" placeholder="Search person by name" autocomplete="off" oninput="_apSearchInputHandler()">
      </div>
      <div class="ct-field-wrap" style="padding-top:2px;">
        <span class="ct-field-label">Invite</span>
        <input type="email" id="apInviteInput" class="ct-search-input" placeholder="Enter email" autocomplete="off" onkeydown="if(event.key==='Enter'){event.preventDefault();_apInviteByEmail();}">
      </div>
      <div id="apChipsRow" class="ap-chips-row">${_apChipsHtml()}</div>
      <div class="ct-section" style="padding-top:6px;">
        <div class="ct-section-label">Suggestions</div>
        <div id="apSuggestions" class="share-results">${_apSuggestionsHtml('')}</div>
      </div>
    </div>
  </div>`;
  document.getElementById('apWrapper')?.remove();
  const w = document.createElement('div'); w.id = 'apWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  if (window.lucide) lucide.createIcons();
}

function _apClose() {
  document.getElementById('apWrapper')?.remove();
  // Refresh the (still open) create-task panel's participants row
  const preview = document.getElementById('ctParticipantsPreview');
  if (preview) {
    const n = (window._ctParticipants||[]).length;
    preview.textContent = n ? `${n} participant${n>1?'s':''} added` : 'Add Participants (optional)';
    preview.classList.toggle('has-text', !!n);
  }
}

function _apChipsHtml() {
  const list = window._ctParticipants || [];
  if (!list.length) return '';
  return list.map(p => `
    <span class="ap-chip">
      ${sanitize(p.name)}
      <button type="button" class="ap-chip-x" onclick="_apRemoveParticipant('${p.id}')">✕</button>
    </span>`).join('');
}

function _apRefreshChips() {
  const el = document.getElementById('apChipsRow');
  if (el) el.innerHTML = _apChipsHtml();
}

function _apIsAdded(id) {
  return (window._ctParticipants||[]).some(p => String(p.id) === String(id));
}

function _apAddParticipant(id, name, email) {
  if (!window._ctParticipants) window._ctParticipants = [];
  if (String(id) === String(currentUser?.id)) { showToast("You're already on this task", 'error'); return; }
  if (_apIsAdded(id)) return;
  window._ctParticipants.push({ id, name, email });
  _apRefreshChips();
  const q = document.getElementById('apSearchInput')?.value.trim() || '';
  _apRenderSuggestions(q);
}

function _apRemoveParticipant(id) {
  window._ctParticipants = (window._ctParticipants||[]).filter(p => String(p.id) !== String(id));
  _apRefreshChips();
  const q = document.getElementById('apSearchInput')?.value.trim() || '';
  _apRenderSuggestions(q);
}

// Default (no query) list: this account's share history, most-recent-first.
// With a query: live directory search, same source _shareTaskSearch uses.
function _apSuggestionsHtml(query) {
  if (query) return `<div class="share-empty">Searching…</div>`; // replaced async by _apRenderSuggestions
  const contacts = (db.shareContacts || []).slice().sort((a,b) => (b.lastAt||0) - (a.lastAt||0)).slice(0, 8);
  if (!contacts.length) return `<div class="share-empty">Search above to add someone</div>`;
  return contacts.map(c => _apRowHtml(c.id, c.name, c.email)).join('');
}

function _apRowHtml(id, name, email) {
  const added = _apIsAdded(id);
  const initial = sanitize((name||email||'?').charAt(0).toUpperCase());
  // JS-string-literal escaping for the onclick attribute — separate from
  // sanitize()'s HTML escaping above (which leaves apostrophes untouched),
  // needed because these values get embedded inside single-quoted JS
  // string arguments in an onclick handler.
  const jsEsc = s => String(s||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
  return `<div class="share-user-row">
    <div class="share-user-avatar">${initial}</div>
    <div class="share-user-info">
      <div class="share-user-name">${sanitize(name||'User')}</div>
      <div class="share-user-email">${sanitize(email||'')}</div>
    </div>
    <button class="btn ${added?'btn-secondary':'btn-primary'} share-btn-mini" ${added?'disabled':''} onclick="_apAddParticipant('${id}','${jsEsc(name)}','${jsEsc(email)}')">${added?'Added':'Add'}</button>
  </div>`;
}

let _apSearchTimer = null;
function _apSearchInputHandler() {
  clearTimeout(_apSearchTimer);
  const q = document.getElementById('apSearchInput')?.value.trim() || '';
  if (!q) { _apRenderSuggestions(''); return; }
  const el = document.getElementById('apSuggestions');
  if (el) el.innerHTML = `<div class="share-empty">Searching…</div>`;
  _apSearchTimer = setTimeout(() => _apRenderSuggestions(q), 350);
}

async function _apRenderSuggestions(query) {
  const el = document.getElementById('apSuggestions');
  if (!el) return;
  if (!query) { el.innerHTML = _apSuggestionsHtml(''); return; }
  try {
    const allUsers = await fbRootGet('users') || {};
    const q = query.toLowerCase();
    const matches = Object.keys(allUsers)
      .map(uid => ({ uid, rec: allUsers[uid] }))
      .filter(({ uid, rec }) => {
        if (!rec || uid === String(currentUser.id)) return false;
        const name = (rec.name || '').toLowerCase();
        const email = (rec.email || '').toLowerCase();
        return name.includes(q) || email.includes(q);
      })
      .slice(0, 8);
    if (document.getElementById('apSearchInput')?.value.trim().toLowerCase() !== q) return; // stale
    if (!matches.length) { el.innerHTML = `<div class="share-empty">No matching users found</div>`; return; }
    el.innerHTML = matches.map(({ uid, rec }) => {
      const name = rec.name || rec.email || 'User';
      return _apRowHtml(uid, name, rec.email || '');
    }).join('');
  } catch (e) {
    console.error('[addParticipants] search failed', e);
    el.innerHTML = `<div class="share-empty">Search failed — check your connection</div>`;
  }
}

async function _apInviteByEmail() {
  const input = document.getElementById('apInviteInput');
  const email = input?.value.trim().toLowerCase();
  if (!email || !email.includes('@')) { showToast('Enter a valid email', 'error'); return; }
  try {
    const allUsers = await fbRootGet('users') || {};
    const match = Object.keys(allUsers).map(uid => ({ uid, rec: allUsers[uid] }))
      .find(({rec}) => (rec?.email||'').toLowerCase() === email);
    if (!match) {
      // No existing account — send a real invite email via EmailJS (see
      // EMAILJS_INVITE_TEMPLATE_ID above) instead of just adding them,
      // since there's no uid yet to deliver a task copy to.
      const taskTitle = document.getElementById('ptTitle')?.value.trim() || 'a task';
      const sent = await _sendTaskInviteEmail(email, taskTitle);
      if (sent) showToast(`Invite sent to ${email} ✓`, 'success');
      // _sendTaskInviteEmail already toasts its own error if it fails/isn't configured.
      if (input && sent) input.value = '';
      return;
    }
    _apAddParticipant(match.uid, match.rec.name || match.rec.email, match.rec.email || '');
    if (input) input.value = '';
    showToast('Added ✓', 'success');
  } catch (e) {
    console.error('[addParticipants] invite lookup failed', e);
    showToast('Could not look up that email — check your connection', 'error');
  }
}

function openShareTaskSheet(taskId) {
  const task = db.tasks.find(t => t.id == taskId);
  if (!task || !task.isPersonal || task.createdBy != currentUser?.id) return;
  const sharedWith = task.sharedToUsers || [];
  openModal(`
    <div class="modal-title">Share "${sanitize(task.title)}"</div>
    <div class="form-group">
      <label>Search by username or email</label>
      <input type="text" id="shareUserSearch" placeholder="Type at least 2 characters…" autocomplete="off"
             oninput="_shareTaskSearchInput('${task.id}')">
    </div>
    <div id="shareSearchResults" class="share-results"></div>
    ${sharedWith.length ? `
      <div class="share-already-hd">Already shared with</div>
      <div class="share-already-list">
        ${sharedWith.map(u => `
          <div class="share-user-row">
            <div class="share-user-avatar">${sanitize((u.name||'?').charAt(0).toUpperCase())}</div>
            <div class="share-user-info">
              <div class="share-user-name">${sanitize(u.name)}</div>
              <div class="share-user-email">${sanitize(u.email||'')}</div>
            </div>
          </div>`).join('')}
      </div>` : ''}
    <div class="modal-actions">
      <button class="btn btn-secondary" onclick="closeModal()">Done</button>
    </div>
  `);
}

let _shareSearchTimer = null;
function _shareTaskSearchInput(taskId) {
  clearTimeout(_shareSearchTimer);
  const q = document.getElementById('shareUserSearch')?.value.trim() || '';
  const results = document.getElementById('shareSearchResults');
  if (q.length < 2) { if (results) results.innerHTML = ''; return; }
  if (results) results.innerHTML = `<div class="share-empty">Searching…</div>`;
  _shareSearchTimer = setTimeout(() => _shareTaskSearch(taskId, q), 350);
}

async function _shareTaskSearch(taskId, query) {
  const results = document.getElementById('shareSearchResults');
  if (!results) return;
  try {
    const allUsers = await fbRootGet('users') || {};
    const q = query.toLowerCase();
    const task = db.tasks.find(t => t.id == taskId);
    const alreadyShared = new Set((task?.sharedToUsers || []).map(u => String(u.id)));
    const matches = Object.keys(allUsers)
      .map(uid => ({ uid, rec: allUsers[uid] }))
      .filter(({ uid, rec }) => {
        if (!rec || uid === String(currentUser.id)) return false;
        if (alreadyShared.has(uid)) return false;
        const name = (rec.name || '').toLowerCase();
        const email = (rec.email || '').toLowerCase();
        return name.includes(q) || email.includes(q);
      })
      .slice(0, 8);
    // Search box may have moved on / query changed while this was in flight
    if (document.getElementById('shareUserSearch')?.value.trim().toLowerCase() !== q) return;
    if (!matches.length) { results.innerHTML = `<div class="share-empty">No matching users found</div>`; return; }
    results.innerHTML = matches.map(({ uid, rec }) => {
      const name = sanitize(rec.name || rec.email || 'User');
      const email = sanitize(rec.email || '');
      const initial = sanitize((rec.name || rec.email || '?').charAt(0).toUpperCase());
      const orgId = sanitize(rec.orgId || '');
      return `<div class="share-user-row">
        <div class="share-user-avatar">${initial}</div>
        <div class="share-user-info">
          <div class="share-user-name">${name}</div>
          <div class="share-user-email">${email}</div>
        </div>
        <button class="btn btn-primary share-btn-mini" onclick="shareTaskWithUser('${taskId}','${uid}','${orgId}')">Share</button>
      </div>`;
    }).join('');
  } catch (e) {
    console.error('[shareTask] user search failed', e);
    results.innerHTML = `<div class="share-empty">Search failed — check your connection</div>`;
  }
}

// Delivers an independent copy of `sourceTask` into targetUid's own org
// (targetOrgId) and notifies them — the shared piece behind both the
// task-detail "Share" button (shareTaskWithUser) and the "Add
// Participants" picker in task creation (saveCustomTask). See the big
// comment above openShareTaskSheet() for why this is a copy, not a live
// link, and why it needs root-level cross-org writes at all.
async function _deliverTaskCopyToUser(sourceTask, targetUid, targetOrgId, targetName) {
  const newTask = {
    id: 'st-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
    title: sourceTask.title,
    description: sourceTask.description || '',
    dueDate: sourceTask.dueDate || '',
    repeat: null,
    category: sourceTask.category || 'Personal',
    priority: sourceTask.priority || 'None',
    isPersonal: true,
    createdBy: targetUid, assignedTo: targetUid,
    createdDate: today(), createdAt: Date.now(),
    points: sourceTask.points || 0, approvalRequired: false,
    isTemplate: false,
    iconSvg: sourceTask.iconSvg || null, iconColor: sourceTask.iconColor || null,
    checklist: (sourceTask.checklist && sourceTask.checklist.length) ? sourceTask.checklist.map(i => ({ id: i.id, text: i.text, done: false })) : null,
    symbol: sourceTask.symbol || null,
    attachmentName: sourceTask.attachmentName || null,
    sharedFromUserId: currentUser.id,
    sharedFromName: currentUser.name,
    sharedFromTaskId: sourceTask.id,
    // The sender's own org — cached here at share time (rather than looked
    // up again later) so that when the RECIPIENT eventually completes this
    // copy, _notifyShareSenderOnComplete() knows exactly which org's
    // taskCompletions/notifications to write back into without another
    // fbRootGet('users') round trip.
    sharedFromOrgId: window.currentOrgId || TXP_ORG_ID,
  };

  // Root-level read-modify-write against the RECIPIENT's own org — same
  // "no live subscription, just fetch/patch the exact path" approach
  // _refreshInternsRoster/_refreshPendingJoinReqCount already use for
  // reaching outside the current org.
  const targetTasksPath = `organizations/${targetOrgId}/data/tasks`;
  const targetTasks = await fbRootGet(targetTasksPath) || [];
  targetTasks.push(newTask);
  await fbRootPut(targetTasksPath, targetTasks);

  // Notify the recipient — real in-app notification entry, same shape
  // pushInternNotif() writes, plus a real FCM push via the existing
  // pushQueue mechanism (_enqueuePush, defined up near registerDeviceToken
  // — it's root-level/fbPost already, so it reaches the recipient's device
  // regardless of which org they're in, same as the writes above).
  const notifPath = `organizations/${targetOrgId}/data/notifications/${targetUid}`;
  const targetNotifs = await fbRootGet(notifPath) || [];
  const notifEntry = {
    id: 'n-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
    type: 'task_shared',
    title: 'Task Shared With You',
    body: `${currentUser.name} shared "${sourceTask.title}" with you`,
    read: false, createdAt: Date.now(),
  };
  targetNotifs.unshift(notifEntry);
  if (targetNotifs.length > NOTIF_MAX_PER_INBOX) targetNotifs.length = NOTIF_MAX_PER_INBOX;
  await fbRootPut(notifPath, targetNotifs);
  _enqueuePush('intern', targetUid, notifEntry, notifEntry.id);
}

// Recent/frequent "Suggestions" in the participant picker are sourced
// from this — every id ever shared with, on this account, gets one entry
// here that keeps a running count + last-shared time. Lives inside `db`
// (persisted the same way tasks/habits are) since — unlike the cross-org
// writes above — it only needs to be readable by the sharer themselves.
function _recordShareContact(id, name, email) {
  if (!db.shareContacts) db.shareContacts = [];
  const existing = db.shareContacts.find(c => String(c.id) === String(id));
  if (existing) {
    existing.count = (existing.count || 1) + 1;
    existing.lastAt = Date.now();
    existing.name = name; existing.email = email; // keep in sync in case they changed it
  } else {
    db.shareContacts.push({ id, name, email, count: 1, lastAt: Date.now() });
  }
  markDirty();
}

// Called right after a RECIPIENT marks a shared task's copy done (see the
// completeTask()/ntdChangeStatus() call sites below) — tells the original
// sender it's done, two ways: a real push (same pushQueue/_enqueuePush
// mechanism as everything else in this file — TxpMessagingService.kt on
// the native side is generic over notification `type`, so nothing there
// needs to change to support this) and marking the SENDER'S OWN original
// copy's status as done too, via a targeted cross-org PATCH.
//
// Deliberately one-directional and one-shot: this only fires on the
// RECIPIENT completing THEIR copy, never the reverse, and never on
// un-completing/undo — so the sender's copy can't flip back to incomplete
// under them just because the recipient hit the 5-second undo toast. If
// two-way sync (undo included) turns out to matter, it's a small extension
// of this same function; not built in until it's actually needed.
//
// taskCompletions is a plain {key: {done}} MAP (not an array), so a PATCH
// with just the one key is safe here — this is exactly the kind of PATCH
// patchDB()'s self-heal comment (search "SELF-HEAL" above) warns is unsafe
// for ARRAYS like tasks/habits, but taskCompletions was never one.
async function _notifyShareSenderOnComplete(task) {
  if (!task || !task.sharedFromUserId || !task.sharedFromOrgId || !task.sharedFromTaskId) return; // not a received share
  const senderId = task.sharedFromUserId, senderOrgId = task.sharedFromOrgId;
  try {
    // Mark the sender's own original task's status as done too.
    const senderKey = task.sharedFromTaskId + '-' + senderId;
    await fbRootPatch(`organizations/${senderOrgId}/data/taskCompletions`, { [senderKey]: { done: true } });

    // Real in-app notification + real push, same shape/mechanism as every
    // other cross-org notification in this feature (see
    // _deliverTaskCopyToUser above).
    const notifPath = `organizations/${senderOrgId}/data/notifications/${senderId}`;
    const notifs = await fbRootGet(notifPath) || [];
    const entry = {
      id: 'n-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
      type: 'task_completed',
      title: 'Task Completed',
      body: `${currentUser.name} completed "${task.title}"`,
      read: false, createdAt: Date.now(),
    };
    notifs.unshift(entry);
    if (notifs.length > NOTIF_MAX_PER_INBOX) notifs.length = NOTIF_MAX_PER_INBOX;
    await fbRootPut(notifPath, notifs);
    _enqueuePush('intern', senderId, entry, entry.id);
  } catch (e) {
    // Best-effort, same as _enqueuePush elsewhere — the recipient's own
    // completion (already applied to their local db before this is called)
    // must never be rolled back just because notifying the sender failed.
    console.warn('[shareTask] notifying sender of completion failed', e);
  }
}

async function shareTaskWithUser(taskId, targetUid, targetOrgId) {
  const task = db.tasks.find(t => t.id == taskId);
  if (!task || !task.isPersonal || task.createdBy != currentUser?.id) return;
  if (!targetOrgId) { showToast('Could not share — that user has no account set up yet', 'error'); return; }
  const btn = event?.target;
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  try {
    const targetUsers = await fbRootGet('users') || {};
    const targetRec = targetUsers[targetUid];
    if (!targetRec) { showToast('User not found', 'error'); return; }
    const targetName = targetRec.name || targetRec.email || 'User';
    const targetEmail = targetRec.email || '';

    await _deliverTaskCopyToUser(task, targetUid, targetOrgId, targetName);

    // Record on MY copy who I've shared it with
    if (!task.sharedToUsers) task.sharedToUsers = [];
    task.sharedToUsers.push({ id: targetUid, name: targetName, email: targetEmail });
    _recordShareContact(targetUid, targetName, targetEmail);
    markDirty();
    try { await fbPut('tasks', db.tasks); } catch (e) {}
    try { await fbPut('shareContacts', db.shareContacts); } catch (e) {}

    showToast(`Shared with ${targetName} ✓`, 'success');
    openShareTaskSheet(taskId); // refresh the sheet (moves them into "Already shared with")
  } catch (e) {
    console.error('[shareTask] failed', e);
    showToast('Could not share task — check your connection', 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Share'; }
  }
}

function ntdOpenLightbox(src) {
  openModal(`<div style="padding:0;margin:-20px;"><img src="${src}" style="width:100%;border-radius:8px;display:block;" alt="Attachment"></div>`);
}

async function ntdToggleCheckItem(taskId, itemId, checked, iid) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const item = (task.checklist||[]).find(i => i.id == itemId);
  if (!item) return;
  item.done = checked;
  // Update visual immediately
  const textEl = document.querySelector(`#ntdci-${itemId} .ntd-check-text`);
  if (textEl) { textEl.classList.toggle('ntd-check-done', checked); }
  // Update badge count
  const doneCount = (task.checklist||[]).filter(i=>i.done).length;
  const total = (task.checklist||[]).length;
  const badge = document.querySelector('#ntdAcc_Checklist .ntd-acc-count');
  if (badge) badge.textContent = `${doneCount}/${total}`;
  markDirty();
  try { await fbPut('tasks', db.tasks); } catch(e){}
}

// Keep openAdminTaskDetail wired to new detail for kanban
function openAdminTaskDetail(tid) { _openNewTaskDetail(tid); }


function toggleTdpDesc() {
  const desc = document.getElementById('tdvDesc');
  const btn  = document.getElementById('tdvExpandBtn');
  if (!desc) return;
  const expanded = desc.dataset.expanded === '1';
  if (expanded) {
    desc.style.maxHeight = '88px';
    desc.dataset.expanded = '0';
    btn.style.transform = '';
  } else {
    desc.style.maxHeight = desc.scrollHeight + 'px';
    desc.dataset.expanded = '1';
    btn.style.transform = 'rotate(180deg)';
  }
}


function closeTdp() {
  const tdp = document.getElementById('tdp');
  if (tdp) { tdp.classList.remove('open'); setTimeout(() => document.getElementById('tdpWrapper')?.remove(), 300); }
  const ov = document.getElementById('tdpOverlay');
  if (ov) ov.classList.remove('visible');
}

async function tdpSubmitCode(tid, iid) {
  const codeInput = document.getElementById('tdpCodeInput');
  const code = codeInput?.value.trim();
  if (!code) return;
  const codeHash = await sha256(code);
  const contrib  = db.contributors?.find(c => c.codeHash === codeHash);
  const task     = db.tasks.find(t => t.id == tid);
  if (!contrib) {
    showToast('Invalid code — try again', 'error');
    if (codeInput) { codeInput.value = ''; document.getElementById('tdpSaveBtn').style.display='none'; }
    return;
  }
  if (task.approvalContribId && contrib.id !== task.approvalContribId) {
    const ac = db.contributors?.find(c => c.id === task.approvalContribId);
    showToast('Wrong contributor. Required: ' + (ac?.name||'assigned'), 'error');
    if (codeInput) { codeInput.value = ''; document.getElementById('tdpSaveBtn').style.display='none'; }
    return;
  }
  const key = tid + '-' + iid;
  db.taskCompletions[key] = {done: true};
  if (task.points) {
    const pts = Math.max(0, Math.min(task.points, 9999));
    db.submissions[iid].points = Math.max(0, (db.submissions[iid].points||0) + pts);
    db.submissions[iid].pointHistory = db.submissions[iid].pointHistory||[];
    db.submissions[iid].pointHistory.unshift({type:'task_approval',label:task.title,pts:task.points,date:today()});
  }
  playSuccessSound();
  closeTdp();
  await saveAndRefresh('Task completed! +' + (task.points||0) + ' pts', 'internTasks');
}

