async function saveEditCustomTask(tid) {
  const task = db.tasks.find(t => t.id == tid); if (!task) return;
  const title = document.getElementById('ectTitle').value.trim();
  if (!title) { showToast('Title required', 'error'); return; }
  task.title       = title;
  task.description = document.getElementById('ectDesc').value;
  task.category    = document.getElementById('ectCat').value;
  task.dueDate     = document.getElementById('ectDue').value;
  closeModal();
  await saveAndRefresh('Task updated!', 'internTasks');
}


// BUG-10 FIX: Task completion now has a 5-second undo window before saving to Firebase.
// Play a short success chime using Web Audio API
function playSuccessSound() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const times = [[0, 523.25], [0.12, 659.25], [0.24, 783.99]]; // C5 E5 G5
    times.forEach(([when, freq]) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      osc.frequency.value = freq;
      osc.type = 'sine';
      gain.gain.setValueAtTime(0.18, ctx.currentTime + when);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + when + 0.35);
      osc.start(ctx.currentTime + when);
      osc.stop(ctx.currentTime + when + 0.35);
    });
  } catch(e) {}
}

// Confetti burst celebration
function showCelebration(circleEl) {
  const el = circleEl || document.body;
  const rect = el.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const colors = ['#e85d26','#27ae60','#f59e0b','#3b82f6','#8b5cf6','#ef4444','#10b981'];
  for (let i = 0; i < 28; i++) {
    const dot = document.createElement('div');
    const angle = (Math.random() * 360) * Math.PI / 180;
    const dist = 50 + Math.random() * 90;
    const size = 4 + Math.random() * 5;
    dot.style.cssText = `position:fixed;left:${cx}px;top:${cy}px;width:${size}px;height:${size}px;
      border-radius:50%;background:${colors[i % colors.length]};pointer-events:none;z-index:9999;
      transition:transform .6s cubic-bezier(.22,1,.36,1),opacity .5s .2s;`;
    document.body.appendChild(dot);
    requestAnimationFrame(() => {
      dot.style.transform = `translate(${Math.cos(angle)*dist}px, ${Math.sin(angle)*dist}px) scale(0)`;
      dot.style.opacity = '0';
    });
    setTimeout(() => dot.remove(), 800);
  }
  // Pulse the circle
  if (circleEl) {
    circleEl.style.transform = 'scale(1.4)';
    circleEl.style.transition = 'transform .25s cubic-bezier(.34,1.56,.64,1)';
    setTimeout(() => { circleEl.style.transform = ''; }, 300);
  }
}

// Complete from dashboard task list (re-renders dashboard)
function completeTaskFromDash(tid, iid) {
  const circleEl = event?.target?.closest?.('.dash-task-circle');
  completeTask(tid, iid, circleEl, 'dashboard');
}

async function completeTask(tid, iid, circleEl, source) {
  const task = db.tasks.find(t => t.id == tid); if (!task) return;
  const key = tid + '-' + iid;
  if (db.taskCompletions[key]?.done) return;

  // Snapshot scroll + carousel position BEFORE re-render
  const ca = document.getElementById('contentArea');
  const savedScroll = ca ? ca.scrollTop : 0;
  const savedCarousel = {};
  document.querySelectorAll('.cp-tab-strip').forEach(strip => {
    strip.querySelectorAll('.cp-tab').forEach((tab, i) => {
      if (tab.classList.contains('active')) savedCarousel[strip.id] = i;
    });
  });

  function restorePosition() {
    requestAnimationFrame(() => {
      Object.entries(savedCarousel).forEach(([stripId, idx]) => {
        carouselGoTo(stripId.replace('-strip', ''), idx, false);
      });
      const ca2 = document.getElementById('contentArea');
      if (ca2) ca2.scrollTop = savedScroll;
    });
  }

  // Play sound + celebration immediately
  playSuccessSound();
  if (circleEl) showCelebration(circleEl);

  // Apply completion optimistically in memory
  db.taskCompletions[key] = { done: true };
  const pts = task.points || 0;
  let coinsEarned = 0;
  if (pts) {
    if (!db.submissions[iid]) db.submissions[iid] = {points:0};
    db.submissions[iid].points = (db.submissions[iid].points || 0) + pts;
    db.submissions[iid].pointHistory = db.submissions[iid].pointHistory || [];
    db.submissions[iid].pointHistory.unshift({ type: 'task', label: task.title, pts, date: today() });
    // This flow was never converting XP into coins — fixed to match how
    // request-approval completion already does it.
    coinsEarned = awardCoins(iid, pts, 'task', task.title, tid);
  }
  // BUG FIX: this used to fire inside the undo-toast's deferred COMMIT
  // callback below, 5s later. showUndoToast() keeps only ONE pending
  // commit at a time in a global (window._undoCallbacks/_undoTimer) — so
  // completing a second task before the first one's 5s window elapsed
  // silently cancelled the first task's timer entirely, and its
  // pushAdminNotif() call never ran. Firing it here, optimistically and
  // immediately (same moment points/coins are applied), means every
  // completion always notifies admin regardless of how fast the intern
  // checks off multiple tasks in a row.
  pushAdminNotif({ type:'task_completed', title:'Task Completed', body:`${currentUser.name} completed "${task.title}"`, internId: iid });
  if (task.isPersonal && task.sharedFromUserId) _notifyShareSenderOnComplete(task);

  // Re-render same page/view — then restore position
  const caEl = document.getElementById('contentArea');
  if (source === 'dashboard') renderInternDashboard(caEl);
  else renderInternTasks(caEl);
  restorePosition();

  // Cancel any previous undo
  if (_undoTimer) clearTimeout(_undoTimer);

  showUndoToast(coinsEarned > 0 ? `Task completed! +${pts} pts · +${coinsEarned} coin${coinsEarned!==1?'s':''}` : `Task completed! +${pts} pts`, () => {
    // ─── UNDO ───
    delete db.taskCompletions[key];
    if (pts) {
      db.submissions[iid].points = Math.max(0, (db.submissions[iid].points || 0) - pts);
      db.submissions[iid].pointHistory = (db.submissions[iid].pointHistory || []).slice(1);
    }
    if (coinsEarned > 0) {
      const w = _getWallet(iid);
      w.balance     = Math.max(0, w.balance - coinsEarned);
      w.totalEarned = Math.max(0, w.totalEarned - coinsEarned);
      w.transactions.shift(); // remove the transaction awardCoins() just added
    }
    const ca2 = document.getElementById('contentArea');
    if (source === 'dashboard') renderInternDashboard(ca2);
    else renderInternTasks(ca2);
    restorePosition();
    updateBadges();
  }, async () => {
    // ─── COMMIT ───
    try { await saveDB(); showStatus('✓ Saved!'); updateBadges(); }
    catch(e) { showToast('Save failed — please sync.', 'error'); }
  });
}

function openApprovalDlg(tid, iid) {
  const task = db.tasks.find(t => t.id == tid);
  const ac = task.approvalContribId ? db.contributors.find(c => c.id === task.approvalContribId) : null;
  openModal(`<div class="modal-title">🔐 Request Approval</div>
    <div style="font-size:13px;color:var(--text2);margin-bottom:10px;">Task: <strong style="color:var(--text);">${task.title}</strong></div>
    ${ac ? `<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:9px 13px;font-size:12px;margin-bottom:12px;">Required contributor: <strong style="color:#1d4ed8;">${ac.name}</strong></div>` : ''}
    <div class="form-group"><label>Contributor Code</label><input type="password" id="approvalCode" placeholder="Enter code" autocomplete="off"></div>
    <div class="modal-actions">
      <button class="btn btn-secondary" onclick="closeModal()">Cancel</button>
      <button class="btn btn-primary" onclick="submitApproval('${tid}','${iid}')">Submit</button>
    </div>`);
}

async function submitApproval(tid, iid) {
  const code = document.getElementById('approvalCode').value.trim();
  const task  = db.tasks.find(t => t.id == tid);
  // FIX-1: hash-based lookup — no plaintext comparison
  const codeHash = await sha256(code);
  const contrib = db.contributors.find(c => c.codeHash === codeHash);
  if (!contrib) { showToast('Invalid code', 'error'); return; }
  if (task.approvalContribId && contrib.id !== task.approvalContribId) {
    const ac = db.contributors.find(c => c.id === task.approvalContribId);
    showToast('Wrong contributor. Required: ' + (ac?.name || 'assigned contributor'), 'error'); return;
  }
  const key = tid + '-' + iid;
  db.taskCompletions[key] = {done: true};
  // FIX-5: clamp task completion points
  if (task.points) {
    const _tp = Math.max(0, Math.min(task.points || 0, 9999));
    db.submissions[iid].points = Math.max(0, (db.submissions[iid].points || 0) + _tp);
  }
  // Add to point history
  if (task.points) {
    db.submissions[iid].pointHistory = db.submissions[iid].pointHistory || [];
    db.submissions[iid].pointHistory.unshift({ type:'task_approval', label: task.title, pts: task.points, date: today() });
  }
  playSuccessSound();
  closeModal();
  pushAdminNotif({ type:'task_completed', title:'Task Completed', body:`${currentUser.name} completed "${task.title}"`, internId: iid });
  await saveAndRefresh('Approved & completed! +' + (task.points||0) + ' pts', 'internTasks');
}

