// Monthly completion counts for a 6-month window. offset=0 is the most
// recent 6 months (ending this month); offset=1 is the 6 months before
// that, etc. — navigated via the chevrons without reopening the whole page.
function _haGetMonthlyCompletions(habitId, internId, offset) {
  const comps = db.habitCompletions?.[internId]?.[habitId] || {};
  const completedDates = Object.keys(comps).filter(d => comps[d]);
  const anchor = new Date(_hToday() + 'T00:00:00');
  const months = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(anchor.getFullYear(), anchor.getMonth() - offset*6 - i, 1);
    const y = d.getFullYear(), m = d.getMonth();
    const count = completedDates.filter(ds => {
      const dd = new Date(ds + 'T00:00:00');
      return dd.getFullYear() === y && dd.getMonth() === m;
    }).length;
    months.push({ label: d.toLocaleDateString('en-US', {month:'short'}), count });
  }
  return months;
}

function _haBuildCompletionChartHtml(habitId, internId, offset, color) {
  const months = _haGetMonthlyCompletions(habitId, internId, offset);
  const rawMax = Math.max(1, ...months.map(m => m.count));
  const axisMax = Math.max(30, Math.ceil(rawMax / 10) * 10);
  const ticks = [axisMax, Math.round(axisMax*2/3), Math.round(axisMax/3), 0];
  return `
    <div style="display:flex;gap:10px;height:160px;">
      <div style="display:flex;flex-direction:column;justify-content:space-between;font-size:11px;color:var(--text3);padding:2px 0;">
        ${ticks.map(t => `<span>${t}</span>`).join('')}
      </div>
      <div style="flex:1;display:flex;align-items:flex-end;gap:10px;border-left:1px solid var(--border);padding-left:10px;">
        ${months.map(m => `
          <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:6px;height:100%;justify-content:flex-end;">
            <div style="width:60%;min-width:14px;height:${Math.max(2, m.count/axisMax*100)}%;background:${color};border-radius:4px 4px 0 0;"></div>
            <span style="font-size:11px;color:var(--text3);">${m.label}</span>
          </div>`).join('')}
      </div>
    </div>`;
}

// Chevron navigation for the Completion chart — re-renders only the chart,
// not the whole Analytics page.
function _haNavCompletion(dir) {
  if (!window._haChart) return;
  window._haChart.offset = Math.max(0, window._haChart.offset + dir);
  const box = document.getElementById('haCompletionChart');
  if (!box) return;
  const habit = (db.habits||[]).find(h => h.id === window._haChart.habitId);
  const color = habit?.color || '#F59E0B';
  box.innerHTML = _haBuildCompletionChartHtml(window._haChart.habitId, window._haChart.internId, window._haChart.offset, color);
}

// Full-year "Streak {year}" grid: one column per month (J F M A M J J A S O N
// D), each a stack of small squares — one per day of that month — colored
// in for days the habit was actually completed, pale otherwise. Shorter
// months just have fewer visible squares (padded with invisible spacers so
// every column still lines up at the top).
function _haBuildYearHeatmapHtml(habitId, internId, year, color) {
  const comps = db.habitCompletions?.[internId]?.[habitId] || {};
  const monthLabels = ['J','F','M','A','M','J','J','A','S','O','N','D'];
  const maxRows = 31;
  let cols = '';
  for (let m = 0; m < 12; m++) {
    const daysInMonth = new Date(year, m + 1, 0).getDate();
    let cells = '';
    for (let row = 0; row < maxRows; row++) {
      const day = row + 1;
      if (day > daysInMonth) {
        cells += `<div style="box-sizing:border-box;margin:0;width:15px;height:15px;flex-shrink:0;"></div>`;
      } else {
        const ds = `${year}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
        const filled = !!comps[ds];
        cells += `<div style="box-sizing:border-box;margin:0;width:15px;height:15px;border-radius:3.5px;background:${filled?color:'var(--surface2)'};flex-shrink:0;"></div>`;
      }
    }
    cols += `<div style="display:flex;flex-direction:column;align-items:center;gap:5px;flex-shrink:0;">
      <div style="font-size:10px;font-weight:600;color:var(--text3);margin-bottom:4px;">${monthLabels[m]}</div>
      ${cells}
    </div>`;
  }
  // Fixed max-height with its own vertical scroll so this section can never
  // balloon the surrounding card/page, regardless of row count.
  return `<div style="max-height:400px;overflow-y:auto;overflow-x:auto;"><div style="display:flex;gap:9px;padding-bottom:4px;width:max-content;">${cols}</div></div>`;
}

function _haNavYearHeatmap(dir) {
  if (!window._haYearHeatmap) return;
  window._haYearHeatmap.year += dir;
  const box = document.getElementById('haYearHeatmap');
  const title = document.getElementById('haYearHeatmapTitle');
  if (!box) return;
  const habit = (db.habits||[]).find(h => h.id === window._haYearHeatmap.habitId);
  const color = habit?.color || '#F59E0B';
  box.innerHTML = _haBuildYearHeatmapHtml(window._haYearHeatmap.habitId, window._haYearHeatmap.internId, window._haYearHeatmap.year, color);
  if (title) title.textContent = `Streak ${window._haYearHeatmap.year}`;
}

// Walks every scheduled day from the habit's start date to today and groups
// consecutive completed days into "runs" — same completion logic as
// _habitCalcStreak (non-scheduled days don't break a run; a missed
// scheduled day does). Returns runs most-recent-first.
function _haGetStreakRuns(habitId, internId) {
  const habit = (db.habits||[]).find(h=>h.id===habitId);
  if (!habit) return [];
  const comps = db.habitCompletions?.[internId]?.[habitId] || {};
  const td = _hToday();
  const startStr = habit.startDate || habit.createdDate || td;
  const start = new Date(startStr + 'T00:00:00');
  const end = new Date(td + 'T00:00:00');

  const runs = [];
  let curStart = null, curEnd = null, curLen = 0;
  const d = new Date(start);
  let guard = 0;
  while (d <= end && guard < 730) {
    const ds = dateToLocalStr(d);
    if (_habitIsScheduledForDate(habit, ds) && _habitIsInRange(habit, ds)) {
      if (comps[ds]) {
        if (curStart === null) curStart = ds;
        curEnd = ds;
        curLen++;
      } else if (curLen > 0) {
        runs.push({ start: curStart, end: curEnd, len: curLen });
        curStart = null; curEnd = null; curLen = 0;
      }
    }
    d.setDate(d.getDate() + 1);
    guard++;
  }
  if (curLen > 0) runs.push({ start: curStart, end: curEnd, len: curLen });
  return runs.reverse(); // most recent first
}

function _haBuildStreakRunsHtml(habitId, internId, color) {
  const runs = _haGetStreakRuns(habitId, internId).slice(0, 8); // already most-recent-first
  return _haRenderStreakRows(runs, color);
}

function _haBuildTopStreaksHtml(habitId, internId, color) {
  const runs = _haGetStreakRuns(habitId, internId)
    .slice()
    .sort((a, b) => b.len - a.len) // longest first
    .slice(0, 5);
  return _haRenderStreakRows(runs, color);
}

function _haRenderStreakRows(runs, color) {
  if (!runs.length) return `<div class="txp-empty">No streaks yet</div>`;
  const maxLen = Math.max(...runs.map(r => r.len));
  const fmt = ds => new Date(ds + 'T00:00:00').toLocaleDateString('en-US', {day:'numeric',month:'short',year:'numeric'});
  return runs.map(r => {
    const widthPct = 14 + (r.len / maxLen) * 70; // widest run ~84%, shortest still readable
    return `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 0;">
      <span style="font-size:12.5px;color:var(--text2);flex-shrink:0;">${fmt(r.start)}</span>
      <div style="flex:1;display:flex;justify-content:center;">
        <div style="width:${widthPct}%;min-width:26px;background:${color};border-radius:20px;text-align:center;padding:6px 0;font-size:13px;font-weight:800;color:#111;">${r.len}</div>
      </div>
      <span style="font-size:12.5px;color:var(--text2);flex-shrink:0;">${fmt(r.end)}</span>
    </div>`;
  }).join('');
}

function closeHabitAnalytics() {
  const ov = document.getElementById('hAnalyticsOv');
  if (!ov) return;
  ov.classList.remove('visible');
  document.getElementById('hAnalyticsPage')?.classList.remove('open');
  setTimeout(() => ov.remove(), 320);
}

// ── Admin: Create Habit Panel ─────────────────────────────────
let _habitCreateState = { color: '#F59E0B', iconSvg: null, freqMode: 'Everyday', dowSel: [], domSel: [], periodN: 3, periodUnit: 'week' };

function openCreateHabit() {
  const _auto = _nextAutoColorAndIcon();
  _habitCreateState = { color: _auto.color, iconSvg: _auto.iconSvg, freqMode: 'Everyday', dowSel: [], domSel: [], periodN: 3, periodUnit: 'week' };
  _renderHabitCreatePanel();
}

function _renderHabitCreatePanel() {
  document.getElementById('hCreateWrapper')?.remove();
  const st = _habitCreateState;
  const interns = INTERNS.filter(i => i.id !== 99);
  const colorSwatches = HABIT_COLORS.map(c =>
    `<div class="ct-color-swatch${c===st.color?' sel':''}" style="background:${c};" data-color="${c}" onclick="_hPickColor('${c}')"></div>`
  ).join('');
  const iconGrid = Object.entries(HABIT_ICONS).map(([k,svg]) =>
    `<div class="ct-icon-opt${st.iconSvg===svg?' sel':''}" data-key="${k}" onclick="_hPickIcon('${k}')">${svg.replace('viewBox','width="20" height="20" viewBox')}</div>`
  ).join('');
  const freqOpts = [
    {key:'Everyday',label:'Everyday',sub:null},
    {key:'SpecificDaysOfWeek',label:'Specific Days of Week',sub:'dow'},
    {key:'SpecificDaysOfMonth',label:'Specific Days of Month',sub:'dom'},
    {key:'SomeDaysPerPeriod',label:'Some Days Per Period',sub:'period'},
  ];
  const dowLabels=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const freqHtml = freqOpts.map(opt => {
    const isSel = st.freqMode === opt.key;
    let sub = '';
    if (isSel && opt.sub==='dow')
      sub = `<div class="ct-freq-sub visible"><div class="ct-dow-row">${dowLabels.map((d,i)=>`<div class="ct-dow-pill${st.dowSel.includes(i)?' sel':''}" onclick="_hToggleDow(${i})">${d}</div>`).join('')}</div></div>`;
    else if (isSel && opt.sub==='dom')
      sub = `<div class="ct-freq-sub visible"><div class="ct-dom-grid">${Array.from({length:31},(_,i)=>`<div class="ct-dom-pill${st.domSel.includes(i+1)?' sel':''}" onclick="_hToggleDom(${i+1})">${i+1}</div>`).join('')}</div></div>`;
    else if (isSel && opt.sub==='period')
      sub = `<div class="ct-freq-sub visible"><div class="ct-period-row"><div class="ct-period-num"><button class="ct-period-btn" onclick="_hPeriodAdj(-1)">−</button><span class="ct-period-val" id="hPeriodVal">${st.periodN}</span><button class="ct-period-btn" onclick="_hPeriodAdj(1)">+</button></div><span style="font-size:14px;color:var(--text);">days per</span><select class="ct-period-sel" onchange="_hPeriodUnit(this.value)"><option value="week"${st.periodUnit==='week'?' selected':''}>Week</option><option value="month"${st.periodUnit==='month'?' selected':''}>Month</option></select></div></div>`;
    return `<div class="ct-freq-option" onclick="_hSetFreq('${opt.key}')"><div class="ct-freq-radio${isSel?' sel':''}"></div><span class="ct-freq-option-label">${opt.label}</span></div>${sub}`;
  }).join('');

  const previewSvg = (st.iconSvg||'').replace('viewBox','width="22" height="22" viewBox');

  const html = `
  <div class="ct-overlay" id="hCreateOverlay" onclick=""></div>
  <div class="ct-page" id="hCreatePage">
    <div class="ct-header">
      <button class="ct-back-btn" onclick="closeCreateHabit()">
        <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
      </button>
      <span class="ct-header-title">Add Habit</span>
      <button class="ct-back-btn" style="font-size:14px;font-weight:700;color:var(--accent);gap:4px;display:flex;align-items:center;" onclick="saveHabit()">
        Save<svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;"><polyline points="20 6 9 17 4 12"/></svg>
      </button>
    </div>
    <div class="ct-body">
      <div class="ct-field-wrap">
        <input type="text" id="hName" class="ct-text-input" placeholder="Enter Habit Title">
      </div>
      <div class="ct-field-wrap">
        <div class="ct-desc-row" onclick="openDescEditor('hDesc')">
          <span class="ct-desc-preview" id="hDescPreview">Enter Description (optional)</span>
          <svg class="ct-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
        </div>
        <textarea id="hDesc" style="display:none;"></textarea>
      </div>
      <div class="ct-divider"></div>
      <div class="ct-icon-color-row">
        <div class="ct-ic-item" onclick="_hToggleColorPicker()">
          <div class="ct-ic-preview" id="hColorPreview"><span class="ct-color-dot" id="hColorDot" style="background:${st.color};"></span></div>
          <span class="ct-ic-label">Color</span>
        </div>
        <div class="ct-ic-item" onclick="_hToggleIconPicker()">
          <div class="ct-ic-preview" id="hIconPreview" style="background:${st.color}33;color:${st.color};">${previewSvg}</div>
          <span class="ct-ic-label">Icon</span>
        </div>
      </div>
      <div class="ct-color-strip" id="hColorStrip">${colorSwatches}</div>
      <div class="ct-icon-grid" id="hIconGrid">${iconGrid}</div>
      ${currentRole === 'individual' ? '' : `
      <div class="ct-divider"></div>
      <!-- Assign -->
      <div class="ct-section" style="padding:12px 20px;">
        <div class="ct-section-label" style="font-size:11px;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">
          Assign To <span id="hAssignCount" style="color:var(--accent);font-weight:700;margin-left:6px;">(0 selected)</span>
        </div>
        <input type="text" id="hInternSearch" class="ct-search-input" placeholder="Search interns…" oninput="_hFilterInterns()">
        <div class="intern-picker" id="hAssignList" style="max-height:140px;">
          <div class="pick-all-row"><span style="font-size:11px;color:var(--text2);">Select interns</span><button onclick="_hToggleAll(true)">All</button><button onclick="_hToggleAll(false)">Clear</button></div>
          ${interns.map(i=>`<label data-name="${i.name.toLowerCase()}"><input type="checkbox" class="hInternCb" value="${i.id}" onchange="_hUpdateCount()"> ${sanitize(i.name)}</label>`).join('')}
        </div>
      </div>`}
      <div class="ct-divider"></div>
      <!-- XP -->
      <div class="ct-field-wrap" style="padding:12px 20px;">
        ${_buildXpStepper('hXP', 0)}
      </div>
      <div class="ct-divider"></div>
      <!-- Frequency -->
      <div class="ct-freq-section">
        <div class="ct-freq-label">Frequency</div>
        <div class="ct-freq-options" id="hFreqOptions">${freqHtml}</div>
      </div>
      <div class="ct-divider"></div>
      <!-- Dates -->
      <div class="ct-picker-row" style="position:relative;">
        <span class="ct-picker-label">Start Date</span>
        <div class="ct-picker-right">
          <span id="hStartLbl" style="font-size:14px;color:var(--accent);">${new Date().toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'})}</span>
          <svg class="ct-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
        </div>
        <input type="date" id="hStartDate" class="ct-date-hidden" value="${_hToday()}" oninput="_hDateLbl(this,'hStartLbl')">
      </div>
      <div class="ct-picker-row" style="position:relative;">
        <span class="ct-picker-label">End Date <span style="color:var(--text3);font-size:11px;">(optional)</span></span>
        <div class="ct-picker-right">
          <span id="hEndLbl" style="font-size:14px;color:var(--text2);">No end date</span>
          <svg class="ct-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
        </div>
        <input type="date" id="hEndDate" class="ct-date-hidden" oninput="_hDateLbl(this,'hEndLbl','No end date')">
      </div>
      <div class="ct-divider"></div>
      <!-- Reminder Coming Soon -->
      <div class="ct-picker-row" style="opacity:.55;pointer-events:none;">
        <span class="ct-picker-label">Reminder Time</span>
        <div class="ct-picker-right">
          <span style="font-size:11px;font-weight:700;background:#6366f1;color:#fff;padding:2px 8px;border-radius:20px;">Coming Soon</span>
        </div>
      </div>
      <div style="height:120px;"></div>
    </div>
  </div>`;

  const w = document.createElement('div'); w.id = 'hCreateWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  if (window.lucide) lucide.createIcons();
  requestAnimationFrame(() => {
    document.getElementById('hCreatePage')?.classList.add('open');
    document.getElementById('hCreateOverlay')?.classList.add('visible');
  });
}

function closeCreateHabit() {
  const p=document.getElementById('hCreatePage'), ov=document.getElementById('hCreateOverlay');
  if(p)p.classList.remove('open'); if(ov)ov.classList.remove('visible');
  setTimeout(()=>document.getElementById('hCreateWrapper')?.remove(),320);
}

function _hPickColor(c) {
  _habitCreateState.color = c;
  const dot = document.getElementById('hColorDot');
  if (dot) dot.style.background = c;
  document.getElementById('hIconPreview').style.cssText=`background:${c}33;color:${c};`;
  document.querySelectorAll('#hColorStrip .ct-color-swatch').forEach(el=>el.classList.toggle('sel',el.dataset.color===c));
}
function _hPickIcon(k) {
  if (!HABIT_ICONS?.[k]) return;
  _habitCreateState.iconSvg = HABIT_ICONS[k];
  const prev = document.getElementById('hIconPreview');
  if (prev) prev.innerHTML = HABIT_ICONS[k].replace('viewBox','width="22" height="22" viewBox');
  document.querySelectorAll('#hIconGrid .ct-icon-opt').forEach(el=>el.classList.toggle('sel',el.dataset.key===k));
  document.getElementById('hIconGrid').style.display='none';
}
function _hToggleColorPicker() {
  const s=document.getElementById('hColorStrip'); const vis=s.style.display==='flex';
  s.style.display=vis?'none':'flex';
  document.getElementById('hIconGrid').style.display='none';
  if(!vis) s.querySelector('.ct-color-swatch.sel')?.scrollIntoView({block:'nearest',inline:'center'});
}
function _hToggleIconPicker() {
  const g=document.getElementById('hIconGrid'); const vis=g.style.display==='grid';
  g.style.display=vis?'none':'grid';
  document.getElementById('hColorStrip').style.display='none';
  if(!vis) g.querySelector('.ct-icon-opt.sel')?.scrollIntoView({block:'nearest'});
}
function _hSetFreq(key) {
  _habitCreateState.freqMode = key;
  _renderHabitFreqOpts();
}
function _hToggleDow(i) {
  const s=_habitCreateState.dowSel;
  const idx=s.indexOf(i); if(idx>-1)s.splice(idx,1); else s.push(i);
  _renderHabitFreqOpts();
}
function _hToggleDom(n) {
  const s=_habitCreateState.domSel;
  const idx=s.indexOf(n); if(idx>-1)s.splice(idx,1); else s.push(n);
  _renderHabitFreqOpts();
}
function _hPeriodAdj(d) {
  _habitCreateState.periodN=Math.max(1,Math.min(30,(_habitCreateState.periodN||3)+d));
  _renderHabitFreqOpts();
}
function _hPeriodUnit(v) { _habitCreateState.periodUnit=v; }
function _renderHabitFreqOpts() {
  const container = document.getElementById('hFreqOptions'); if(!container) return;
  const st = _habitCreateState;
  const freqOpts=[{key:'Everyday',label:'Everyday',sub:null},{key:'SpecificDaysOfWeek',label:'Specific Days of Week',sub:'dow'},{key:'SpecificDaysOfMonth',label:'Specific Days of Month',sub:'dom'},{key:'SomeDaysPerPeriod',label:'Some Days Per Period',sub:'period'}];
  const dowLabels=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  container.innerHTML = freqOpts.map(opt=>{
    const isSel=st.freqMode===opt.key;
    let sub='';
    if(isSel&&opt.sub==='dow') sub=`<div class="ct-freq-sub visible"><div class="ct-dow-row">${dowLabels.map((d,i)=>`<div class="ct-dow-pill${st.dowSel.includes(i)?' sel':''}" onclick="_hToggleDow(${i})">${d}</div>`).join('')}</div></div>`;
    else if(isSel&&opt.sub==='dom') sub=`<div class="ct-freq-sub visible"><div class="ct-dom-grid">${Array.from({length:31},(_,i)=>`<div class="ct-dom-pill${st.domSel.includes(i+1)?' sel':''}" onclick="_hToggleDom(${i+1})">${i+1}</div>`).join('')}</div></div>`;
    else if(isSel&&opt.sub==='period') sub=`<div class="ct-freq-sub visible"><div class="ct-period-row"><div class="ct-period-num"><button class="ct-period-btn" onclick="_hPeriodAdj(-1)">−</button><span class="ct-period-val">${st.periodN}</span><button class="ct-period-btn" onclick="_hPeriodAdj(1)">+</button></div><span style="font-size:14px;color:var(--text);">days per</span><select class="ct-period-sel" onchange="_hPeriodUnit(this.value)"><option value="week"${st.periodUnit==='week'?' selected':''}>Week</option><option value="month"${st.periodUnit==='month'?' selected':''}>Month</option></select></div></div>`;
    return `<div class="ct-freq-option" onclick="_hSetFreq('${opt.key}')"><div class="ct-freq-radio${isSel?' sel':''}"></div><span class="ct-freq-option-label">${opt.label}</span></div>${sub}`;
  }).join('');
}
function _hUpdateCount() {
  const n=document.querySelectorAll('.hInternCb:checked').length;
  const el=document.getElementById('hAssignCount'); if(el) el.textContent=`(${n} selected)`;
}
function _hToggleAll(check) {
  document.querySelectorAll('#hAssignList label:not(.pick-all-row)').forEach(lbl=>{
    if(lbl.style.display!=='none') lbl.querySelector('input').checked=check;
  });
  _hUpdateCount();
}
function _hFilterInterns() {
  const q=(document.getElementById('hInternSearch')?.value||'').toLowerCase();
  document.querySelectorAll('#hAssignList label[data-name]').forEach(lbl=>{
    lbl.style.display=lbl.dataset.name.includes(q)?'':'none';
  });
}
function _hDateLbl(input, lblId, emptyText='') {
  const lbl=document.getElementById(lblId); if(!lbl) return;
  if(input.value) { const d=new Date(input.value+'T00:00:00'); lbl.textContent=d.toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'}); lbl.style.color='var(--accent)'; }
  else { lbl.textContent=emptyText||'Not set'; lbl.style.color='var(--text2)'; }
}

async function saveHabit() {
  const name = document.getElementById('hName')?.value.trim();
  if (!name) { showToast('Habit name required', 'error'); return; }
  let selectedIds;
  if (currentRole === 'individual') {
    // No Assign To section is rendered for individual (see
    // _renderHabitCreatePanel()) — this habit is always just for
    // themselves.
    selectedIds = [currentUser.id];
  } else {
    selectedIds = [...document.querySelectorAll('.hInternCb:checked')].map(cb=>_parseInternId(cb.value));
    if (!selectedIds.length) { showToast('Assign to at least one intern', 'error'); return; }
  }
  const xpRaw = parseInt(document.getElementById('hXP')?.value);
  const xp = (isFinite(xpRaw) && xpRaw > 0) ? xpRaw : 5;
  const st = _habitCreateState;

  // Build frequency config
  let frequency = { type: 'everyday', config: {} };
  if (st.freqMode === 'SpecificDaysOfWeek') frequency = { type: 'daysOfWeek', config: { days: [...st.dowSel] } };
  else if (st.freqMode === 'SpecificDaysOfMonth') frequency = { type: 'daysOfMonth', config: { dates: [...st.domSel] } };
  else if (st.freqMode === 'SomeDaysPerPeriod') frequency = { type: 'perPeriod', config: { count: st.periodN, unit: st.periodUnit } };

  const startDate = document.getElementById('hStartDate')?.value || _hToday();
  const endDate = document.getElementById('hEndDate')?.value || null;
  if (endDate && endDate < startDate) { showToast('End date must be after start date', 'error'); return; }

  const habit = {
    id: 'h-' + Date.now(),
    name,
    description: document.getElementById('hDesc')?.value.trim() || '',
    iconSvg: st.iconSvg || null,
    color: st.color || '#F59E0B',
    assignedTo: selectedIds,
    frequency,
    startDate,
    endDate,
    xpPerCompletion: xp,
    createdAt: Date.now(),
    createdBy: 'admin'
  };

  // Duplicate check
  const dupIntern = selectedIds.find(iid => (db.habits||[]).some(h=>h.name===name && h.assignedTo && h.assignedTo.includes(iid)));
  if (dupIntern) {
    const iname = INTERNS.find(i=>i.id===dupIntern)?.name || '';
    showToast(`${iname} already has this habit`, 'error'); return;
  }

  if (!db.habits) db.habits = [];
  db.habits.unshift(habit);
  selectedIds.forEach(iid => pushInternNotif(iid, { type:'habit_assigned', title:'New Habit Assigned', body: name }));
  closeCreateHabit();
  // BUG FIX: Use a targeted write instead of full fbWrite (saveDB) to avoid
  // overwriting habitCompletions that were written independently.
  // THE FIX: this used to fbPatch('habits', db.habits) as a "belt and
  // braces" second write after the safe object-keyed patch above it. But
  // db.habits is a real array, and PATCHing a raw array corrupts it
  // server-side into a numeric-keyed object (see fbPut's comment above —
  // this is a documented, established quirk of Firebase's REST PATCH
  // method, not new). That corrupted 'habits' node is exactly what broke
  // habit completion for every trainee afterward: completeHabit() itself
  // was always correct, but any client that next loaded fresh (a new
  // login, not just the live realtime stream — which does self-normalize)
  // read `db.habits` back as a plain object instead of an array, silently
  // breaking every array method downstream. A single fbPut of the real
  // array is both correct and simpler than the two-step dance this
  // replaces.
  try {
    showLoading('Saving...');
    await fbPut('habits', db.habits);
    hideLoading();
    showToast(`Habit created for ${selectedIds.length} intern(s)!`, 'success');
    if (currentPage) await navigateTo(currentPage);
  } catch(e) {
    hideLoading();
    showToast('Save failed. Check your internet.', 'error');
  }
}

// ── Admin Habit Management (Admin Dashboard card) ─────────────
function openAdminHabits() {
  const habits = db.habits || [];
  const td = _hToday();
  if (!habits.length) {
    openModal(`
      <div class="modal-title">🔥 Habits</div>
      <div class="txp-empty" style="margin:20px 0;">No habits created yet.</div>
      <button class="btn btn-primary btn-full" onclick="closeModal();openCreateHabit()">+ Create First Habit</button>
    `);
    if (window.lucide) lucide.createIcons();
    return;
  }

  const rows = habits.map(h => {
    const assignedNames = (h.assignedTo||[]).map(iid=>INTERNS.find(i=>i.id===iid)?.name?.split(' ')[0]||'?').join(', ');
    const totalAssigned = (h.assignedTo||[]).length;
    const doneToday = (h.assignedTo||[]).filter(iid=>_habitCompleted(h.id,iid,td)).length;
    const color = h.color||'#F59E0B';
    const iconSvg=(h.iconSvg||'').replace(/width="[^"]*"/,'').replace(/height="[^"]*"/,'').replace('<svg','<svg width="20" height="20"');
    return `<div class="admin-habit-row" onclick="openAdminHabitDetail('${h.id}')">
      <div class="admin-habit-icon" style="background:${color}22;color:${color};">${iconSvg}</div>
      <div class="admin-habit-info">
        <div class="admin-habit-name">${sanitize(h.name)}</div>
        <div class="admin-habit-meta">${sanitize(assignedNames.length>30?assignedNames.slice(0,28)+'…':assignedNames)}</div>
      </div>
      <div class="admin-habit-stat" style="color:${color};">${doneToday}/${totalAssigned}</div>
      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--text3)" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
    </div>`;
  }).join('');

  openModal(`
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">
      <div class="modal-title" style="margin:0;">🔥 Habits</div>
      <button class="btn btn-primary btn-sm" onclick="closeModal();openCreateHabit()">+ New</button>
    </div>
    <div class="admin-habit-list">${rows}</div>
  `);
  if (window.lucide) lucide.createIcons();
}

function openAdminHabitDetail(habitId) {
  const habit = (db.habits||[]).find(h=>h.id===habitId);
  if (!habit) return;
  const color = habit.color||'#F59E0B';
  const td = _hToday();
  const internRows = (habit.assignedTo||[]).map(iid => {
    const intern = INTERNS.find(i=>i.id===iid); if(!intern) return '';
    const { current: streak } = _habitCalcStreak(habitId, iid);
    const score = _habitCalcScore(habitId, iid);
    const done = _habitCompleted(habitId, iid, td);
    return `<div class="admin-hi-row" onclick="openHabitDetail('${habitId}','${iid}')">
      <div class="admin-hi-avatar" style="background:${color}22;color:${color};">${intern.name.charAt(0)}</div>
      <div class="admin-hi-info">
        <div class="admin-hi-name">${sanitize(intern.name)}</div>
        <div class="admin-hi-meta">Streak: ${streak}d · Score: ${score}%</div>
      </div>
      <div class="admin-hi-status" style="color:${done?'#22c55e':'var(--text3)'};">${done?'✓ Done':'Pending'}</div>
    </div>`;
  }).join('');

  closeModal();
  openModal(`
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;">
      <div style="width:40px;height:40px;border-radius:10px;background:${color}22;color:${color};display:flex;align-items:center;justify-content:center;flex-shrink:0;">
        ${(habit.iconSvg||'').replace(/width="[^"]*"/,'').replace(/height="[^"]*"/,'').replace('<svg','<svg width="22" height="22"')}
      </div>
      <div>
        <div style="font-size:16px;font-weight:700;">${sanitize(habit.name)}</div>
        <div style="font-size:11px;color:var(--text2);">${_habitFreqLabel(habit.frequency)}</div>
      </div>
    </div>
    ${habit.description?`<div style="font-size:13px;color:var(--text2);margin-bottom:16px;padding:10px;background:var(--surface2);border-radius:8px;" class="rich-desc">${sanitizeRichHtml(habit.description)}</div>`:''}
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--text3);margin-bottom:8px;">Assigned Interns</div>
    <div class="admin-habit-interns">${internRows}</div>
    <div style="margin-top:16px;">
      <button class="btn btn-danger btn-full" onclick="confirmDeleteHabit('${habitId}')">Delete Habit</button>
    </div>
  `);
  if (window.lucide) lucide.createIcons();
}

function confirmDeleteHabit(habitId) {
  const habit = (db.habits||[]).find(h=>h.id===habitId); if(!habit) return;
  closeModal();
  openModal(`
    <div class="modal-title">Delete Habit?</div>
    <div style="font-size:13px;color:var(--text2);margin:12px 0;">Delete "<strong>${sanitize(habit.name)}</strong>"? XP already awarded will be kept. This cannot be undone.</div>
    <div style="display:flex;gap:8px;">
      <button class="btn btn-secondary" style="flex:1;" onclick="closeModal()">Cancel</button>
      <button class="btn btn-danger" style="flex:1;" onclick="doDeleteHabit('${habitId}')">Delete</button>
    </div>
  `);
}

async function doDeleteHabit(habitId) {
  db.habits = (db.habits||[]).filter(h=>h.id!==habitId);
  closeModal();
  await saveAndRefresh('Habit deleted.', 'adminDashboard');
}

function setATF(f) { window.adminTaskFilter = f; }


