function openAtCategorySheet() {
  document.getElementById('atCatSheet')?.remove();
  const current = window.habitCatFilter || 'All';
  const cats = ['Office', 'Academic', 'Personal'];
  const sheet = document.createElement('div');
  sheet.id = 'atCatSheet';
  sheet.innerHTML = `
    <div class="tc-backdrop" onclick="document.getElementById('atCatSheet')?.remove()"></div>
    <div class="tc-sheet" id="atCatSheetInner">
      <div class="tc-handle"></div>
      <div class="at-cat-sheet-header">
        <span class="at-cat-sheet-title">Add to Categories</span>
        <button class="at-cat-new-btn" onclick="alert('Coming soon')">+ New Category</button>
      </div>
      <div class="at-cat-sheet-list">
        ${cats.map(c => `
          <label class="at-cat-sheet-item" onclick="event.stopPropagation()">
            <div class="at-cat-sheet-checkbox${current===c?' at-cat-checked':''}">
              ${current===c?`<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>`:''}
            </div>
            <span class="at-cat-sheet-name">${c}</span>
            <input type="radio" name="atCatRadio" value="${c}" ${current===c?'checked':''} style="display:none;" onchange="_atPickCat('${c}')">
          </label>`).join('')}
      </div>
      <div class="at-cat-sheet-footer">
        <button class="at-cat-done-btn" onclick="_atCatDone()">Done</button>
      </div>
    </div>`;
  document.body.appendChild(sheet);
  requestAnimationFrame(() => sheet.querySelector('#atCatSheetInner').classList.add('tc-sheet-open'));

  // Wire label clicks to radio inputs
  sheet.querySelectorAll('.at-cat-sheet-item').forEach(item => {
    item.addEventListener('click', () => {
      const radio = item.querySelector('input[type=radio]');
      if (radio) { radio.checked = true; _atPickCat(radio.value); }
    });
  });
}
function _atPickCat(v) {
  window.habitCatFilter = v;
  // Update checkboxes visually
  document.querySelectorAll('.at-cat-sheet-item').forEach(item => {
    const radio = item.querySelector('input');
    const box   = item.querySelector('.at-cat-sheet-checkbox');
    if (!box) return;
    const active = radio?.value === v;
    box.className = 'at-cat-sheet-checkbox' + (active ? ' at-cat-checked' : '');
    box.innerHTML = active ? `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>` : '';
  });
}
function _atCatDone() {
  document.getElementById('atCatSheet')?.remove();
  renderAdminTasks(document.getElementById('contentArea'));
}
function atSetCat(v)    { window.habitCatFilter    = v; renderAdminTasks(document.getElementById('contentArea')); }

// Admin task calendar — reuses intern calendar sheet, refreshes admin page
function openAdminTaskCalendar() {
  const todayStr = _habitToday();
  const now = new Date(todayStr + 'T00:00:00');
  _calViewYear  = now.getFullYear();
  _calViewMonth = now.getMonth();
  _calSelStart  = null;
  _calSelEnd    = null;
  _renderAdminTaskCalendar();
}
function _renderAdminTaskCalendar() {
  document.getElementById('taskCalSheet')?.remove();
  const todayStr    = _habitToday();
  const y = _calViewYear, m = _calViewMonth;
  const monthName   = new Date(y, m, 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const firstDow    = new Date(y, m, 1).getDay();
  const daysInMonth = new Date(y, m + 1, 0).getDate();
  let cells = '';
  for (let i = 0; i < firstDow; i++) cells += `<div class="tc-cell tc-empty"></div>`;
  for (let d = 1; d <= daysInMonth; d++) {
    const ds = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday = ds === todayStr;
    const isStart = _calSelStart && ds === _calSelStart;
    const isEnd   = _calSelEnd   && ds === _calSelEnd;
    const inRange = _calSelStart && _calSelEnd && ds > _calSelStart && ds < _calSelEnd;
    let cls = 'tc-cell';
    if (isToday) cls += ' tc-today';
    if (isStart && !isEnd) cls += ' tc-sel-start';
    if (isEnd && !isStart) cls += ' tc-sel-end';
    if (isStart && isEnd)  cls += ' tc-sel-start tc-sel-single';
    if (inRange) cls += ' tc-in-range';
    cells += `<div class="${cls}" onclick="_atCalTapDay('${ds}')">${d}</div>`;
  }
  let hint = !_calSelStart ? 'Tap a date to select start'
    : !_calSelEnd ? `<span style="color:var(--accent);font-weight:700;">${_habitFmtHeaderDate(_calSelStart)}</span> &nbsp;→&nbsp; Tap end date`
    : `<span style="color:var(--accent);font-weight:700;">${_habitFmtHeaderDate(_calSelStart)}</span> &nbsp;—&nbsp; <span style="color:var(--accent);font-weight:700;">${_habitFmtHeaderDate(_calSelEnd)}</span>`;
  const sheet = document.createElement('div');
  sheet.id = 'taskCalSheet';
  sheet.innerHTML = `
    <div class="tc-backdrop" onclick="_atCloseCalendar()"></div>
    <div class="tc-sheet" id="tcSheetInner">
      <div class="tc-handle"></div>
      <div class="tc-header">
        <button class="tc-nav-btn" onclick="_atCalPrev()"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg></button>
        <span class="tc-month-label">${monthName}</span>
        <button class="tc-nav-btn" onclick="_atCalNext()"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg></button>
      </div>
      <div class="tc-dow-row">${['Su','Mo','Tu','We','Th','Fr','Sa'].map(d=>`<div class="tc-dow">${d}</div>`).join('')}</div>
      <div class="tc-grid">${cells}</div>
      <div class="tc-hint">${hint}</div>
      <div class="tc-actions">
        <button class="tc-btn-clear" onclick="_atCalClear()">Clear</button>
        <button class="tc-btn-apply" onclick="_atCalApply()">Apply</button>
      </div>
    </div>`;
  document.body.appendChild(sheet);
  requestAnimationFrame(() => sheet.querySelector('#tcSheetInner').classList.add('tc-sheet-open'));
}
function _atCalTapDay(ds) {
  if (!_calSelStart || (_calSelStart && _calSelEnd)) { _calSelStart = ds; _calSelEnd = null; }
  else if (ds < _calSelStart) { _calSelEnd = _calSelStart; _calSelStart = ds; }
  else if (ds === _calSelStart) { _calSelEnd = null; }
  else { _calSelEnd = ds; }
  _renderAdminTaskCalendar();
}
function _atCalPrev() { _calViewMonth--; if (_calViewMonth < 0) { _calViewMonth = 11; _calViewYear--; } _renderAdminTaskCalendar(); }
function _atCalNext() { _calViewMonth++; if (_calViewMonth > 11) { _calViewMonth = 0; _calViewYear++; } _renderAdminTaskCalendar(); }
function _atCalClear() {
  _calSelStart = null; _calSelEnd = null;
  window.habitRangeStart = null; window.habitRangeEnd = null;
  window.habitSelectedDate = _habitToday();
  document.getElementById('taskCalSheet')?.remove();
  renderAdminTasks(document.getElementById('contentArea'));
}
