// Human-readable label for a repeat config object
function repeatLabel(r) {
  if (!r) return 'None';
  const dn = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  if (r.freq === 'Days'     && r.interval === 1) return 'Daily';
  if (r.freq === 'Days')                         return `Every ${r.interval} Days`;
  if (r.freq === 'Weekdays')                     return 'Every Weekday (Mon–Fri)';
  if (r.freq === 'Weeks') {
    const dayStr = r.days?.length
      ? ' (' + r.days.slice().sort((a,b)=>a-b).map(d=>dn[d]).join(', ') + ')'
      : '';
    return r.interval === 1 ? `Every Week${dayStr}` : `Every ${r.interval} Weeks${dayStr}`;
  }
  if (r.freq === 'Months')  return r.interval === 1 ? 'Monthly'   : `Every ${r.interval} Months`;
  if (r.freq === 'Years')   return r.interval === 1 ? 'Yearly'    : `Every ${r.interval} Years`;
  return `Every ${r.interval} ${r.freq}`;
}

// Auto-refresh timer: re-runs processRepeatTasks every 5 min while logged in.
// Catches the midnight rollover when a user stays logged in all day.
let _repeatCheckTimer = null;
function startRepeatTimer() {
  if (_repeatCheckTimer) clearInterval(_repeatCheckTimer);
  _repeatCheckTimer = setInterval(async () => {
    if (!currentUser || !db) return;
    const changed = processRepeatTasks();
    if (changed) {
      try {
        await saveDB();
        updateBadges();
        if (currentPage) navigateTo(currentPage);
        showStatus('✓ New recurring tasks generated');
      } catch(e) { /* silent — will catch on next sync */ }
    }
  }, 5 * 60 * 1000); // every 5 minutes
}

// ── Repeat Dialog ──
function openRepeatDlg(ctx) {
  document.getElementById('subDialogOverlay')?.remove();
  const cur = _repeatConfig || {freq:'Days', interval:1, days:[]};
  const dn  = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  // Detect which quick preset matches the current config
  function detectPreset(r) {
    if (!r) return 'daily';
    if (r.freq === 'Days'     && r.interval === 1)  return 'daily';
    if (r.freq === 'Weekdays')                       return 'weekdays';
    if (r.freq === 'Weeks'    && r.interval === 1)   return 'weekly';
    if (r.freq === 'Months'   && r.interval === 1)   return 'monthly';
    return 'custom';
  }
  const initPreset = detectPreset(cur);
  const showDays   = (initPreset === 'weekly') || (initPreset === 'custom' && cur.freq === 'Weeks');
  const showCustom = initPreset === 'custom';

  const ov = document.createElement('div');
  ov.id = 'subDialogOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);backdrop-filter:blur(2px);z-index:2000;display:flex;align-items:center;justify-content:center;';
  ov._rs = {freq: cur.freq||'Days', interval: cur.interval||1, days:[...(cur.days||[])], preset: initPreset};

  const pillStyle  = (active) => `padding:6px 14px;border-radius:20px;border:1.5px solid ${active?'#e85d26':'var(--border)'};background:${active?'#e85d26':'var(--surface2)'};color:${active?'#fff':'var(--text2)'};font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;transition:all .15s;`;
  const presets = [{k:'daily','label':'⚡ Daily'},{k:'weekdays',label:'📅 Weekdays'},{k:'weekly',label:'🗓 Weekly'},{k:'monthly',label:'📆 Monthly'},{k:'custom',label:'⚙ Custom'}];

  ov.innerHTML = `
    <div style="background:var(--card-bg);border:1px solid var(--border);border-radius:14px;padding:24px;width:370px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.35);">
      <div style="font-size:15px;font-weight:700;color:var(--text);margin-bottom:4px;">🔁 Repeat Schedule</div>
      <div style="font-size:12px;color:var(--text2);margin-bottom:4px;">A NEW copy of this task is auto-created each day on the chosen schedule.</div>
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;padding:6px 10px;font-size:11px;color:#e85d26;margin-bottom:14px;">⚡ <strong>Daily</strong> = a fresh task appears every day for the intern — they complete it each day.</div>

      <!-- Quick Preset Pills -->
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px;">
        ${presets.map(p=>`<button id="rp-${p.k}" onclick="selectRepPreset('${p.k}')" style="${pillStyle(initPreset===p.k)}">${p.label}</button>`).join('')}
      </div>

      <!-- Custom Controls (visible only in Custom mode) -->
      <div id="repCustomSection" style="display:${showCustom?'flex':'none'};align-items:center;gap:10px;margin-bottom:12px;">
        <div style="background:var(--surface2);border-radius:8px;display:flex;align-items:center;border:1px solid var(--border);flex-shrink:0;">
          <button onclick="chRI(-1)" style="background:none;border:none;color:var(--text);padding:7px 12px;cursor:pointer;font-size:15px;">−</button>
          <span id="riVal" style="color:var(--text);font-weight:700;min-width:26px;text-align:center;">${cur.interval||1}</span>
          <button onclick="chRI(1)"  style="background:none;border:none;color:var(--text);padding:7px 12px;cursor:pointer;font-size:15px;">+</button>
        </div>
        <select id="rfSel" onchange="updateRFUI()" style="background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:8px 11px;font-size:14px;font-family:inherit;flex:1;outline:none;">
          ${['Days','Weekdays','Weeks','Months','Years'].map(f=>`<option value="${f}" ${(cur.freq||'Days')===f?'selected':''}>${f}</option>`).join('')}
        </select>
      </div>

      <!-- Day-of-Week Picker (Weekly preset or Weeks in Custom) -->
      <div id="rDaysRow" style="display:${showDays?'flex':'none'};gap:5px;flex-wrap:wrap;margin-bottom:14px;">
        ${dn.map((d,i)=>`<button id="rd-${i}" onclick="togRD(${i})" style="width:40px;height:40px;border-radius:50%;border:none;cursor:pointer;font-size:11px;font-weight:700;background:${cur.days?.includes(i)?'#e85d26':'var(--surface2)'};color:${cur.days?.includes(i)?'#fff':'var(--text2)'};transition:all .15s;">${d}</button>`).join('')}
      </div>

      <!-- Live Preview -->
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:9px 13px;font-size:12px;color:var(--text2);margin-bottom:18px;">
        Task repeats: <strong id="repPreviewLabel" style="color:#e85d26;">${repeatLabel(ov._rs)}</strong>
      </div>

      <div style="display:flex;gap:7px;justify-content:flex-end;">
        <button onclick="cancelRep()" style="background:none;border:1px solid var(--border);color:var(--text2);border-radius:8px;padding:7px 14px;cursor:pointer;font-family:inherit;">Cancel</button>
        <button onclick="clearRep('${ctx}')" style="background:none;border:1px solid #e53e3e;color:#e53e3e;border-radius:8px;padding:7px 14px;cursor:pointer;font-family:inherit;">Remove</button>
        <button onclick="confirmRep('${ctx}')" style="background:#e85d26;color:#fff;border:none;border-radius:8px;padding:7px 14px;cursor:pointer;font-family:inherit;font-weight:600;">✓ Done</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
}

// Select a quick preset pill
function selectRepPreset(p) {
  const ov = document.getElementById('subDialogOverlay'); if (!ov) return;
  ov._rs.preset = p;
  // Update pill styles
  ['daily','weekdays','weekly','monthly','custom'].forEach(k => {
    const btn = document.getElementById('rp-'+k); if (!btn) return;
    const active = k === p;
    btn.style.background   = active ? '#e85d26' : 'var(--surface2)';
    btn.style.borderColor  = active ? '#e85d26' : 'var(--border)';
    btn.style.color        = active ? '#fff'    : 'var(--text2)';
  });
  // Apply preset config
  const map = {daily:{freq:'Days',interval:1}, weekdays:{freq:'Weekdays',interval:1},
               weekly:{freq:'Weeks',interval:1}, monthly:{freq:'Months',interval:1}};
  if (map[p]) { ov._rs.freq = map[p].freq; ov._rs.interval = map[p].interval; }
  // Show/hide custom controls
  const cs = document.getElementById('repCustomSection');
  if (cs) cs.style.display = p==='custom' ? 'flex' : 'none';
  // Sync the custom select with current freq
  const rfSel = document.getElementById('rfSel'); if (rfSel) rfSel.value = ov._rs.freq;
  const riVal = document.getElementById('riVal'); if (riVal) riVal.textContent = ov._rs.interval;
  // Show/hide day picker
  const showDays = p==='weekly' || (p==='custom' && ov._rs.freq==='Weeks');
  const dr = document.getElementById('rDaysRow'); if (dr) dr.style.display = showDays?'flex':'none';
  updateRepPreview();
}

// Update the live "Task repeats: X" preview line
function updateRepPreview() {
  const ov  = document.getElementById('subDialogOverlay'); if (!ov) return;
  const lbl = document.getElementById('repPreviewLabel'); if (!lbl) return;
  lbl.textContent = repeatLabel(ov._rs);
}

function chRI(d) {
  const ov = document.getElementById('subDialogOverlay');
  const el = document.getElementById('riVal');
  let v = parseInt(el.textContent) + d;
  if (v < 1) v = 1; if (v > 365) v = 365;
  el.textContent = v; ov._rs.interval = v; updateRepPreview();
}

function updateRFUI() {
  const freq = document.getElementById('rfSel').value;
  const ov = document.getElementById('subDialogOverlay');
  if (ov) ov._rs.freq = freq;
  const dr = document.getElementById('rDaysRow');
  if (dr) dr.style.display = freq==='Weeks' ? 'flex' : 'none';
  updateRepPreview();
}

function togRD(i) {
  const ov  = document.getElementById('subDialogOverlay');
  const st  = ov._rs;
  const btn = document.getElementById('rd-'+i);
  if (st.days.includes(i)) {
    st.days = st.days.filter(d=>d!==i);
    btn.style.background='var(--surface2)'; btn.style.color='var(--text2)';
  } else {
    st.days.push(i);
    btn.style.background='#e85d26'; btn.style.color='#fff';
  }
  updateRepPreview();
}

function cancelRep() { document.getElementById('subDialogOverlay')?.remove(); }

function clearRep(ctx) {
  _repeatConfig = null;
  document.getElementById('subDialogOverlay')?.remove();
  const lel = document.getElementById(ctx==='t' ? 'tRepLabel' : 'ptRepLabel');
  if (lel) lel.textContent = 'None';
}

function confirmRep(ctx) {
  const ov = document.getElementById('subDialogOverlay');
  const st = ov._rs;
  // Weekly preset requires at least one day selected
  if ((st.preset==='weekly' || st.freq==='Weeks') && st.days.length===0) {
    document.getElementById('repPreviewLabel').textContent = '⚠ Select at least one day';
    document.getElementById('repPreviewLabel').style.color = '#e53e3e'; return;
  }
  _repeatConfig = {freq:st.freq, interval:st.interval, days:[...st.days]};
  ov.remove();
  const lel = document.getElementById(ctx==='t' ? 'tRepLabel' : 'ptRepLabel');
  if (lel) lel.textContent = repeatLabel(_repeatConfig);
}

