async function toggleToolkitFeature(key, enabled) {
  if (!db.toolkit) db.toolkit = { statusBreakdown: true };
  db.toolkit[key] = enabled;
  try {
    await fbPut('toolkit', db.toolkit);
    showToast(enabled ? '✅ Feature enabled' : '🔕 Feature disabled');
    // Re-render dashboard if currently on it
    const ca = document.getElementById('contentArea');
    if (currentPage === 'adminDashboard') renderAdminDashboard(ca);
    if (currentPage === 'internDashboard') renderInternDashboard(ca);
  } catch(e) {
    showToast('❌ Failed to save — check connection');
    db.toolkit[key] = !enabled; // revert
  }
}

