window.fcHandleImage = function(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      const maxW = 800, maxH = 500;
      let w = img.width, h = img.height;
      if (w > maxW) { h = Math.round(h * maxW / w); w = maxW; }
      if (h > maxH) { w = Math.round(w * maxH / h); h = maxH; }
      canvas.width = w; canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      window._fcImageBase64 = canvas.toDataURL('image/jpeg', 0.75);
      const el = document.getElementById('fcImgEl');
      const prev = document.getElementById('fcImgPreview');
      if (el) { el.src = window._fcImageBase64; }
      if (prev) { prev.style.display = 'block'; }
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
};

window.fcClearImage = function() {
  window._fcImageBase64 = null;
  const prev = document.getElementById('fcImgPreview');
  if (prev) prev.style.display = 'none';
};

window.fcToggleBtn = function() {
  window._fcBtnOn = !window._fcBtnOn;
  const tog = document.getElementById('fcBtnToggle');
  const knob = document.getElementById('fcBtnKnob');
  const fields = document.getElementById('fcBtnFields');
  if (tog) tog.style.background = window._fcBtnOn ? '#4834d4' : '#d1d5db';
  if (knob) knob.style.left = window._fcBtnOn ? '22px' : '2px';
  if (fields) fields.style.display = window._fcBtnOn ? 'flex' : 'none';
};

window.fcSave = async function(status) {
  const desc = document.getElementById('fcDesc')?.value.trim();
  if (!desc) { showToast('Please add a description', 'error'); return; }
  const tag      = (document.getElementById('fcTagInput')?.value.trim()) || 'General';
  const btnLabel = window._fcBtnOn ? (document.getElementById('fcBtnLabel')?.value.trim() || '') : '';
  const btnUrl   = window._fcBtnOn ? (document.getElementById('fcBtnUrl')?.value.trim() || '') : '';

  if (!db.feedPosts) db.feedPosts = [];
  const editIdx = window._fcEditIdx;
  // Only re-upload when the image actually changed — window._fcImageBase64
  // is seeded from the existing post's URL when editing (see the modal's
  // open logic), so if the user didn't pick a new photo this is already a
  // Drive URL, not fresh base64, and re-uploading it would be pointless.
  let fcImageUrl = window._fcImageBase64 || null;
  if (fcImageUrl && fcImageUrl.startsWith('data:')) {
    try { fcImageUrl = await uploadImageToDrive(fcImageUrl, 'feedpost_' + Date.now() + '.jpg', 'feed'); }
    catch (err) { console.error('Drive upload failed for feed post image, keeping inline:', err); }
  }
  const post = {
    type: 'post',
    tag,
    description: desc,
    imageBase64: fcImageUrl,
    btnLabel,
    btnUrl,
    status,
    createdAt: (editIdx !== null && editIdx !== undefined) ? db.feedPosts[editIdx].createdAt : Date.now(),
    updatedAt: Date.now(),
    authorId: currentUser.id,
    authorName: currentUser.name,
  };

  const isNew = editIdx === null || editIdx === undefined;
  if (!isNew) {
    db.feedPosts[editIdx] = post;
  } else {
    db.feedPosts.push(post);
  }

  try {
    await fbPut('feedPosts', db.feedPosts);
    showToast(status === 'published' ? '✓ Post published' : '✓ Draft saved', 'success');
    if (isNew && status === 'published') {
      pushInternNotifBroadcast('all', { type:'post_created', title:'New Post', body: desc });
    }
    renderAdminFeed(document.getElementById('contentArea'));
  } catch(e) { showToast('Save failed', 'error'); }
};

// ── Admin: Poll create/edit page ─────────────────────────────────────────
function renderAdminPollCreate(ca, editIdx) {
  const isEdit = editIdx !== undefined && editIdx !== null;
  const posts = getFeedPosts();
  const post = isEdit ? posts[editIdx] : null;
  window._fpEditIdx = isEdit ? editIdx : null;
  window._fpOptions = post?.pollOptions ? post.pollOptions.map(o => o.label) : ['', ''];

  ca.innerHTML = `
  <div class="arw-page" style="font-family:'DM Sans','Outfit',sans-serif;">
    <div class="arw-header">
      <button class="arw-back-btn" onclick="renderAdminFeed(document.getElementById('contentArea'))">
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
      </button>
      <div class="arw-header-title">${isEdit ? 'Edit Poll' : 'Create Poll'}</div>
      <div style="width:36px;"></div>
    </div>

    <div style="padding:12px 16px 100px;display:flex;flex-direction:column;gap:12px;">

      <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px;">
        <div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:10px;">Poll Question</div>
        <textarea id="fpQuestion" rows="2"
          style="width:100%;background:var(--surface2);border:1.5px solid var(--border);border-radius:10px;padding:10px 14px;color:var(--text);font-family:inherit;font-size:13px;resize:none;outline:none;box-sizing:border-box;line-height:1.5;"
          placeholder="e.g. Which workshop should we organize next?">${sanitize(post?.pollQuestion || '')}</textarea>
      </div>

      <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px;">
        <div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:10px;">Options</div>
        <div id="fpOptionsList" style="display:flex;flex-direction:column;gap:8px;"></div>
        <button type="button" onclick="fpAddOption()" style="margin-top:10px;background:none;border:1.5px dashed var(--border);border-radius:10px;padding:9px;width:100%;color:var(--text2);font-size:12.5px;font-weight:600;cursor:pointer;">+ Add option</button>
      </div>

      <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px;">
        <div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:10px;">Closing Date (optional)</div>
        <input id="fpCloseDate" type="date" value="${post?.pollCloseDate || ''}"
          style="width:100%;background:var(--surface2);border:1.5px solid var(--border);border-radius:10px;padding:10px 14px;color:var(--text);font-family:inherit;font-size:13px;outline:none;box-sizing:border-box;">
      </div>

      <div style="display:flex;gap:10px;margin-top:6px;">
        <button onclick="fpSave('draft')" style="flex:1;padding:14px;border-radius:14px;border:1.5px solid var(--border);background:var(--surface);color:var(--text);font-size:13.5px;font-weight:700;cursor:pointer;">Save Draft</button>
        <button onclick="fpSave('published')" style="flex:1;padding:14px;border-radius:14px;border:none;background:#4834d4;color:#fff;font-size:13.5px;font-weight:700;cursor:pointer;">Publish</button>
      </div>
    </div>
  </div>`;
  fpRenderOptions();
}
function fpRenderOptions() {
  const box = document.getElementById('fpOptionsList'); if (!box) return;
  box.innerHTML = window._fpOptions.map((val, i) => `
    <div style="display:flex;gap:8px;align-items:center;">
      <input type="text" value="${sanitize(val)}" placeholder="Option ${i+1}" oninput="window._fpOptions[${i}]=this.value"
        style="flex:1;background:var(--surface2);border:1.5px solid var(--border);border-radius:10px;padding:9px 12px;color:var(--text);font-family:inherit;font-size:13px;outline:none;box-sizing:border-box;">
      ${window._fpOptions.length > 2 ? `<button type="button" onclick="fpRemoveOption(${i})" style="background:none;border:none;color:#dc2626;cursor:pointer;padding:4px;flex-shrink:0;"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>` : ''}
    </div>`).join('');
}
function fpAddOption() {
  if (window._fpOptions.length >= 6) { showToast('Maximum 6 options', 'error'); return; }
  window._fpOptions.push('');
  fpRenderOptions();
}
function fpRemoveOption(i) {
  window._fpOptions.splice(i, 1);
  fpRenderOptions();
}
window.fpSave = async function(status) {
  const question = document.getElementById('fpQuestion')?.value.trim();
  if (!question) { showToast('Please add a poll question', 'error'); return; }
  const labels = window._fpOptions.map(o => (o || '').trim()).filter(Boolean);
  if (labels.length < 2) { showToast('Add at least 2 options', 'error'); return; }
  const closeDate = document.getElementById('fpCloseDate')?.value || '';

  if (!db.feedPosts) db.feedPosts = [];
  const editIdx = window._fpEditIdx;
  const existingVotes = (editIdx !== null && editIdx !== undefined) ? (db.feedPosts[editIdx].votes || {}) : {};
  const post = {
    type: 'poll',
    pollQuestion: question,
    pollOptions: labels.map((label, i) => ({ id: 'opt' + i, label })),
    pollCloseDate: closeDate,
    votes: existingVotes, // { internId: optionId } — preserved across edits
    status,
    createdAt: (editIdx !== null && editIdx !== undefined) ? db.feedPosts[editIdx].createdAt : Date.now(),
    updatedAt: Date.now(),
    authorId: currentUser.id,
    authorName: currentUser.name,
  };

  const isNew = editIdx === null || editIdx === undefined;
  if (!isNew) db.feedPosts[editIdx] = post;
  else db.feedPosts.push(post);

  try {
    await fbPut('feedPosts', db.feedPosts);
    showToast(status === 'published' ? '✓ Poll published' : '✓ Draft saved', 'success');
    if (isNew && status === 'published') {
      pushInternNotifBroadcast('all', { type:'post_created', title:'New Post', body: 'Poll: ' + question });
    }
    renderAdminFeed(document.getElementById('contentArea'));
  } catch(e) { showToast('Save failed', 'error'); }
};
// Intern casts (or changes) their vote — single choice for this version.
window.voteFeedPoll = async function(arrIdx, optionId) {
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post || post.type !== 'poll') return;
  if (!post.votes) post.votes = {};
  post.votes[currentUser.id] = optionId;
  try {
    await fbPut('feedPosts', posts);
    renderInternFeed(document.getElementById('contentArea'));
  } catch(e) { showToast('Vote failed — try again', 'error'); }
};
// Shared poll-results renderer — used by both the intern feed (after
// voting) and the admin analytics view, so the math only lives in one place.
function _fpResultsHtml(post, highlightOptionId) {
  const votes = post.votes || {};
  const counts = {}; post.pollOptions.forEach(o => counts[o.id] = 0);
  Object.values(votes).forEach(optId => { if (counts[optId] !== undefined) counts[optId]++; });
  const total = Object.values(counts).reduce((a,b) => a+b, 0);
  return post.pollOptions.map(o => {
    const n = counts[o.id] || 0;
    const pct = total ? Math.round(n/total*100) : 0;
    const isMine = highlightOptionId === o.id;
    return `
      <div style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;font-size:12.5px;font-weight:${isMine?'800':'600'};color:${isMine?'#4834d4':'var(--text)'};margin-bottom:5px;">
          <span>${sanitize(o.label)}${isMine?' ✓':''}</span><span>${pct}% (${n})</span>
        </div>
        <div style="height:8px;border-radius:4px;background:var(--surface2);overflow:hidden;">
          <div style="height:100%;width:${pct}%;border-radius:4px;background:${isMine?'#4834d4':'#a5a0f0'};"></div>
        </div>
      </div>`;
  }).join('') + `<div style="font-size:11.5px;color:var(--text3);margin-top:6px;">${total} vote${total!==1?'s':''} total</div>`;
}

// ══════════════════════════════════════════════════════════════════════
// Feed Comments — add/edit/delete/reply/like (any role), pin/delete-any
// (admin only), per the Feed PRD's comment permissions matrix.
// ══════════════════════════════════════════════════════════════════════
window._fcExpanded = window._fcExpanded || []; // arrIdx values with an open comment section, survives re-renders
window._fcEditingComment = null;

function fcToggleComments(arrIdx) {
  const wrap = document.getElementById('fcCommentsWrap-' + arrIdx);
  if (!wrap) return;
  const open = wrap.style.display !== 'none';
  wrap.style.display = open ? 'none' : 'block';
  const i = window._fcExpanded.indexOf(arrIdx);
  if (open && i > -1) window._fcExpanded.splice(i, 1);
  else if (!open && i === -1) window._fcExpanded.push(arrIdx);
}

// Highlights @mentions of real roster names in blue — longest names
// matched first so "Ali" doesn't shadow "Ali Jee".
function _fcRenderCommentText(text) {
  let html = sanitize(text || '');
  const names = INTERNS.map(i => i.name).sort((a,b) => b.length - a.length);
  names.forEach(name => {
    const esc = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    html = html.replace(new RegExp('@' + esc + '\\b', 'g'), `<span style="color:#4834d4;font-weight:700;">@${name}</span>`);
  });
  return html;
}

function _fcCommentRow(c, arrIdx, isReply) {
  const liked = (c.likes || []).includes(currentUser.id);
  const isMine = c.userId === currentUser.id;
  const canDelete = isMine || currentRole === 'admin';
  const canPin = currentRole === 'admin' && !isReply;
  const avatarImg = buildAvatarImg(getAvatarConfig(c.userId), 28);
  const isEditing = window._fcEditingComment === c.id;
  return `<div style="display:flex;gap:8px;margin-top:${isReply?'8px':'12px'};">
    <span style="width:28px;height:28px;border-radius:50%;overflow:hidden;flex-shrink:0;background:var(--surface2);">${avatarImg}</span>
    <div style="flex:1;min-width:0;">
      <div style="background:var(--surface2);border-radius:12px;padding:8px 12px;">
        <div style="font-size:12.5px;font-weight:700;color:var(--text);font-family:'Inter',sans-serif;">${sanitize(c.userName||'')}${c.pinned ? ' <span style="color:#4834d4;">📌 Pinned</span>' : ''}</div>
        ${isEditing ? `
          <textarea id="fcEditInput-${c.id}" rows="2" style="width:100%;margin-top:5px;font-size:13px;border:1px solid var(--border);border-radius:8px;padding:6px 8px;font-family:inherit;resize:none;outline:none;box-sizing:border-box;background:var(--surface);color:var(--text);">${sanitize(c.text)}</textarea>
          <div style="display:flex;gap:12px;margin-top:6px;">
            <button onclick="fcSaveCommentEdit(${arrIdx},'${c.id}')" style="font-size:11.5px;font-weight:700;color:#4834d4;background:none;border:none;cursor:pointer;padding:0;">Save</button>
            <button onclick="fcCancelCommentEdit(${arrIdx})" style="font-size:11.5px;color:var(--text2);background:none;border:none;cursor:pointer;padding:0;">Cancel</button>
          </div>` :
          `<div style="font-size:13px;color:var(--text);margin-top:2px;line-height:1.4;font-family:'Inter',sans-serif;">${_fcRenderCommentText(c.text)}</div>
          ${c.imageBase64 ? `<img src="${c.imageBase64}" style="max-width:100%;max-height:200px;border-radius:10px;margin-top:8px;display:block;object-fit:cover;">` : ''}`
        }
      </div>
      ${!isEditing ? `
      <div style="display:flex;gap:14px;margin-top:5px;padding-left:4px;flex-wrap:wrap;">
        <span style="font-size:11px;color:var(--text3);">${feedTimeAgo(c.createdAt)}</span>
        <button onclick="fcLikeComment(${arrIdx},'${c.id}')" style="font-size:11px;font-weight:700;color:${liked?'#dc2626':'var(--text2)'};background:none;border:none;cursor:pointer;padding:0;">Like${(c.likes||[]).length ? ' (' + c.likes.length + ')' : ''}</button>
        ${!isReply ? `<button onclick="fcShowReplyBox('${c.id}')" style="font-size:11px;font-weight:700;color:var(--text2);background:none;border:none;cursor:pointer;padding:0;">Reply</button>` : ''}
        ${isMine ? `<button onclick="fcStartCommentEdit(${arrIdx},'${c.id}')" style="font-size:11px;color:var(--text2);background:none;border:none;cursor:pointer;padding:0;">Edit</button>` : ''}
        ${canDelete ? `<button onclick="fcDeleteComment(${arrIdx},'${c.id}')" style="font-size:11px;color:#dc2626;background:none;border:none;cursor:pointer;padding:0;">Delete</button>` : ''}
        ${canPin ? `<button onclick="fcPinComment(${arrIdx},'${c.id}')" style="font-size:11px;color:var(--text2);background:none;border:none;cursor:pointer;padding:0;">${c.pinned ? 'Unpin' : 'Pin'}</button>` : ''}
      </div>
      <div id="fcReplyBox-${c.id}" style="display:none;margin-top:8px;">
        <div style="display:flex;gap:6px;">
          <input type="text" id="fcReplyInput-${c.id}" placeholder="Write a reply…" style="flex:1;font-size:13px;border:1px solid var(--border);border-radius:20px;padding:7px 12px;font-family:inherit;outline:none;background:var(--surface);color:var(--text);box-sizing:border-box;">
          <button onclick="fcSubmitComment(${arrIdx},'${c.id}')" style="font-size:12px;font-weight:700;color:#4834d4;background:none;border:none;cursor:pointer;flex-shrink:0;">Post</button>
        </div>
      </div>` : ''}
    </div>
  </div>`;
}

function _fcCommentsSectionHtml(post, arrIdx) {
  const all = post.comments || [];
  const topLevel = all.filter(c => !c.parentId).sort((a,b) => (b.pinned?1:0)-(a.pinned?1:0) || a.createdAt-b.createdAt);
  const repliesOf = id => all.filter(c => c.parentId === id).sort((a,b) => a.createdAt-b.createdAt);
  // Replies sit inside their own left-bordered thread container — the
  // border creates the vertical connecting line down from the parent.
  const rows = topLevel.map(c => {
    const replies = repliesOf(c.id);
    const repliesHtml = replies.length
      ? `<div style="margin-left:14px;padding-left:20px;border-left:2px solid var(--border);">${replies.map(r => _fcCommentRow(r, arrIdx, true)).join('')}</div>`
      : '';
    return _fcCommentRow(c, arrIdx, false) + repliesHtml;
  }).join('');
  return rows || `<div style="font-size:12.5px;color:var(--text3);padding:4px 0;font-family:'Inter',sans-serif;">No comments yet — be the first.</div>`;
}

// ══════════════════════════════════════════════════════════════════════
// Comments now open in a dedicated dialog (matching the "All activity"
// style) instead of expanding inline in the card — with an empty state,
// @mention autocomplete, and photo attachment in the composer.
// ══════════════════════════════════════════════════════════════════════
function openFeedCommentsModal(arrIdx) {
  window._fcModalArrIdx = arrIdx;
  window._fcModalImageBase64 = null;
  const html = `
  <div class="fc-modal-overlay" id="fcModalOverlay" onclick="closeFeedCommentsModal()"></div>
  <div class="fc-modal-sheet" id="fcModalSheet">
    <div class="fc-modal-header">
      <button type="button" onclick="closeFeedCommentsModal()" class="fc-modal-back">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
      </button>
      <span class="fc-modal-title">Comments</span>
      <span style="width:36px;"></span>
    </div>
    <div class="fc-modal-body" id="fcModalBody"></div>
    <div class="fc-modal-composer">
      <div id="fcModalImgPreviewWrap" style="display:none;padding:0 0 8px;">
        <div style="position:relative;display:inline-block;">
          <img id="fcModalImgPreview" src="" style="max-height:90px;border-radius:10px;display:block;">
          <button type="button" onclick="fcModalClearImage()" style="position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;background:rgba(0,0,0,.6);border:none;color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;">✕</button>
        </div>
      </div>
      <div style="display:flex;gap:8px;align-items:flex-end;position:relative;">
        <span class="fc-modal-avatar">${buildAvatarImg(getAvatarConfig(currentUser.id), 32)}</span>
        <div style="flex:1;position:relative;">
          <input type="text" id="fcModalInput" placeholder="Add a comment…" oninput="fcCommentInputHandler(this,'fcModalMentionDD')" class="fc-modal-input">
          <div id="fcModalMentionDD" class="fc-mention-dd" style="display:none;"></div>
        </div>
        <button type="button" class="fc-modal-icon-btn" onclick="document.getElementById('fcModalImgInput').click()" title="Add photo">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
        </button>
        <button type="button" class="fc-modal-icon-btn" onclick="fcModalInsertAt()" title="Mention someone">@</button>
        <button type="button" id="fcModalSubmitBtn" class="fc-modal-submit-btn" disabled onclick="fcModalSubmitComment()">Comment</button>
        <input type="file" id="fcModalImgInput" accept="image/*" style="display:none;" onchange="fcModalHandleImage(this)">
      </div>
    </div>
  </div>`;
  const w = document.createElement('div'); w.id = 'fcModalWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  requestAnimationFrame(() => {
    document.getElementById('fcModalOverlay')?.classList.add('visible');
    document.getElementById('fcModalSheet')?.classList.add('open');
  });
  _fcRenderModalBody();
}
function closeFeedCommentsModal() {
  const ov = document.getElementById('fcModalOverlay'), m = document.getElementById('fcModalSheet');
  if (ov) ov.classList.remove('visible');
  if (m) m.classList.remove('open');
  setTimeout(() => document.getElementById('fcModalWrapper')?.remove(), 200);
}
function _fcRenderModalBody() {
  const arrIdx = window._fcModalArrIdx;
  const post = getFeedPosts()[arrIdx];
  const body = document.getElementById('fcModalBody');
  if (!body || !post) return;
  const commentCount = (post.comments || []).length;
  if (!commentCount) {
    body.innerHTML = `
      <div class="fc-modal-empty">
        <svg width="90" height="90" viewBox="0 0 24 24" fill="none" stroke="var(--border)" stroke-width="1"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
        <div class="fc-modal-empty-text">Be the first to comment</div>
        <button type="button" class="fc-modal-empty-btn" onclick="document.getElementById('fcModalInput')?.focus()">Comment</button>
      </div>`;
    return;
  }
  body.innerHTML = _fcCommentsSectionHtml(post, arrIdx);
}
// @mention autocomplete — triggers on "@" + partial name, matches the real roster.
function fcCommentInputHandler(inputEl, dropdownId) {
  const match = inputEl.value.match(/@([a-zA-Z ]*)$/);
  const dd = document.getElementById(dropdownId);
  if (!dd) return;
  if (!match) { dd.style.display = 'none'; _fcModalUpdateSubmitBtn(); return; }
  const q = match[1].trim().toLowerCase();
  const matches = INTERNS.filter(i => i.name.toLowerCase().includes(q)).slice(0, 5);
  if (!matches.length) { dd.style.display = 'none'; _fcModalUpdateSubmitBtn(); return; }
  dd.innerHTML = matches.map(i => `
    <button type="button" onmousedown="event.preventDefault();fcInsertMention('${inputEl.id}','${dropdownId}','${i.id}')" class="fc-mention-item">
      <span class="fc-mention-avatar">${buildAvatarImg(getAvatarConfig(i.id), 24)}</span>${sanitize(i.name)}
    </button>`).join('');
  dd.style.display = 'block';
  _fcModalUpdateSubmitBtn();
}
function fcInsertMention(inputId, dropdownId, internId) {
  const intern = INTERNS.find(i => i.id === internId); if (!intern) return;
  const input = document.getElementById(inputId);
  input.value = input.value.replace(/@([a-zA-Z ]*)$/, '@' + intern.name + ' ');
  document.getElementById(dropdownId).style.display = 'none';
  input.focus();
  _fcModalUpdateSubmitBtn();
}
function fcModalInsertAt() {
  const input = document.getElementById('fcModalInput'); if (!input) return;
  input.value += (input.value && !input.value.endsWith(' ') ? ' ' : '') + '@';
  input.focus();
  fcCommentInputHandler(input, 'fcModalMentionDD');
}
function fcModalHandleImage(inputEl) {
  const file = inputEl.files[0]; if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const maxW = 600, maxH = 400;
      let w = img.width, h = img.height;
      if (w > maxW) { h = Math.round(h * maxW / w); w = maxW; }
      if (h > maxH) { w = Math.round(w * maxH / h); h = maxH; }
      canvas.width = w; canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      window._fcModalImageBase64 = canvas.toDataURL('image/jpeg', 0.75);
      const pv = document.getElementById('fcModalImgPreview'); if (pv) pv.src = window._fcModalImageBase64;
      const wrap = document.getElementById('fcModalImgPreviewWrap'); if (wrap) wrap.style.display = 'block';
      _fcModalUpdateSubmitBtn();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
  inputEl.value = '';
}
function fcModalClearImage() {
  window._fcModalImageBase64 = null;
  const wrap = document.getElementById('fcModalImgPreviewWrap'); if (wrap) wrap.style.display = 'none';
  _fcModalUpdateSubmitBtn();
}
function _fcModalUpdateSubmitBtn() {
  const btn = document.getElementById('fcModalSubmitBtn'); if (!btn) return;
  const txt = document.getElementById('fcModalInput')?.value.trim();
  const has = !!txt || !!window._fcModalImageBase64;
  btn.disabled = !has;
  btn.classList.toggle('fc-modal-submit-active', has);
}
window.fcModalSubmitComment = function() {
  const arrIdx = window._fcModalArrIdx;
  const input = document.getElementById('fcModalInput');
  const text = input?.value.trim();
  if (!text && !window._fcModalImageBase64) return;
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  if (!post.comments) post.comments = [];
  const commentImage = window._fcModalImageBase64 || null;
  const commentId = 'c' + Date.now() + Math.floor(Math.random()*1000);
  post.comments.push({
    id: commentId,
    userId: currentUser.id, userName: currentUser.name,
    text: text || '', imageBase64: commentImage,
    createdAt: Date.now(), likes: [], pinned: false, parentId: null,
  });
  input.value = '';
  window._fcModalImageBase64 = null;
  document.getElementById('fcModalImgPreviewWrap').style.display = 'none';
  _fcModalUpdateSubmitBtn();
  _fcRenderModalBody();
  fbPut('feedPosts', posts).catch(() => showToast('Failed to sync comment', 'error'));
  // Comment posts optimistically (instant, using the local base64) — the
  // Drive upload happens in the background afterward, and once it resolves
  // the comment is patched in place with the offloaded URL so it doesn't
  // linger as base64 in Firebase.
  if (commentImage) {
    uploadImageToDrive(commentImage, 'comment_' + commentId + '.jpg', 'feed').then(url => {
      const freshPosts = getFeedPosts();
      const freshPost = freshPosts[arrIdx];
      const c = freshPost?.comments?.find(x => x.id === commentId);
      if (c) { c.imageBase64 = url; fbPut('feedPosts', freshPosts).catch(() => {}); }
    }).catch(err => console.error('Drive upload failed for comment image, keeping inline:', err));
  }
};

function fcShowReplyBox(commentId) {
  document.querySelectorAll('[id^="fcReplyBox-"]').forEach(el => { if (el.id !== 'fcReplyBox-'+commentId) el.style.display = 'none'; });
  const box = document.getElementById('fcReplyBox-' + commentId);
  if (box) { box.style.display = box.style.display === 'none' ? 'block' : 'none'; document.getElementById('fcReplyInput-'+commentId)?.focus(); }
}

// Re-renders whichever comment surface is currently active — the new
// intern-facing modal, the admin moderation sheet, or (as a fallback) the
// full feed. Auto-detects context so every comment action below just calls
// this the same way, no caller-side branching needed.
function _fcRefreshAfterCommentAction(arrIdx) {
  if (document.getElementById('fcModalBody')) {
    _fcRenderModalBody();
  } else if (document.getElementById('faCommentsWrapper')) {
    openFeedCommentsSheet(arrIdx);
  } else {
    renderInternFeed(document.getElementById('contentArea'));
  }
}

window.fcSubmitComment = async function(arrIdx, parentId) {
  const inputId = parentId ? `fcReplyInput-${parentId}` : `fcNewComment-${arrIdx}`;
  const input = document.getElementById(inputId);
  const text = input?.value.trim();
  if (!text) return;
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  if (!post.comments) post.comments = [];
  post.comments.push({
    id: 'c' + Date.now() + Math.floor(Math.random()*1000),
    userId: currentUser.id, userName: currentUser.name,
    text, createdAt: Date.now(), likes: [], pinned: false, parentId: parentId || null,
  });
  if (!window._fcExpanded.includes(arrIdx)) window._fcExpanded.push(arrIdx);
  try {
    await fbPut('feedPosts', posts);
    _fcRefreshAfterCommentAction(arrIdx);
  } catch (e) { showToast('Failed to post comment', 'error'); }
};
window.fcStartCommentEdit = function(arrIdx, commentId) {
  window._fcEditingComment = commentId;
  _fcRerenderCommentsInPlace(arrIdx);
};
window.fcCancelCommentEdit = function(arrIdx) {
  window._fcEditingComment = null;
  _fcRerenderCommentsInPlace(arrIdx);
};
function _fcRerenderCommentsInPlace(arrIdx) {
  const wrap = document.getElementById('fcModalBody') || document.getElementById('faCommentsWrapper');
  const post = getFeedPosts()[arrIdx];
  if (wrap && post) wrap.innerHTML = _fcCommentsSectionHtml(post, arrIdx);
}
window.fcSaveCommentEdit = async function(arrIdx, commentId) {
  const val = document.getElementById('fcEditInput-' + commentId)?.value.trim();
  if (!val) return;
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  const c = (post.comments || []).find(x => x.id === commentId);
  if (!c) return;
  c.text = val; c.updatedAt = Date.now();
  window._fcEditingComment = null;
  try { await fbPut('feedPosts', posts); _fcRefreshAfterCommentAction(arrIdx); }
  catch (e) { showToast('Failed to save', 'error'); }
};
window.fcDeleteComment = async function(arrIdx, commentId) {
  if (!confirm('Delete this comment?')) return;
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  post.comments = (post.comments || []).filter(c => c.id !== commentId && c.parentId !== commentId); // also drop its replies
  if (!window._fcExpanded.includes(arrIdx)) window._fcExpanded.push(arrIdx);
  try { await fbPut('feedPosts', posts); _fcRefreshAfterCommentAction(arrIdx); }
  catch (e) { showToast('Failed to delete', 'error'); }
};
window.fcLikeComment = async function(arrIdx, commentId) {
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  const c = (post.comments || []).find(x => x.id === commentId); if (!c) return;
  if (!c.likes) c.likes = [];
  const i = c.likes.indexOf(currentUser.id);
  if (i > -1) c.likes.splice(i, 1); else c.likes.push(currentUser.id);
  if (!window._fcExpanded.includes(arrIdx)) window._fcExpanded.push(arrIdx);
  try { await fbPut('feedPosts', posts); _fcRefreshAfterCommentAction(arrIdx); }
  catch (e) { /* silent — a failed like isn't worth interrupting the user over */ }
};
window.fcPinComment = async function(arrIdx, commentId) {
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  const c = (post.comments || []).find(x => x.id === commentId); if (!c) return;
  c.pinned = !c.pinned;
  if (!window._fcExpanded.includes(arrIdx)) window._fcExpanded.push(arrIdx);
  try { await fbPut('feedPosts', posts); _fcRefreshAfterCommentAction(arrIdx); }
  catch (e) { showToast('Failed', 'error'); }
};

// Admin-only: moderate a single post's comments from the management list
// (kebab menu → "Comments") without needing to be on the intern feed view.
function openFeedCommentsSheet(arrIdx) {
  const post = getFeedPosts()[arrIdx]; if (!post) return;
  const composerHtml = `
    <div style="display:flex;gap:8px;margin-top:14px;align-items:center;border-top:1px solid var(--border);padding-top:14px;">
      <span style="width:28px;height:28px;border-radius:50%;overflow:hidden;flex-shrink:0;background:var(--surface2);">${buildAvatarImg(getAvatarConfig(currentUser.id), 28)}</span>
      <input type="text" id="fcNewComment-${arrIdx}" placeholder="Write a comment…" style="flex:1;font-size:13px;border:1px solid var(--border);border-radius:20px;padding:8px 14px;font-family:inherit;outline:none;background:var(--surface2);color:var(--text);box-sizing:border-box;">
      <button onclick="fcSubmitComment(${arrIdx},null)" style="font-size:12.5px;font-weight:700;color:#4834d4;background:none;border:none;cursor:pointer;flex-shrink:0;">Post</button>
    </div>`;
  const html = `
  <div class="rte-modal-overlay" id="faCommentsOverlay" onclick="closeFeedCommentsSheet()"></div>
  <div class="rte-color-modal" id="faCommentsModal" style="max-height:75vh;overflow-y:auto;">
    <div class="rte-color-modal-title">Comments</div>
    <div id="faCommentsWrapper">${_fcCommentsSectionHtml(post, arrIdx)}</div>
    ${composerHtml}
  </div>`;
  const existing = document.getElementById('faCommentsWrapperOuter');
  if (existing) { document.getElementById('faCommentsWrapper').innerHTML = _fcCommentsSectionHtml(post, arrIdx); return; }
  const w = document.createElement('div'); w.id = 'faCommentsWrapperOuter'; w.innerHTML = html;
  document.body.appendChild(w);
  requestAnimationFrame(() => {
    document.getElementById('faCommentsOverlay')?.classList.add('visible');
    document.getElementById('faCommentsModal')?.classList.add('open');
  });
}
function closeFeedCommentsSheet() {
  const ov = document.getElementById('faCommentsOverlay'), m = document.getElementById('faCommentsModal');
  if (ov) ov.classList.remove('visible');
  if (m) m.classList.remove('open');
  setTimeout(() => document.getElementById('faCommentsWrapperOuter')?.remove(), 200);
}

// ── Intern: Feed view ────────────────────────────────
function renderInternFeed(ca, resetScroll) {
  // TEMP: filter tabs hidden for now per request. Flip to false (or delete
  // this line) to bring them back — nothing else needs to change.
  const HIDE_FEED_TABS = true;
  const prevScrollTop = document.querySelector('.arw-page')?.scrollTop || 0;
  const allPosts = db.feedPosts || [];
  window._feedFilter = HIDE_FEED_TABS ? 'all' : (window._feedFilter || 'all');
  const filter = window._feedFilter;
  let posts = allPosts.filter(p => p.status === 'published');
  if (filter === 'quickpost') posts = posts.filter(p => p.type === 'quickpost');
  else if (filter === 'post') posts = posts.filter(p => p.type === 'post' || !p.type);
  else if (filter === 'poll') posts = posts.filter(p => p.type === 'poll');
  posts = posts.slice().reverse().sort((a,b) => (b.pinned?1:0) - (a.pinned?1:0)); // pinned float to the top

  const totalCount = allPosts.filter(p => p.status === 'published').length;
  const tabs = [
    ['all', 'All'], ['quickpost', 'Posts'], ['post', 'Announcements'], ['poll', 'Poll'],
  ];
  const tabsHtml = tabs.map(([key,label], idx) => {
    const active = filter === key;
    const marginRight = idx < tabs.length - 1 ? '8px' : '0';
    return `<button type="button" onclick="feedSetFilter('${key}')" style="display:inline-block;margin-right:${marginRight};padding:8px 16px;border-radius:8px;border:1.5px solid ${active ? '#4834d4' : '#d1c9b8'};background:${active ? '#4834d4' : '#ffffff'};color:${active ? '#ffffff' : '#3a3a3a'};font-size:12.5px;font-weight:700;font-family:'Inter',sans-serif;cursor:pointer;white-space:nowrap;">${label}</button>`;
  }).join('');

  ca.innerHTML = `
  <div class="arw-page" style="font-family:'Inter',sans-serif;background:linear-gradient(160deg, #fbeee9 0%, #f3e6ee 35%, #e9e6f5 65%, #e1e4f5 100%);">

    <!-- Header -->
    <div class="feed-hd" style="position:relative;z-index:3;">
      <div style="font-size:21px;font-weight:800;color:var(--text);font-family:'Inter',sans-serif;letter-spacing:-.3px;">Feed</div>
      ${totalCount > 0 ? `<span style="font-size:14px;font-weight:400;color:var(--text2);font-family:'Inter',sans-serif;">${totalCount} post${totalCount>1?'s':''}</span>` : ''}
    </div>
    <div style="width:100%;box-sizing:border-box;overflow-x:auto;white-space:nowrap;padding:12px 16px 6px;position:relative;z-index:2;background:#EFE7D8;${HIDE_FEED_TABS ? 'display:none;' : ''}">${tabsHtml}</div>

    <!-- Posts -->
    <div style="padding:10px 0 90px;position:relative;z-index:1;">
      ${posts.length === 0 ? `
        <div style="text-align:center;padding:80px 18px;">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="var(--border)" stroke-width="1.2" style="margin-bottom:12px;"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          <div style="font-size:16px;font-weight:600;color:var(--text);margin-bottom:5px;font-family:'Inter',sans-serif;">Nothing here yet</div>
          <div style="font-size:13px;font-weight:400;color:var(--text2);font-family:'Inter',sans-serif;">Check back soon for updates.</div>
        </div>` :
        posts.map((p) => {
          const arrIdx = allPosts.indexOf(p);
          const authorId = p.authorId != null ? p.authorId : 99;
          // Looks the name up from the current roster every render, rather
          // than trusting the name that was frozen into the post at
          // creation time — so renaming someone updates every post they've
          // ever made, not just new ones.
          const rosterMatch = INTERNS.find(i => i.id === authorId);
          const authorName = rosterMatch ? rosterMatch.name : (p.authorName || 'Zia Hasnain');
          const pinBadge = p.pinned ? `<div style="display:flex;align-items:center;gap:4px;padding:0 18px 6px;"><svg width="11" height="11" viewBox="0 0 24 24" fill="#4834d4" stroke="none"><path d="M12 2l1.5 6L20 9l-5 4 1.5 7L12 16l-4.5 4L9 13 4 9l6.5-1z"/></svg><span style="font-size:11px;font-weight:700;color:#4834d4;">PINNED</span></div>` : '';

          return _fcUnifiedCardHtml(p, arrIdx, authorId, authorName, pinBadge);
        }).join('')}
    </div>
  </div>`;
  _fcCheckTruncation();
  // Every-render scroll handling: a filter switch intentionally starts back
  // at the top (so the header/tabs never appear mid-scroll/clipped), but a
  // like/comment action re-render should stay right where the person was —
  // yanking them back to the top mid-scroll felt jarring and un-native.
  const pageEl = document.querySelector('.arw-page');
  if (pageEl) {
    if (resetScroll) pageEl.scrollTo(0, 0);
    else pageEl.scrollTop = prevScrollTop;
  }
  if (ca && resetScroll) ca.scrollTop = 0;
}
function feedSetFilter(key) {
  window._feedFilter = key;
  renderInternFeed(document.getElementById('contentArea'), true);
}

// One unified card for every post type — Post/Announcement/Question/custom
// tags and Poll all share the exact same layout (avatar+name+role header,
// tag+time row, text-then-image, reaction/comment summary, action row).
// The only difference: Poll and Announcement-tagged posts don't get the
// Like/Save/Share treatment — just Comment — since those are official
// content, not social posts. Everything else (Post/Question/custom tags)
// gets the full treatment.
function _fcUnifiedCardHtml(p, arrIdx, authorId, authorName, pinBadge) {
  const tagLabel = p.type === 'poll' ? 'Poll' : (p.tag || 'Post');
  const isRestricted = p.type === 'poll' || tagLabel.toLowerCase() === 'announcement';

  const headerHtml = `
    <div style="display:flex;align-items:flex-start;gap:10px;padding:14px 18px 0;">
      <span style="width:44px;height:44px;border-radius:50%;overflow:hidden;flex-shrink:0;background:var(--surface2);">${buildAvatarImg(getAvatarConfig(authorId), 44)}</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:14.5px;font-weight:700;color:var(--text);">${sanitize(authorName)} <span style="font-weight:400;color:var(--text2);">• Admin</span></div>
        <div style="display:flex;align-items:center;gap:6px;margin-top:2px;">
          <span style="display:inline-block;padding:2px 8px;border-radius:6px;font-size:10.5px;font-weight:700;background:rgba(72,52,212,.1);color:#4834d4;letter-spacing:.3px;">${sanitize(tagLabel.toUpperCase())}</span>
          <span style="font-size:12.5px;color:var(--text3);">${feedTimeAgo(p.createdAt)}</span>
        </div>
      </div>
    </div>`;

  let textHtml, mediaHtml = '';
  if (p.type === 'poll') {
    const myVote = p.votes && p.votes[currentUser.id];
    const pollClosed = p.pollCloseDate && p.pollCloseDate < _habitToday();
    const showResults = !!myVote || pollClosed;
    textHtml = `<div style="padding:0 18px;margin-top:10px;font-size:15px;font-weight:600;color:var(--text);line-height:1.5;">${sanitize(p.pollQuestion||'')}</div>`;
    mediaHtml = `
      <div style="padding:0 18px;margin-top:12px;">
        ${showResults ? _fpResultsHtml(p, myVote) :
          (p.pollOptions||[]).map(o => `
          <button type="button" onclick="voteFeedPoll(${arrIdx},'${o.id}')" style="display:block;width:100%;text-align:left;padding:12px 14px;margin-bottom:8px;border-radius:12px;border:1.5px solid var(--border);background:var(--surface);color:var(--text);font-size:13.5px;font-weight:600;cursor:pointer;">${sanitize(o.label)}</button>
          `).join('')}
        ${pollClosed ? `<div style="font-size:11.5px;color:var(--text3);">Poll closed</div>` : ''}
      </div>`;
  } else {
    const textId = `fcText-${arrIdx}`;
    textHtml = `
      <div style="padding:0 18px;margin-top:10px;">
        <div id="${textId}" class="fc-post-text-clamp" style="font-size:14.5px;color:var(--text);line-height:1.5;word-break:break-word;overflow-wrap:break-word;">${sanitize(p.description||'')}</div>
        <button type="button" onclick="fcExpandText('${textId}',this)" class="fc-more-btn" style="display:none;background:none;border:none;color:var(--text2);font-size:13px;font-weight:700;cursor:pointer;padding:2px 0;">…more</button>
      </div>`;
    mediaHtml = `
      ${p.imageBase64 ? `
      <div style="padding:12px 18px 0;">
        <img src="${p.imageBase64}" style="width:100%;max-height:320px;object-fit:cover;border-radius:12px;display:block;">
      </div>` : ''}
      ${p.btnLabel ? `
      <div style="padding:14px 18px 0;">
        <a href="${sanitize(p.btnUrl||'#')}" target="_blank" rel="noopener noreferrer"
          style="display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border-radius:14px;border:2px solid #4834d4;color:#4834d4;font-size:13.5px;font-weight:700;text-decoration:none;letter-spacing:.4px;background:transparent;">
          ${sanitize(p.btnLabel).toUpperCase()}
        </a>
      </div>` : ''}`;
  }

  const commentCount = (p.comments||[]).length;
  const iCommented = (p.comments||[]).some(c => c.userId === currentUser.id);
  let actionRowHtml;

  if (isRestricted) {
    // Poll / Announcement: Comment box only — no Like box at all.
    actionRowHtml = `
      <div style="display:flex;padding:12px 18px 16px;">
        <button type="button" onclick="openFeedCommentsModal(${arrIdx})"
          style="display:flex;align-items:center;gap:8px;padding:9px 18px;border-radius:14px;border:2px solid ${iCommented?'#22c55e':'var(--border)'};background:none;cursor:pointer;">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="${iCommented?'#22c55e':'none'}" stroke="${iCommented?'#22c55e':'var(--text2)'}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          <span style="font-size:14px;font-weight:700;color:${iCommented?'#22c55e':'var(--text)'};">${commentCount}</span>
        </button>
      </div>`;
  } else {
    const likes = p.likes || [];
    const iLiked = likes.includes(currentUser.id);
    actionRowHtml = `
      <div style="display:flex;gap:10px;padding:12px 18px 16px;">
        <button type="button" onclick="fcToggleLike(${arrIdx})"
          style="display:flex;align-items:center;gap:8px;padding:9px 18px;border-radius:14px;border:2px solid ${iLiked?'#22c55e':'var(--border)'};background:none;cursor:pointer;">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="${iLiked?'#22c55e':'none'}" stroke="${iLiked?'#22c55e':'var(--text2)'}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
          <span style="font-size:14px;font-weight:700;color:${iLiked?'#22c55e':'var(--text)'};">${likes.length}</span>
        </button>
        <button type="button" onclick="openFeedCommentsModal(${arrIdx})"
          style="display:flex;align-items:center;gap:8px;padding:9px 18px;border-radius:14px;border:2px solid ${iCommented?'#22c55e':'var(--border)'};background:none;cursor:pointer;">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="${iCommented?'#22c55e':'none'}" stroke="${iCommented?'#22c55e':'var(--text2)'}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          <span style="font-size:14px;font-weight:700;color:${iCommented?'#22c55e':'var(--text)'};">${commentCount}</span>
        </button>
      </div>`;
  }

  return `
        <div style="background:var(--surface);margin:0 12px 12px;padding-bottom:4px;border-radius:16px;overflow:hidden;">
          ${pinBadge}
          ${headerHtml}
          ${textHtml}
          ${mediaHtml}
          ${actionRowHtml}
        </div>`;
}

// Shows "…more" only on posts that actually overflow the 3-line clamp —
// short posts never get a pointless "more" link with nothing more to show.
function _fcCheckTruncation() {
  document.querySelectorAll('.fc-post-text-clamp').forEach(el => {
    const btn = el.parentElement?.querySelector('.fc-more-btn');
    if (btn && el.scrollHeight > el.clientHeight + 2) btn.style.display = 'inline-block';
  });
}
function fcExpandText(id, btnEl) {
  const el = document.getElementById(id); if (!el) return;
  el.classList.remove('fc-post-text-clamp');
  if (btnEl) btnEl.style.display = 'none';
}

// ── Reactions: quick-tap Like, long-press for the reaction bubble picker ──
// Simple like toggle for the heart box — replaces the earlier multi-
// reaction long-press picker, which was scrapped in favor of a single
// heart (matching the simpler reference design).
// Optimistic: the local data + re-render happen immediately (instant green
// fill), and the Firebase write fires in the background afterward — it no
// longer waits on the network round-trip before showing the change.
window.fcToggleLike = function(arrIdx) {
  const posts = getFeedPosts();
  const post = posts[arrIdx]; if (!post) return;
  if (!post.likes) post.likes = [];
  const i = post.likes.indexOf(currentUser.id);
  if (i > -1) post.likes.splice(i, 1); else post.likes.push(currentUser.id);
  renderInternFeed(document.getElementById('contentArea'));
  fbPut('feedPosts', posts).catch(() => showToast('Failed to sync like', 'error'));
};
